// Cyrus R1: put a build's hosted resource pack in front of players on ONE server: make sure the managed Nxeon Pack
// Loader is there (ref-counted, lib/cyrus/managed) and upsert this mod's entry in plugins/NxeonPackLoader/packs.json
// (lib/cyrus/packhost/deliver.ts writes it atomically; the plugin reloads it by itself). Removal is the reverse.
//
// OFF behind the existing managed-plugin flag (CYRUS_MANAGED_PLUGINS_REAL=1): with it unset nothing here touches a
// server and the result says so. Turning that flag on (plus the R0 owner steps: migration, catalog seed, the Pack
// Loader jar on the worker host, pack storage) is the only switch. Runs in the worker after the Mods engine installed
// the mod's jar (worker/game-mods.ts), never in a request handler.
import type { GuestFs } from "../../mods/guest-fs";
import { MANAGED_REAL_FLAG } from "../managed/installer";
import { ensureManagedPlugin, releaseManagedPlugin, type ManagedDeps } from "../managed/service";
import { readLoaderConfig, writeLoaderConfig } from "../packhost/deliver";
import { applyPackChange } from "../packhost/loader-config";
import { PACK_ROLE, readBuildAssets } from "./sync";

export const PACK_LOADER_KEY = "nxeon-pack-loader";
export const PACK_DELIVERY_FLAG = MANAGED_REAL_FLAG;

export type DeliverBuild = { id: string; mcVersion: string; result: unknown };
export type DeliverDeps = { managed: ManagedDeps; fs: GuestFs; env?: Record<string, string | undefined>; base?: string };
export type DeliverResult =
  | { ok: true; action: "no_pack" | "switched_off" | "added" | "updated" | "unchanged" | "removed" | "absent"; wrote: boolean; loader?: string; notes: string[] }
  | { ok: false; error: string };

const dependentFor = (projectId: string) => `project:${projectId}`;

export async function deliverBuildPack(serverId: string, build: DeliverBuild, deps: DeliverDeps): Promise<DeliverResult> {
  const a = readBuildAssets(build.result);
  if (!a?.loader || a.status !== "ready") return { ok: true, action: "no_pack", wrote: false, notes: [] };
  if ((deps.env ?? process.env)[PACK_DELIVERY_FLAG] !== "1") {
    return { ok: true, action: "switched_off", wrote: false, notes: [`custom-texture pack delivery is switched off (${PACK_DELIVERY_FLAG} is not 1); the plugin was installed without it`] };
  }
  const loader = a.loader;
  const ens = await ensureManagedPlugin(deps.managed, { serverId, key: PACK_LOADER_KEY, mcVersion: build.mcVersion, dependent: dependentFor(a.projectId) });
  if (!ens.ok) return { ok: false, error: `Nxeon Pack Loader: ${ens.error}` };
  const cur = await readLoaderConfig(deps.fs, deps.base);
  if (!cur.ok) return { ok: false, error: `the server's pack config is invalid, so it was left alone: ${cur.error}` };
  const r = applyPackChange(cur.config, { op: "upsert", namespace: a.namespace, role: PACK_ROLE, sha1: loader.sha1, prompt: loader.prompt, required: loader.required }, {
    urlFor: (sha1) => { if (sha1 !== loader.sha1) throw new Error("pack url requested for another sha1"); return loader.url; },
  });
  if (!r.ok) return { ok: false, error: r.error };
  const wrote = r.changed ? await writeLoaderConfig(deps.fs, r.config, deps.base) : false;
  const notes = [...r.warnings.map((w) => w.message)];
  if (ens.action === "installed" || ens.action === "upgraded") notes.push("the Nxeon Pack Loader was installed; it starts with the next server restart");
  return { ok: true, action: r.action, wrote, loader: ens.action, notes };
}

/** Which project's pack entry to drop: from a build's stored assets, or (a version without a pack) the chain's project. */
export type PackIdent = { namespace: string; projectId: string };
export const packIdentOf = (build: Pick<DeliverBuild, "result">): PackIdent | null => {
  const a = readBuildAssets(build.result);
  return a ? { namespace: a.namespace, projectId: a.projectId } : null;
};

/** The mod (or its pack) left the server: drop its entry, then release the Pack Loader (removed when nothing else needs it). */
export async function removeBuildPack(serverId: string, ident: PackIdent, deps: DeliverDeps): Promise<DeliverResult> {
  if ((deps.env ?? process.env)[PACK_DELIVERY_FLAG] !== "1") return { ok: true, action: "switched_off", wrote: false, notes: [] };
  const cur = await readLoaderConfig(deps.fs, deps.base);
  if (!cur.ok) return { ok: false, error: `the server's pack config is invalid, so it was left alone: ${cur.error}` };
  const r = applyPackChange(cur.config, { op: "remove", namespace: ident.namespace, role: PACK_ROLE }, { urlFor: () => "" });
  if (!r.ok) return { ok: false, error: r.error };
  const wrote = r.changed ? await writeLoaderConfig(deps.fs, r.config, deps.base) : false;
  const rel = await releaseManagedPlugin(deps.managed, { serverId, key: PACK_LOADER_KEY, dependent: dependentFor(ident.projectId) });
  if (!rel.ok) return { ok: false, error: `Nxeon Pack Loader: ${rel.error}` };
  return { ok: true, action: r.action, wrote, loader: rel.action, notes: [] };
}
// Worker glue for Cyrus pack delivery (SERVER ONLY): called by worker/game-mods.ts after the Mods engine changed a
// Cyrus mod on a server, with the guest connection it already holds. With CYRUS_MANAGED_PLUGINS_REAL unset this
// returns null BEFORE any database read or server access, so today's behaviour is unchanged.
import { db } from "../../db";
import type { GuestFs } from "../../mods/guest-fs";
import type { ServerFacts } from "../../mods/types";
import { loadCatalog } from "../managed/catalog";
import { engineManagedInstaller } from "../managed/installer";
import { projectForRootBuild } from "../engine-core/store";
import { deliverBuildPack, packIdentOf, PACK_DELIVERY_FLAG, removeBuildPack, type DeliverDeps, type DeliverResult } from "./deliver";
import { creaturesSwitchedOn, deliverCreatures, removeCreatures, type StoredCreature } from "../creature/deliver";
import { readBuildAssets } from "./sync";

export async function afterCyrusModChange(a: { serverId: string; versionId: string | null; op: "install" | "update" | "remove"; fs: GuestFs; facts: ServerFacts; env?: Record<string, string | undefined> }): Promise<DeliverResult | null> {
  const env = a.env ?? process.env;
  if (env[PACK_DELIVERY_FLAG] !== "1" || !a.versionId) return null;
  const build = await db.modBuild.findUnique({ where: { id: a.versionId }, select: { id: true, mcVersion: true, result: true, rootBuildId: true } });
  if (!build) return null;
  const deps: DeliverDeps = {
    fs: a.fs, env,
    managed: { db, catalog: loadCatalog(), installer: engineManagedInstaller({ env, open: async () => ({ fs: a.fs, server: a.facts }) }) },
  };
  const ident = packIdentOf(build) ?? (await projectForRootBuild(build.rootBuildId ?? build.id).then((p) => (p ? { namespace: p.namespace, projectId: p.id } : null)));
  let r: DeliverResult | null;
  if (a.op === "remove") r = ident ? await removeBuildPack(a.serverId, ident, deps) : null;
  else {
    r = await deliverBuildPack(a.serverId, build, deps);
    // A version without a pack replaced one with a pack: drop the stale entry.
    if (r.ok && r.action === "no_pack" && ident) r = await removeBuildPack(a.serverId, ident, deps);
  }
  // Cyrus R3 creatures: BetterModel + the compiled models. Only with CYRUS_CREATURES=1 as well (fail closed).
  if (creaturesSwitchedOn(env) && ident) {
    const stored = (readBuildAssets(build.result)?.creatures ?? []) as StoredCreature[];
    const c = a.op === "remove"
      ? await removeCreatures({ serverId: a.serverId, mcVersion: build.mcVersion, ...ident }, { managed: deps.managed, fs: a.fs, env })
      : await deliverCreatures({ serverId: a.serverId, mcVersion: build.mcVersion, ...ident, creatures: stored }, { managed: deps.managed, fs: a.fs, env });
    if (!c.ok) return r && r.ok ? { ...r, notes: [...r.notes, `animated creatures not delivered: ${c.error}`] } : { ok: false, error: `animated creatures not delivered: ${c.error}` };
    if (r && !r.ok) return { ok: false, error: `${r.error}${c.restartRequired ? " (animated creatures were delivered; restart the server)" : ""}` };
    const notes = [...(r && r.ok ? r.notes : []), ...c.notes];
    const base: DeliverResult = r && r.ok ? r : { ok: true, action: "no_pack", wrote: false, notes: [] };
    // restart needed for a new BetterModel or changed models: reported through `loader` like a newly placed plugin
    return { ...(base as Extract<DeliverResult, { ok: true }>), notes, ...(c.restartRequired ? { loader: "installed" } : {}) };
  }
  return r;
}
