import { db } from "../lib/db";
import { SANDBOX } from "../lib/sandbox";
import { connectionTarget, serverRootPassword } from "../lib/sftp";
import { INSTALLABLE_FAMILIES, RESOLVABLE_SOURCES } from "../lib/mod-install-support";
import { controlSpec } from "../lib/game-control";
import { MINECRAFT_PLUGIN_UDP_PORTS } from "../lib/games";
import { allocateGameForward } from "../lib/ipam";
import {
  TERRARIA_JOB_TIMEOUT_MS,
  parseTerrariaInstall,
  parseTerrariaRemove,
  terrariaInstallScript,
  terrariaPluginDirShell,
  terrariaRemoveScript,
} from "../lib/terraria-plugins";
import { Client, type ClientChannel, type SFTPWrapper } from "ssh2";
import type { Job } from "@prisma/client";
import { engineInstallerFor } from "../lib/mods/installers";
import { installOrUpdate, uninstall as engineUninstall, setDisabled as engineSetDisabled, loadState, dependencyGraph, type EngineDeps } from "../lib/mods/engine";
import { toggleDecision } from "../lib/mods/toggle-policy";
import { orderPendingByPlan } from "../lib/mods/batch";
import { LocalGuestFs, sandboxGuestRoot, seedSandboxGuest, type GuestFs } from "../lib/mods/guest-fs";
import { safeFetch } from "../lib/mods/safe-fetch";
import { dbMirrorLookup } from "../lib/mods/mirror";
import { catalogFacts, serverFacts, ENGINE_PENDING_STATUSES } from "../lib/mods/facts";
import type { OpResult } from "../lib/mods/types";
import { SshGuestFs } from "./mods-guest-ssh";
import { afterCyrusModChange } from "../lib/cyrus/assets/deliver-worker";
import {
  pickVsRelease,
  vsFileExt,
  VS_BUILTIN_MODIDS,
  type VsRelease,
  KF2_WORKSHOP_ENV,
  updateKf2Ini,
  isWorkshopId,
  gmodWorkshopLua,
  satisfiesSemver,
  pickFicsitVersion,
  type FicsitVersion,
} from "./game-mods-pure";

/**
 * GAME_MOD_SYNC handler — reconcile a game server's installed mods to the desired
 * state recorded in `ServerMod` rows:
 *   - status INSTALLING → fetch + install the mod, then INSTALLED (or FAILED)
 *   - status REMOVING   → remove the mod, then delete the row (or FAILED)
 *
 * Wire into worker/index.ts handlers:  GAME_MOD_SYNC: gameModSync,
 *
 * ENGINE FAMILIES (2026-10-01 — minecraft, valheim, rust, cs2, factorio; see
 * lib/mods/installers/index.ts) go through lib/mods/engine.ts: verified
 * download, dependency resolution, safe placement, guest state file, rollback,
 * plus UPDATING / DISABLING / ENABLING. In SANDBOX they run the SAME pipeline
 * against a fake guest directory (lib/mods/guest-fs.ts LocalGuestFs) — real
 * downloads, real files, no simulated success.
 *
 * Every other family keeps the THREE PATHS below, mirroring game-config's
 * honesty guard so we never tell a customer a mod is installed when nothing
 * was written to their server:
 *  - SANDBOX: simulate (flip INSTALLING→INSTALLED, REMOVING→REMOVED). Dev only.
 *  - REAL (ENABLE_REAL_GAMEMODS=1, not sandbox): install/remove over SSH via the
 *    per-source adapter. Where an adapter isn't implemented yet, the mod is marked
 *    FAILED with a clear reason — never silently "INSTALLED".
 *  - Neither (production, flag off): mark the queued changes FAILED with a plain
 *    message. A change we did NOT apply is a failure and must say so.
 */

const REAL_ENABLED = !SANDBOX && process.env.ENABLE_REAL_GAMEMODS === "1";

async function notify(userId: string, title: string, body?: string, href?: string) {
  try {
    await db.notification.create({ data: { userId, title, body, href } });
  } catch (e) {
    console.error("[game-mods] notify failed", e);
  }
}

export async function gameModSync(job: Job): Promise<void> {
  const serverId = job.serverId;
  if (!serverId) throw new Error("game mod sync: job has no serverId");

  const server = await db.server.findUnique({
    where: { id: serverId },
    include: { osTemplate: true, gamePlan: true, dedicatedIp: true, node: true },
  });
  if (!server) throw new Error(`Server ${serverId} not found`);

  const pending = orderPendingByPlan(
    await db.serverMod.findMany({
      where: { serverId, status: { in: [...ENGINE_PENDING_STATUSES] } },
      include: { mod: true },
      orderBy: { updatedAt: "asc" },
    }),
    job.payload,
  );
  if (pending.length === 0) return;

  const installedNames: string[] = [];
  const removedNames: string[] = [];
  const failedNames: string[] = [];
  const changed: string[] = [];
  let restartRequired = false;
  let depGraph: Record<string, string[]> | null = null;

  // ── engine families (lib/mods/installers/*) — one guest connection per job ──
  let guest: GuestFs | null = null;
  let sshGuest: SshGuestFs | null = null;
  const engineRows = pending.filter((sm) => engineInstallerFor(sm.mod.gameFamily, sm.mod.source));
  const legacyRows = pending.filter((sm) => !engineInstallerFor(sm.mod.gameFamily, sm.mod.source));
  const step = async (text: string, pct: number) => {
    await db.job.update({ where: { id: job.id }, data: { step: text.slice(0, 180), progress: Math.max(0, Math.min(99, pct)) } }).catch(() => {});
  };

  try {
    for (const [n, sm] of engineRows.entries()) {
      const installer = engineInstallerFor(sm.mod.gameFamily, sm.mod.source)!;
      const op = sm.status;
      let result: OpResult;
      // Defense in depth: the portal only queues toggles the vetting allows
      // (lib/mods/toggle-policy.ts); a row that got here any other way is refused.
      const toggleBlocked =
        op === "DISABLING" || op === "ENABLING"
          ? (() => {
              const d = toggleDecision({ family: sm.mod.gameFamily, variant: server.gameVariant ?? null, mod: sm.mod, engine: true });
              return d.allowed ? null : d.reason;
            })()
          : null;
      if (toggleBlocked) {
        result = { ok: false, error: toggleBlocked };
      } else if (!SANDBOX && !REAL_ENABLED) {
        result = { ok: false, error: "Mod installation is being enabled for this game — your change was not applied yet. Our team has been notified." };
      } else {
        try {
          if (!guest) {
            if (SANDBOX) {
              const local = new LocalGuestFs(sandboxGuestRoot(server.id));
              await seedSandboxGuest(local, sm.mod.gameFamily, server.gameVariant ?? null);
              guest = local;
            } else {
              sshGuest = await SshGuestFs.open(server);
              guest = sshGuest;
            }
          }
          const deps: EngineDeps = {
            fs: guest,
            fetcher: safeFetch,
            mirror: dbMirrorLookup((sql, ...args) => db.$queryRawUnsafe(sql, ...args)),
            progress: (text, pct) => step(`${sm.mod.name}: ${text}`, Math.round(((n + pct / 100) / engineRows.length) * 100)),
          };
          const facts = serverFacts(server, sm.mod.gameFamily);
          const cf = catalogFacts(sm.mod, { targetVersionId: sm.targetVersionId });
          result =
            op === "REMOVING" ? await engineUninstall(installer, cf, facts, deps)
            : op === "DISABLING" ? await engineSetDisabled(installer, cf, facts, deps, true)
            : op === "ENABLING" ? await engineSetDisabled(installer, cf, facts, deps, false)
            : await installOrUpdate(installer, cf, facts, deps, op === "UPDATING" ? "update" : "install");
        } catch (e) {
          result = { ok: false, error: e instanceof Error ? e.message : String(e) };
        }
      }

      const label = `${op.toLowerCase()} ${sm.mod.slug}`;
      if (result.ok) {
        restartRequired ||= result.restartRequired;
        changed.push(...result.changed);
        // Cyrus R1: the mod's custom-texture pack (Nxeon Pack Loader + packs.json). A no-op returning null unless
        // CYRUS_MANAGED_PLUGINS_REAL=1; a delivery problem never fails the jar change, it is reported instead.
        if (sm.mod.source === "cyrus" && sm.mod.gameFamily === "minecraft" && guest && (op === "INSTALLING" || op === "UPDATING" || op === "REMOVING")) {
          try {
            const d = await afterCyrusModChange({
              serverId, versionId: op === "REMOVING" ? (sm.versionId ?? null) : (result.versionId ?? null),
              op: op === "REMOVING" ? "remove" : op === "UPDATING" ? "update" : "install", fs: guest, facts: serverFacts(server, "minecraft"),
            });
            if (d && !d.ok) changed.push(`custom textures not delivered: ${d.error}`);
            else if (d?.ok) { changed.push(...d.notes); if (d.loader === "installed" || d.loader === "upgraded") restartRequired = true; }
          } catch (e) {
            console.error(`[game-mods] cyrus pack delivery failed for ${serverId}`, e);
            changed.push("custom textures not delivered (internal error)");
          }
        }
        if (op === "REMOVING") {
          await db.serverMod.delete({ where: { id: sm.id } });
          removedNames.push(sm.mod.name);
        } else {
          await db.serverMod.update({
            where: { id: sm.id },
            data: {
              status: op === "DISABLING" ? "DISABLED" : "INSTALLED",
              version: result.version ?? sm.version ?? null,
              error: null,
              targetVersionId: null,
              // Cyrus rows track the exact build on the server (version history / rollback read it).
              ...(result.versionId && sm.mod.source === "cyrus" ? { versionId: result.versionId, fileName: result.fileName ?? null } : {}),
            },
          });
          installedNames.push(sm.mod.name);
          // Plugins that listen on their own UDP port (Geyser, Simple Voice Chat)
          // are unreachable on a NAT server until that port is forwarded.
          const udp = sm.mod.gameFamily === "minecraft" ? MINECRAFT_PLUGIN_UDP_PORTS[sm.mod.slug] : undefined;
          if (udp && op !== "DISABLING" && !server.dedicatedIp) {
            try {
              const have = await db.portForward.findFirst({ where: { serverId, guestPort: udp.port, protocol: udp.protocol } });
              if (!have) {
                const pub = await allocateGameForward(server.nodeId, serverId, udp.port, udp.protocol);
                await db.job.create({ data: { type: "SYNC_FORWARDS", serverId } });
                changed.push(`forwarded ${udp.port}/${udp.protocol} (public port ${pub})`);
              }
            } catch (e) {
              console.error(`[game-mods] could not forward ${udp.port}/udp for ${serverId}`, e);
            }
          }
        }
        await db.auditLog.create({ data: { userId: server.userId, action: "gameserver.mod.applied", detail: `${serverId} ${label} ${result.version ?? ""} ${result.changed.join("; ")}`.slice(0, 900) } }).catch(() => {});
      } else {
        // A change that was NOT applied is a failure, and the row says what it still is.
        const restingStatus =
          op === "INSTALLING" ? "FAILED"
          : op === "ENABLING" ? "DISABLED"
          : "INSTALLED"; // failed remove/update/disable: whatever was there is still there
        await db.serverMod.update({ where: { id: sm.id }, data: { status: restingStatus, error: result.error.slice(0, 1000), targetVersionId: null } });
        failedNames.push(sm.mod.name);
        await db.auditLog.create({ data: { userId: server.userId, action: "gameserver.mod.failed", detail: `${serverId} ${label}: ${result.error}`.slice(0, 900) } }).catch(() => {});
      }
    }
    // Publish the dependency graph the portal's Installed list reads (which
    // installed mods need which). Read-only; a failure here changes nothing.
    if (guest && engineRows.length) {
      try {
        depGraph = dependencyGraph(await loadState(guest, engineRows[0].mod.gameFamily));
      } catch {
        depGraph = null;
      }
    }
  } finally {
    sshGuest?.close();
  }

  for (const sm of legacyRows) {
    const removing = sm.status === "REMOVING";
    try {
      if (sm.status !== "INSTALLING" && sm.status !== "REMOVING") {
        // Update/enable/disable are engine-only; the portal never queues them
        // for these families. Put the row back rather than leave it stuck.
        await db.serverMod.update({ where: { id: sm.id }, data: { status: sm.status === "ENABLING" ? "DISABLED" : "INSTALLED", error: "That action isn't available for this game." } });
        failedNames.push(sm.mod.name);
        continue;
      }
      if (SANDBOX) {
        // Dev simulation for the pre-engine families only — no VM mutation.
        if (removing) {
          await db.serverMod.delete({ where: { id: sm.id } });
          removedNames.push(sm.mod.name);
        } else {
          await db.serverMod.update({ where: { id: sm.id }, data: { status: "INSTALLED", error: null } });
          installedNames.push(sm.mod.name);
        }
        continue;
      }

