// ModBuild persistence: mirror the build service's status into the DB row and
// keep the finished jar on the primary. Used by the API routes (sync on read,
// while someone watches) and by the worker sweep (so a build finishes even if
// nobody keeps the page open). Plain module: safe in the worker.
import { createHash } from "node:crypto";
import { mkdir, writeFile, rename, readFile } from "node:fs/promises";
import { join } from "node:path";
import type { ModBuild, Prisma } from "@prisma/client";
import { db } from "../db";
import { svcArtifact, svcGet, type ServiceBuild } from "./client";
import { isTerminal, type ModBuildResult, type ModBuildView } from "./types";
import { readCyrusMeta } from "../cyrus/meta";
import { safeSettle } from "../cyrus/tokens/builds";
import { onBuildSettled } from "../cyrus-mods/pages";
import { syncBuildAssets } from "../cyrus/assets/sync";
import { defaultAssetSyncDeps } from "../cyrus/assets/sync-deps";

export const MODBUILD_DIR = process.env.NXEON_MODBUILD_DIR || "/var/lib/nxeon/modbuilds";
export const jarPathFor = (id: string) => join(MODBUILD_DIR, `${id}.jar`);

// A build the service never heard back on for this long is failed (the VM was
// rebuilt, the tunnel down for an hour, ...). Generous: real builds take 1-10 min.
const STALE_MS = 2 * 60 * 60 * 1000;

function toResult(s: ServiceBuild): ModBuildResult {
  return {
    summary: s.summary,
    commands: (s.commands || []) as ModBuildResult["commands"],
    permissions: (s.permissions || []) as ModBuildResult["permissions"],
    config: (s.config || []) as ModBuildResult["config"],
    warnings: s.warnings || [],
    files: s.files || [],
    safety: (s.safety as ModBuildResult["safety"]) || null,
    ...(s.capabilities ? { capabilities: s.capabilities } : {}),
    events: (s.events || []).slice(-150),
    repairs: s.repairs || 0,
    queuePosition: s.queuePosition || 0,
    errorDetail: s.errorDetail ? String(s.errorDetail).slice(0, 6000) : null,
    ai: {
      route: s.route?.class ?? null,
      routeMethod: s.route?.method ?? null,
      routeScore: s.route?.score ?? null,
      calls: (s.aiCalls || []).slice(0, 20).map((c) => ({
        kind: c.kind || "generate", route: c.route ?? null, model: c.model, resolvedModel: c.resolvedModel ?? null,
        costUsd: c.costUsd || 0, turns: c.turns ?? null, durationMs: c.durationMs ?? null,
      })),
    },
  };
}

/** Pull the service's view of one build into its row. Never throws for an unreachable service. */
export async function syncBuild(row: ModBuild): Promise<ModBuild> {
  const out = await syncBuildRow(row);
  // Cyrus tokens: a build that just finished settles its hold (idempotent, never throws).
  if (isTerminal(out.status) && !isTerminal(row.status)) await safeSettle(out);
  return out;
}

async function syncBuildRow(row: ModBuild): Promise<ModBuild> {
  if (isTerminal(row.status)) return row;
  let s: ServiceBuild | null;
  try {
    s = await svcGet(row.id);
  } catch {
    if (Date.now() - row.createdAt.getTime() > STALE_MS) {
      return db.modBuild.update({ where: { id: row.id }, data: { status: "failed", errorCode: "unreachable", error: "We lost contact with the builder while this was running. Please try again.", finishedAt: new Date() } });
    }
    return row;
  }
  if (!s) {
    return db.modBuild.update({ where: { id: row.id }, data: { status: "failed", errorCode: "lost", error: "The builder has no record of this build. Please try again.", finishedAt: new Date() } });
  }
  const data: Prisma.ModBuildUpdateInput = {
    status: s.status,
    attempts: s.attempts || 0,
    costUsd: s.costUsd || 0,
    durationMs: s.durationMs || null,
    pluginName: s.pluginName || row.pluginName,
    version: s.version || row.version,
    error: s.error,
    errorCode: s.errorCode,
    result: toResult(s) as unknown as Prisma.InputJsonValue,
  };
  if (s.status === "succeeded" && s.jar) {
    // Store the jar before flipping the row to succeeded, so "succeeded" always
    // means "downloadable".
    const bytes = await svcArtifact(row.id);
    const sha = createHash("sha256").update(bytes).digest("hex");
    if (sha !== s.jar.sha256) throw new Error("artifact checksum mismatch");
    await mkdir(MODBUILD_DIR, { recursive: true, mode: 0o750 });
    const dest = jarPathFor(row.id);
    await writeFile(dest + ".part", bytes, { mode: 0o640 });
    await rename(dest + ".part", dest);
    Object.assign(data, { jarName: s.jar.name, jarSize: bytes.length, jarSha256: sha, jarPath: dest });
    // Cyrus R1: texture specs that came with the jar -> pack, hosting, Pack Loader entry, revision + asset rows.
    // Before the row flips to succeeded (a DB error throws, so the next sync retries; it is idempotent). Builds
    // without assets skip this entirely (no assetResult from the service).
    if (s.assetResult) {
      const assets = await syncBuildAssets({ id: row.id, userId: row.userId, rootBuildId: row.rootBuildId, mcVersion: row.mcVersion, pluginName: s.pluginName || row.pluginName, jarName: s.jar.name, jarSha256: sha }, s.assetResult, defaultAssetSyncDeps());
      if (assets) data.result = { ...toResult(s), assets } as unknown as Prisma.InputJsonValue;
    }
  }
  if (isTerminal(s.status)) data.finishedAt = s.finishedAt ? new Date(s.finishedAt) : new Date();
  const updated = await db.modBuild.update({ where: { id: row.id }, data });
  // Cyrus mods: the first finished version creates the mod's NxLabs page (private
  // by default); every later version regenerates it. Never fails the build.
  if (updated.status === "succeeded") await onBuildSettled(updated).catch(() => {});
  return updated;
}

export async function readJar(row: ModBuild): Promise<Buffer> {
  if (!row.jarPath || row.status !== "succeeded") throw new Error("no jar");
  return readFile(row.jarPath);
}

/** Worker sweep: advance every in-flight build. */
export async function sweepModBuilds(): Promise<void> {
  const rows = await db.modBuild.findMany({ where: { status: { notIn: ["succeeded", "failed"] } }, take: 20, orderBy: { createdAt: "asc" } });
  for (const r of rows) {
    try { await syncBuild(r); } catch (e) { console.error("[modbuilder] sync failed", r.id, (e as Error).message); }
  }
}

/** The customer never sees which models ran or what they cost. */
function publicResult(r: ModBuildResult | null): ModBuildResult | null {
  if (!r) return null;
  const { ai, ...rest } = r;
  void ai;
  return rest;
}

export function toView(row: ModBuild): ModBuildView {
  return {
    id: row.id,
    status: row.status as ModBuildView["status"],
    prompt: row.prompt,
    changeRequest: row.changeRequest,
    baseBuildId: row.baseBuildId,
    rootBuildId: row.rootBuildId,
    mcVersion: row.mcVersion,
    pluginName: row.pluginName,
    version: row.version,
    error: row.error,
    errorCode: row.errorCode,
    attempts: row.attempts,
    durationMs: row.durationMs,
    jarName: row.jarName,
    jarSize: row.jarSize,
    createdAt: row.createdAt.toISOString(),
    finishedAt: row.finishedAt ? row.finishedAt.toISOString() : null,
    result: publicResult(row.result as unknown as ModBuildResult | null),
    lastInstall: (row.lastInstall as unknown as ModBuildView["lastInstall"]) ?? null,
    cyrus: row.cyrus ? readCyrusMeta(row.cyrus) : null,
  };
}
