// Cyrus Mod Packs (R2): install / update / uninstall a pack AS ONE UNIT. All-or-nothing:
//   validate -> fetch + verify every artifact (and publish resource packs) BEFORE touching the server ->
//   preflight (never overwrite a file the pack does not own) -> snapshot every path the change can touch
//   (backup copies) -> remove dropped members -> place members -> Pack Loader entries -> unit record -> verify.
// Any failure after the snapshot restores the exact previous bytes of every snapshotted path (and removes paths that
// did not exist), then re-verifies the restore and reports it honestly.
// HOST SEAM: everything goes through injected interfaces: `UnitFs` (a GuestFs-shaped subset: Nxeon's SshGuestFs /
// LocalGuestFs satisfy it structurally), `MemberPlacer` (default: staged writes; ./engine-placer.ts places through
// the Mods engine), `ArtifactFetcher` (third-party downloads) and `PackPublisher` (pack hosting). Nothing here
// imports Nxeon code; nothing here is called by any live route or job yet.
import { createHash } from "node:crypto";
import { LOADER_CONFIG_PATH, serializeLoaderConfig, validateLoaderConfig, type LoaderConfig } from "../packhost/loader-config";
import { canonical } from "../conflicts/merge";
import { validateNxPack, type NxPack, type NxPackFile, type NxPackMember } from "./manifest";

export interface UnitFs {
  stat(p: string): Promise<{ type: "file" | "dir"; size: number } | null>;
  readFile(p: string, maxBytes?: number): Promise<Buffer | null>;
  writeFile(p: string, data: Buffer): Promise<void>;
  mkdirp(p: string): Promise<void>;
  rename(from: string, to: string): Promise<void>;
  remove(p: string): Promise<void>;
  list(dir: string): Promise<string[]>;
  copy(from: string, to: string): Promise<void>;
}
export type PlacedFile = { target: string; data: Buffer; sha256: string; role: "plugin" | "datapack" | "config" };
export interface MemberPlacer {
  /** Extra state files the placer itself writes (e.g. the Mods engine's state.json); snapshotted and restored too. */
  readonly statePaths: string[];
  /** Set when this placer must not be used (e.g. a real installer whose switch is off): the unit refuses before touching anything. */
  readonly disabledReason?: string;
  place(m: { member: NxPackMember; files: PlacedFile[] }): Promise<void>;
  remove(m: { memberId: string; targets: string[] }): Promise<void>;
}
export type ArtifactFetcher = (f: NxPackFile) => Promise<Buffer>;
export type PackPublisher = (zip: Buffer, sha1: string) => Promise<{ url: string }>;

export type UnitRecord = { schema: 1; packId: string; versionId: string; manifestSha256: string; files: { path: string; sha256: string; member: string }[]; loaderIds: string[]; installedAt: string };
export type UnitStep = "validate" | "fetch" | "preflight" | "snapshot" | "remove" | "place" | "packloader" | "record" | "verify";
export type RollbackReport = { attempted: boolean; ok: boolean; restored: number; removed: number; mismatches: string[] };
export type UnitResult =
  | { ok: true; action: "installed" | "updated" | "unchanged" | "uninstalled"; record: UnitRecord | null; changed: string[]; restartRequired: boolean }
  | { ok: false; step: UnitStep; error: string; rollback: RollbackReport };

export type UnitDeps = { fs: UnitFs; placer?: MemberPlacer; fetch?: ArtifactFetcher; publish?: PackPublisher; now?: () => Date; recordDir?: string; backupDir?: string };
export const DEFAULT_RECORD_DIR = "/root/.nxeon-cyrus/modpacks";
export const DEFAULT_BACKUP_DIR = "/root/.nxeon-cyrus/modpack-backups";

const sha = (alg: "sha1" | "sha256" | "sha512", b: Buffer) => createHash(alg).update(b).digest("hex");
const NO_ROLLBACK: RollbackReport = { attempted: false, ok: true, restored: 0, removed: 0, mismatches: [] };
const errMsg = (e: unknown) => (e instanceof Error ? e.message : String(e)).slice(0, 400);

/** Staged writes (part file + rename) straight through the fs. */
export function fsPlacer(fs: UnitFs): MemberPlacer {
  return {
    statePaths: [],
    async place({ files }) { for (const f of files) { const part = `${f.target}.nxeon-part`; await fs.writeFile(part, f.data); await fs.rename(part, f.target); } },
    async remove({ targets }) { for (const t of targets) await fs.remove(t); },
  };
}

export function targetPath(path: string, base: string, level: string): string {
  if (path.startsWith("plugins/")) return `${base}/${path}`;
  if (path.startsWith("datapacks/")) return `${base}/${level}/${path}`;
  if (path.startsWith("config/")) return `${base}/plugins/${path.slice("config/".length)}`;
  throw new Error(`unplaceable path ${path}`);
}

async function writeStaged(fs: UnitFs, p: string, data: Buffer) { const part = `${p}.nxeon-part`; await fs.writeFile(part, data); await fs.rename(part, p); }
async function readRecord(fs: UnitFs, p: string): Promise<UnitRecord | null> {
  const b = await fs.readFile(p, 4 * 1024 * 1024);
  if (!b) return null;
  try { const r = JSON.parse(b.toString("utf8")) as UnitRecord; return r && r.schema === 1 && Array.isArray(r.files) ? r : null; } catch { return null; }
}

type Snap = { path: string; existed: boolean; sha256: string | null; backup: string | null };
async function snapshot(fs: UnitFs, paths: string[], dir: string): Promise<Snap[]> {
  const out: Snap[] = [];
  for (const p of [...new Set(paths)].sort()) {
    const st = await fs.stat(p);
    if (!st) { out.push({ path: p, existed: false, sha256: null, backup: null }); continue; }
    if (st.type !== "file") throw new Error(`${p} is a directory; refusing to touch it`);
    const b = await fs.readFile(p);
    if (!b) throw new Error(`${p} could not be read for the backup`);
    const backup = `${dir}${p}`;
    await fs.copy(p, backup);
    const copy = await fs.readFile(backup);
    if (!copy || !copy.equals(b)) throw new Error(`backup of ${p} did not verify`);
    out.push({ path: p, existed: true, sha256: sha("sha256", b), backup });
  }
  return out;
}

async function restore(fs: UnitFs, snaps: Snap[]): Promise<RollbackReport> {
  const rep: RollbackReport = { attempted: true, ok: true, restored: 0, removed: 0, mismatches: [] };
  for (const s of snaps) {
    try {
      await fs.remove(`${s.path}.nxeon-part`).catch(() => {});
      if (s.existed) { await fs.copy(s.backup!, s.path); rep.restored++; }
      else if (await fs.stat(s.path)) { await fs.remove(s.path); rep.removed++; }
    } catch (e) { rep.mismatches.push(`${s.path}: restore failed (${errMsg(e)})`); }
  }
  for (const s of snaps) {
    const b = await fs.readFile(s.path).catch(() => null);
    const now = b ? sha("sha256", b) : null;
    if (now !== s.sha256) rep.mismatches.push(`${s.path}: expected ${s.sha256 ?? "absent"}, found ${now ?? "absent"}`);
  }
  rep.ok = rep.mismatches.length === 0;
  return rep;
}

const stamp = (d: Date) => d.toISOString().replace(/[-:]/g, "").replace(/\.\d+Z$/, "Z");

/** Pack Loader config with this pack's entries replaced (other owners' entries keep their positions). */
function loaderWith(current: LoaderConfig | null, packId: string, entries: { id: string; url: string; sha1: string; required: boolean; role: string }[]): LoaderConfig {
  const owner = `modpack:${packId}`;
  const keep = (current?.packs ?? []).filter((p) => p.owner !== owner && !entries.some((e) => e.id === p.id));
  return { schema: 1, packs: [...keep, ...entries.map((e) => ({ id: e.id, url: e.url, sha1: e.sha1, prompt: "This server's Mod Pack uses a resource pack. Accept it to see the custom content.", required: e.required, owner, role: e.role }))] };
}

export async function installModPackUnit(args: { manifest: unknown; archive: Map<string, Buffer>; base?: string; levelName?: string; deps: UnitDeps }): Promise<UnitResult> {
  const { fs } = args.deps;
  const base = (args.base ?? "/opt/mc").replace(/\/$/, "");
  const level = args.levelName ?? "world";
  const recordPath = `${args.deps.recordDir ?? DEFAULT_RECORD_DIR}`;
  const placer = args.deps.placer ?? fsPlacer(fs);
  const now = (args.deps.now ?? (() => new Date()))();
  const fail = (step: UnitStep, error: string, rollback = NO_ROLLBACK): UnitResult => ({ ok: false, step, error, rollback });

  // 1. validate
  const v = validateNxPack(args.manifest);
  if (!v.ok) return fail("validate", v.errors.map((e) => `${e.path}: ${e.message}`).join("; "));
  const pack: NxPack = v.pack;
  if (!/^[A-Za-z0-9_-]{1,64}$/.test(level)) return fail("validate", "level name is not a plain folder name");
  if (placer.disabledReason) return fail("validate", placer.disabledReason);
  const rec = `${recordPath}/${pack.packId}.json`;
  const manifestSha256 = sha("sha256", Buffer.from(canonical(pack)));

  // 2. fetch + verify everything (no server writes yet), publish resource packs (immutable, content-addressed)
  const placed = new Map<string, PlacedFile[]>();
  try {
    for (const f of pack.embedded) {
      const b = args.archive.get(f.embedded);
      if (!b) throw new Error(`${f.embedded} is missing from the pack archive`);
      if (sha("sha1", b) !== f.hashes.sha1 || sha("sha512", b) !== f.hashes.sha512 || sha("sha256", b) !== f.hashes.sha256 || b.length !== f.fileSize) throw new Error(`${f.path}: embedded bytes do not match the manifest hashes`);
      if (!placed.has(f.member)) placed.set(f.member, []);
      placed.get(f.member)!.push({ target: targetPath(f.path, base, level), data: b, sha256: sha("sha256", b), role: f.role });
    }
    for (const f of pack.files) {
      if (!args.deps.fetch) throw new Error("no artifact fetcher for third-party files");
      const b = await args.deps.fetch(f);
      if (sha("sha1", b) !== f.hashes.sha1 || sha("sha512", b) !== f.hashes.sha512 || b.length !== f.fileSize) throw new Error(`${f.path}: downloaded bytes do not match the manifest hashes`);
      if (!placed.has(f.member)) placed.set(f.member, []);
      placed.get(f.member)!.push({ target: targetPath(f.path, base, level), data: b, sha256: sha("sha256", b), role: f.role });
    }
  } catch (e) { return fail("fetch", errMsg(e)); }
  const loaderEntries: { id: string; url: string; sha1: string; required: boolean; role: string }[] = [];
  try {
    for (const rp of pack.resourcePacks.packs) {
      const b = args.archive.get(rp.embedded);
      if (!b || sha("sha1", b) !== rp.sha1 || sha("sha256", b) !== rp.sha256) throw new Error(`resource pack ${rp.role} is missing or does not match its hashes`);
      if (!args.deps.publish) throw new Error("no pack publisher configured (resource packs need hosting)");
      const { url } = await args.deps.publish(b, rp.sha1);
      if (!/^https:\/\//.test(url)) throw new Error("pack URL must be https");
      loaderEntries.push({ id: rp.id, url, sha1: rp.sha1, required: rp.required, role: rp.role });
    }
  } catch (e) { return fail("fetch", errMsg(e)); }

  // 3. preflight: previous unit record, ownership, idempotency
  const prev = await readRecord(fs, rec);
  const newTargets = [...placed.values()].flat();
  const owned = new Set(prev?.files.map((f) => f.path) ?? []);
  for (const t of newTargets) {
    if (owned.has(t.target)) continue;
    const cur = await fs.readFile(t.target).catch(() => null);
    const st = await fs.stat(t.target);
    if (st?.type === "dir") return fail("preflight", `${t.target} is a folder`);
    if (cur && sha("sha256", cur) !== t.sha256) return fail("preflight", `${t.target} already exists and does not belong to this Mod Pack; nothing was changed`);
  }
  const loaderPath = `${base}/${LOADER_CONFIG_PATH}`;
  let currentLoader: LoaderConfig | null = null;
  if (loaderEntries.length || prev?.loaderIds.length) {
    const raw = await fs.readFile(loaderPath, 1024 * 1024);
    if (raw) {
      let j: unknown;
      try { j = JSON.parse(raw.toString("utf8")); } catch { return fail("preflight", "the server's packs.json is not valid JSON; nothing was changed"); }
      const lv = validateLoaderConfig(j);
      if (!lv.ok) return fail("preflight", `the server's packs.json is invalid (${lv.errors[0].message}); nothing was changed`);
      currentLoader = lv.config;
    }
  }
  const nextLoader = loaderEntries.length || prev?.loaderIds.length ? loaderWith(currentLoader, pack.packId, loaderEntries) : null;
  if (nextLoader) { const lv = validateLoaderConfig(nextLoader, { requireHttps: true }); if (!lv.ok) return fail("preflight", lv.errors.map((e) => e.message).join("; ")); }
  const record: UnitRecord = { schema: 1, packId: pack.packId, versionId: pack.versionId, manifestSha256, files: newTargets.map((t) => ({ path: t.target, sha256: t.sha256, member: [...placed.entries()].find(([, fs2]) => fs2.includes(t))![0] })).sort((a, b) => (a.path < b.path ? -1 : 1)), loaderIds: loaderEntries.map((e) => e.id), installedAt: now.toISOString() };
  if (prev && prev.manifestSha256 === manifestSha256) {
    let intact = true;
    for (const f of prev.files) { const b = await fs.readFile(f.path).catch(() => null); if (!b || sha("sha256", b) !== f.sha256) { intact = false; break; } }
    const loaderOk = !nextLoader || (await fs.readFile(loaderPath).catch(() => null))?.toString("utf8") === serializeLoaderConfig(nextLoader);
    if (intact && loaderOk) return { ok: true, action: "unchanged", record: prev, changed: [], restartRequired: false };
  }

  // 4. snapshot
  const removedTargets = (prev?.files ?? []).filter((f) => !newTargets.some((t) => t.target === f.path));
  const touch = [...newTargets.map((t) => t.target), ...removedTargets.map((f) => f.path), rec, ...(nextLoader ? [loaderPath] : []), ...placer.statePaths];
  const backupDir = `${args.deps.backupDir ?? DEFAULT_BACKUP_DIR}/${stamp(now)}-${pack.packId}`;
  let snaps: Snap[];
  try { snaps = await snapshot(fs, touch, backupDir); } catch (e) { await fs.remove(backupDir).catch(() => {}); return fail("snapshot", errMsg(e)); }

  let step: UnitStep = "remove";
  const changed: string[] = [];
  try {
    // 5. remove members (or files) the new version no longer has
    const byMember = new Map<string, string[]>();
    for (const f of removedTargets) { if (!byMember.has(f.member)) byMember.set(f.member, []); byMember.get(f.member)!.push(f.path); }
    for (const [memberId, targets] of [...byMember.entries()].sort()) { await placer.remove({ memberId, targets }); changed.push(`removed ${memberId}`); }
    // 6. place members in manifest order
    step = "place";
    for (const m of pack.members) {
      const files = placed.get(m.id);
      if (!files?.length) continue;
      await placer.place({ member: m, files }); // idempotent: unchanged files are rewritten with identical bytes
      changed.push(`${prev?.files.some((f) => f.member === m.id) ? "updated" : "installed"} ${m.id} ${m.version}`);
    }
    // 7. Pack Loader entries
    step = "packloader";
    if (nextLoader) { await fs.mkdirp(loaderPath.slice(0, loaderPath.lastIndexOf("/"))); await writeStaged(fs, loaderPath, Buffer.from(serializeLoaderConfig(nextLoader))); }
    // 8. unit record
    step = "record";
    await fs.mkdirp(recordPath);
    await writeStaged(fs, rec, Buffer.from(JSON.stringify(record, null, 2) + "\n"));
    // 9. verify what is on disk now
    step = "verify";
    for (const t of newTargets) { const b = await fs.readFile(t.target); if (!b || sha("sha256", b) !== t.sha256) throw new Error(`${t.target} does not verify after install`); }
    for (const f of removedTargets) if (await fs.stat(f.path)) throw new Error(`${f.path} is still present after removal`);
    if (nextLoader && (await fs.readFile(loaderPath))?.toString("utf8") !== serializeLoaderConfig(nextLoader)) throw new Error("packs.json does not verify after install");
  } catch (e) {
    const rb = await restore(fs, snaps);
    if (rb.ok) await fs.remove(backupDir).catch(() => {});
    return fail(step, `${errMsg(e)}; ${rb.ok ? "the change was rolled back and the previous state verified" : "ROLLBACK INCOMPLETE: the backup is kept at " + backupDir}`, rb);
  }
  await fs.remove(backupDir).catch(() => {});
  return { ok: true, action: prev ? "updated" : "installed", record, changed, restartRequired: newTargets.some((t) => t.role === "plugin") || removedTargets.length > 0 };
}

export async function uninstallModPackUnit(args: { packId: string; base?: string; deps: UnitDeps }): Promise<UnitResult> {
  const { fs } = args.deps;
  const base = (args.base ?? "/opt/mc").replace(/\/$/, "");
  const placer = args.deps.placer ?? fsPlacer(fs);
  const now = (args.deps.now ?? (() => new Date()))();
  const rec = `${args.deps.recordDir ?? DEFAULT_RECORD_DIR}/${args.packId}.json`;
  if (placer.disabledReason) return { ok: false, step: "validate", error: placer.disabledReason, rollback: NO_ROLLBACK };
  const prev = await readRecord(fs, rec);
  if (!prev) return { ok: true, action: "unchanged", record: null, changed: [], restartRequired: false };
  const loaderPath = `${base}/${LOADER_CONFIG_PATH}`;
  let nextLoader: LoaderConfig | null = null;
  if (prev.loaderIds.length) {
    const raw = await fs.readFile(loaderPath, 1024 * 1024);
    if (raw) {
      let j: unknown;
      try { j = JSON.parse(raw.toString("utf8")); } catch { return { ok: false, step: "preflight", error: "the server's packs.json is not valid JSON; nothing was changed", rollback: NO_ROLLBACK }; }
      const lv = validateLoaderConfig(j);
      if (!lv.ok) return { ok: false, step: "preflight", error: "the server's packs.json is invalid; nothing was changed", rollback: NO_ROLLBACK };
      nextLoader = loaderWith(lv.config, args.packId, []);
    }
  }
  const backupDir = `${args.deps.backupDir ?? DEFAULT_BACKUP_DIR}/${stamp(now)}-${args.packId}-uninstall`;
  let snaps: Snap[];
  try { snaps = await snapshot(fs, [...prev.files.map((f) => f.path), rec, ...(nextLoader ? [loaderPath] : []), ...placer.statePaths], backupDir); }
  catch (e) { await fs.remove(backupDir).catch(() => {}); return { ok: false, step: "snapshot", error: errMsg(e), rollback: NO_ROLLBACK }; }
  let step: UnitStep = "remove";
  try {
    const byMember = new Map<string, string[]>();
    for (const f of prev.files) { if (!byMember.has(f.member)) byMember.set(f.member, []); byMember.get(f.member)!.push(f.path); }
    for (const [memberId, targets] of [...byMember.entries()].sort()) await placer.remove({ memberId, targets });
    step = "packloader";
    if (nextLoader) await writeStaged(fs, loaderPath, Buffer.from(serializeLoaderConfig(nextLoader)));
    step = "record";
    await fs.remove(rec);
    step = "verify";
    for (const f of prev.files) if (await fs.stat(f.path)) throw new Error(`${f.path} is still present`);
  } catch (e) {
    const rb = await restore(fs, snaps);
    if (rb.ok) await fs.remove(backupDir).catch(() => {});
    return { ok: false, step, error: `${errMsg(e)}; ${rb.ok ? "rolled back and verified" : "ROLLBACK INCOMPLETE: backup kept at " + backupDir}`, rollback: rb };
  }
  await fs.remove(backupDir).catch(() => {});
  return { ok: true, action: "uninstalled", record: null, changed: prev.files.map((f) => `removed ${f.path}`), restartRequired: true };
}

// Cyrus R2 data pack studio: DELIVERY of a built data pack to a server's world (pure planning + one flagged action).
//
// Where: `<server>/<level-name>/datapacks/nxeon-<namespace>-<name>.zip` (one file per pack; the prefix makes Nxeon's
// packs recognisable and the namespace keeps two mods apart). How: through the existing installer abstraction
// (lib/cyrus/modpack/install.ts `MemberPlacer`; in production `engineMemberPlacer`, the shared Mods engine, so the
// engine's state file knows the file) with staged writes. Then the reload rule (VERIFIED on Paper 1.21.1 .. 26.2 with
// Test Flight: `datapack disable` / `datapack enable` reloads recipes, loot tables, advancements, tags and
// functions without a restart):
//   apply "reload"  -> run `minecraft:reload` once over the console (never Bukkit's /reload, which reloads plugins)
//   apply "restart" -> the pack adds registry content (enchantments, R4 world generation): only a restart loads it;
//                      mark restart-required. World generation additionally only shapes NEW chunks, and its
//                      dimension is reached by the mod's teleport / a command (never "available now").
// Bytes: the emitter is deterministic, so the zip is rebuilt from the spec stored on the CyrusProjectAsset row and
// must hash to the recorded sha256 (no blob storage, nothing public).
// OFF unless CYRUS_DATAPACK_DELIVERY_REAL=1: off, it returns before touching anything (fail closed). A pack with world
// generation is also skipped unless CYRUS_WORLDGEN=1 (with the studio switch), so turning worldgen off stops delivery.
import type { MemberPlacer, PlacedFile } from "../modpack/install";
import { targetPath } from "../modpack/install";
import { buildDataPack } from "./emit";
import { worldgenOn } from "./route";

export const DATAPACK_DELIVERY_FLAG = "CYRUS_DATAPACK_DELIVERY_REAL";
export const RELOAD_COMMAND = "minecraft:reload";

export type DeliveryPlan = { file: string; relPath: string; apply: "reload" | "restart"; commands: string[]; notes: string[]; /** R4: the pack's own dimensions (reached by teleport / command) */ dimensions?: string[] };

/** worldgen: the pack's world generation summary (dimensions) when it has any. */
export function planDataPackDelivery(p: { namespace: string; name: string; apply: "reload" | "restart"; worldgen?: { dimensions: string[] } | null }): DeliveryPlan {
  const file = `nxeon-${p.namespace}-${p.name}.zip`;
  const wg = p.worldgen ?? null;
  const dims = wg?.dimensions ?? [];
  return {
    file, relPath: `datapacks/${file}`, apply: p.apply,
    commands: p.apply === "reload" ? [RELOAD_COMMAND] : [],
    notes: wg
      ? [
        "This data pack adds world generation, which only loads when the server starts: Nxeon restarts the server once (a reload is not enough).",
        "Only NEW chunks are generated with it; chunks that already exist never change.",
        ...(dims.length ? [`Players reach ${dims.join(", ")} with the mod's teleport command (or /execute in ${dims[0]} run tp @s 0 120 0); there is no portal, and it is not there until the restart.`] : []),
        "The first start after installing takes a few seconds longer while the server prepares the new dimension.",
      ]
      : p.apply === "restart"
        ? ["This data pack adds enchantments (registry content), which only load when the server starts: restart the server once."]
        : ["Recipes, loot tables, advancements, tags and functions load with minecraft:reload; no restart is needed."],
    ...(wg ? { dimensions: dims } : {}),
  };
}

/** Rebuild the zip from a stored asset's provenance and prove it is the same bytes that were checked at build time. */
export function rebuildForDelivery(prov: { spec?: unknown; version?: unknown; packSha256?: unknown; worldgen?: unknown }, namespace: string): { ok: true; zip: Buffer; sha256: string; apply: "reload" | "restart"; name: string; worldgen?: { dimensions: string[] } } | { ok: false; error: string } {
  if (typeof prov.version !== "string" || typeof prov.packSha256 !== "string") return { ok: false, error: "the asset has no recorded version or pack hash" };
  const b = buildDataPack(prov.spec, { version: prov.version, namespace, worldgen: prov.worldgen === true });
  if (!b.ok) return { ok: false, error: `the stored spec no longer builds: ${b.errors[0] ?? "?"}` };
  if (b.pack.sha256 !== prov.packSha256) return { ok: false, error: `rebuilt pack ${b.pack.sha256.slice(0, 12)} differs from the recorded ${prov.packSha256.slice(0, 12)} (emitter changed?)` };
  return { ok: true, zip: b.pack.zip, sha256: b.pack.sha256, apply: b.pack.apply, name: b.pack.name, ...(b.pack.worldgen ? { worldgen: { dimensions: b.pack.worldgen.dimensions } } : {}) };
}

export type DeliveryInput = { projectId: string; revisionId: string; namespace: string; name: string; version: string; zip: Buffer; sha256: string; apply: "reload" | "restart"; worldgen?: { dimensions: string[] } };
export type DeliveryResult =
  | { ok: true; placed: string; plan: DeliveryPlan; restartRequired: boolean }
  | { ok: false; skipped: true; reason: string }
  | { ok: false; skipped?: false; error: string };

/**
 * Place one data pack on a server. `runConsole` sends ONE console command (the host's RCON/console seam); absent, the
 * reload is left to the caller (reported in plan.commands). Never deletes other packs; a new version of the same pack
 * replaces its own file only.
 */
export async function deliverDataPack(
  input: DeliveryInput,
  deps: { placer: MemberPlacer; base?: string; level?: string; runConsole?: (cmd: string) => Promise<void>; env?: Record<string, string | undefined> },
): Promise<DeliveryResult> {
  const env = deps.env ?? process.env;
  if (env[DATAPACK_DELIVERY_FLAG] !== "1") return { ok: false, skipped: true, reason: `data pack delivery is switched off (${DATAPACK_DELIVERY_FLAG} is not 1); nothing was changed` };
  if (input.worldgen && !worldgenOn(env)) return { ok: false, skipped: true, reason: "this data pack has world generation and world generation is switched off (CYRUS_WORLDGEN); nothing was changed" };
  if (input.worldgen && input.apply !== "restart") return { ok: false, error: "a data pack with world generation must be applied with a restart" };
  if (deps.placer.disabledReason) return { ok: false, skipped: true, reason: deps.placer.disabledReason };
  const plan = planDataPackDelivery({ namespace: input.namespace, name: input.name, apply: input.apply, worldgen: input.worldgen ?? null });
  const target = targetPath(plan.relPath, deps.base ?? "/opt/mc", deps.level ?? "world");
  const file: PlacedFile = { target, data: input.zip, sha256: input.sha256, role: "datapack" };
  try {
    await deps.placer.place({ member: { id: `dp-${input.name}`.slice(0, 64), kind: "datapack", origin: "cyrus", label: `${input.name} (Cyrus data pack)`, version: input.sha256.slice(0, 12), project: { projectId: input.projectId, revisionId: input.revisionId, namespace: input.namespace } }, files: [file] });
  } catch (e) { return { ok: false, error: `placing ${plan.file} failed: ${(e as Error).message}` }; }
  if (plan.apply === "reload" && deps.runConsole) {
    try { await deps.runConsole(RELOAD_COMMAND); } catch (e) { return { ok: false, error: `${plan.file} is placed but ${RELOAD_COMMAND} failed: ${(e as Error).message}; it loads on the next restart` }; }
  }
  return { ok: true, placed: target, plan, restartRequired: plan.apply === "restart" };
}
// A MemberPlacer that places Mod Pack members through Nxeon's shared Mods engine (lib/mods/engine.ts), so the
// engine's state file records every jar/datapack the pack put on the server (the Mods tab and later engine runs then
// know these files are Nxeon's). Same imports as lib/cyrus/managed/installer.ts already uses (no new Nxeon coupling).
// The unit installer (./install.ts) snapshots the engine's state.json with everything else, so a failed pack install
// also undoes the engine's bookkeeping. OFF unless CYRUS_MODPACK_INSTALL_REAL=1; off, the unit refuses before
// touching the server. Must run where the engine runs (the worker, under its per-server lock). Not wired anywhere yet.
import { installOrUpdate, uninstall, STATE_PATH } from "../../mods/engine";
import { minecraftInstaller } from "../../mods/installers/minecraft";
import type { CatalogFacts, FamilyInstaller, Resolution, ServerFacts } from "../../mods/types";
import type { GuestFs } from "../../mods/guest-fs";
import { FetchError } from "../../mods/safe-fetch";
import type { MemberPlacer, PlacedFile } from "./install";

export const MODPACK_SOURCE = "cyrus-modpack";
export const MODPACK_REAL_FLAG = "CYRUS_MODPACK_INSTALL_REAL";
const noNetwork = async (): Promise<never> => { throw new FetchError("Mod Pack members never download inside the engine (fetched and verified first)", "host"); };

const facts = (packId: string, memberId: string, label: string): CatalogFacts => ({
  id: `modpack:${packId}:${memberId}`, gameFamily: "minecraft", slug: `${packId}-${memberId}`, name: label, source: MODPACK_SOURCE, sourceId: `${packId}:${memberId}`,
  url: null, category: "library", appliesToVariant: null, loaders: ["paper", "purpur"], gameVersions: [], serverSide: "required",
});

function resolution(packId: string, memberId: string, label: string, version: string, f: PlacedFile): Resolution {
  const filename = f.target.slice(f.target.lastIndexOf("/") + 1);
  return {
    packages: [{
      key: `${MODPACK_SOURCE}:${packId}:${memberId}`, name: label, version, versionId: `${packId}:${version}`,
      file: { url: `modpack://${packId}/${memberId}/${filename}`, filename, size: f.data.length, hashes: { sha256: f.sha256 } },
      placement: f.role === "datapack" ? "datapack" : "plugin-jar", requires: [], incompatible: [], prefetched: f.data, root: true,
    }],
    notes: [],
  };
}

export function engineMemberPlacer(deps: { fs: GuestFs; server: ServerFacts; packId: string; env?: Record<string, string | undefined> }): MemberPlacer {
  const env = deps.env ?? process.env;
  const off = env[MODPACK_REAL_FLAG] !== "1";
  const fam = (r: Resolution): FamilyInstaller => ({ ...minecraftInstaller, sources: [MODPACK_SOURCE], resolve: async () => r, legacyPaths: () => [] });
  return {
    statePaths: [STATE_PATH],
    ...(off ? { disabledReason: `Mod Pack installs through the Mods engine are switched off (${MODPACK_REAL_FLAG} is not 1); nothing was changed` } : {}),
    async place({ member, files }) {
      if (off) throw new Error("switched off");
      const primary = files.filter((f) => f.role !== "config");
      if (primary.length !== 1) throw new Error(`${member.id}: expected exactly one jar or datapack, got ${primary.length}`);
      const r = await installOrUpdate(fam(resolution(deps.packId, member.id, member.label, member.version, primary[0])), facts(deps.packId, member.id, member.label), deps.server, { fs: deps.fs, fetcher: noNetwork }, "update");
      if (!r.ok) throw new Error(r.error);
      const placedAt = r.fileName;
      if (placedAt && !primary[0].target.endsWith(`/${placedAt}`)) throw new Error(`${member.id}: the engine placed ${placedAt}, expected ${primary[0].target}`);
      for (const c of files.filter((f) => f.role === "config")) { const part = `${c.target}.nxeon-part`; await deps.fs.writeFile(part, c.data); await deps.fs.rename(part, c.target); }
    },
    async remove({ memberId, targets }) {
      if (off) throw new Error("switched off");
      const stub = resolution(deps.packId, memberId, memberId, "0", { target: "/x", data: Buffer.alloc(0), sha256: "0".repeat(64), role: "plugin" });
      const r = await uninstall(fam(stub), facts(deps.packId, memberId, memberId), deps.server, { fs: deps.fs, fetcher: noNetwork });
      if (!r.ok) throw new Error(r.error);
      for (const t of targets) if (await deps.fs.stat(t)) await deps.fs.remove(t); // config files (the engine removes only what it placed)
    },
  };
}
// The interface a future Mod Pack UI / worker job uses (R2). One injectable HOST SEAM: Cyrus never imports Nxeon to
// reach a server, a download, pack hosting or Test Flight; Nxeon (today) or a standalone host API (later) implements
// `CompositionHost`. Mod Packs and conflict checks are NOT plan-gated, so the host needs no plan or user lookup here.
// Nothing calls this yet: no route, job or UI is wired (docs "Cyrus composition (R2)").
import { detectConflicts } from "../conflicts/engine";
import { inventoryEntries } from "../conflicts/normalize";
import type { ConflictReport, ModEntry } from "../conflicts/types";
import { scanServer } from "../inventory/scan";
import type { InventoryReport, ReadOnlyServerFs } from "../inventory/types";
import type { TestFlightReport, TestFlightSpec, TestFlightSummary } from "../testflight/types";
import { buildModPack, type BuildInput, type BuildOk, type BuildFail } from "./builder";
import { mergeDynamic, planDynamicChecks, type DynamicMember, type DynamicResult, type FlightOutcome } from "./dynamic";
import { installModPackUnit, uninstallModPackUnit, type ArtifactFetcher, type MemberPlacer, type PackPublisher, type UnitFs, type UnitResult } from "./install";

export interface CompositionHost {
  /** Read-only view of one server (the inventory never writes). */
  openServerReadOnly(serverId: string): Promise<{ fs: ReadOnlyServerFs; base: string; close?: () => void }>;
  /** Writable view + the placer to use (Mods-engine backed in Nxeon). Called only from a worker job under the server lock. */
  openServerForInstall(serverId: string, packId: string): Promise<{ fs: UnitFs; base: string; levelName: string; placer: MemberPlacer; close?: () => void }>;
  fetchArtifact: ArtifactFetcher;
  publishPack: PackPublisher;
  /** One Test Flight (node-2, one at a time; the host retries "busy" with backoff). */
  runFlight?: (spec: TestFlightSpec) => Promise<{ report: TestFlightReport; summary: TestFlightSummary }>;
}

/** Server Doctor / inventory: what is on the server, read-only. */
export async function inspectServer(host: CompositionHost, serverId: string): Promise<InventoryReport> {
  const s = await host.openServerReadOnly(serverId);
  try { return await scanServer(s.fs, { base: s.base }); } finally { s.close?.(); }
}

/** Conflicts of new candidates against each other and against what the server already runs. */
export function checkAgainstServer(inv: InventoryReport, candidates: ModEntry[], opts: { modPack?: boolean } = {}): ConflictReport {
  const { mods, ctx } = inventoryEntries(inv);
  return detectConflicts([...candidates, ...mods], { ...ctx, modPack: opts.modPack });
}

/** Build (static), then optionally fly the plan and rebuild with the dynamic evidence in the compatibility matrix. */
export async function buildAndVerify(host: CompositionHost, input: BuildInput, flight?: { mcVersions: string[]; members: DynamicMember[] }): Promise<{ build: BuildOk | BuildFail; dynamic: DynamicResult | null }> {
  const first = await buildModPack(input);
  if (!first.ok || !flight || !host.runFlight) return { build: first, dynamic: null };
  const plan = planDynamicChecks({ mcVersions: flight.mcVersions, members: flight.members, report: first.report });
  const outcomes: FlightOutcome[] = [];
  for (const p of plan) { // strictly sequential (node-2 rule)
    try { const r = await host.runFlight(p.spec); outcomes.push({ key: p.key, report: r.report, summary: r.summary }); }
    catch (e) { outcomes.push({ key: p.key, report: null, summary: null, error: (e as Error).message }); }
  }
  const dynamic = mergeDynamic(first.report, plan, outcomes, flight.members);
  return { build: await buildModPack({ ...input, dynamic }), dynamic };
}

export async function installPack(host: CompositionHost, serverId: string, built: BuildOk): Promise<UnitResult> {
