  try {
    return await installModPackUnit({ manifest: built.manifest, archive: new Map(built.archive.map((f) => [f.path, f.data])), base: s.base, levelName: s.levelName, deps: { fs: s.fs, placer: s.placer, fetch: host.fetchArtifact, publish: host.publishPack } });
