/** Get-or-create the row and lock it for this transaction. A fresh row starts as `removed` with no dependents. */
async function lockRow(tx: Tx, serverId: string, key: string, family: string): Promise<RowRec> {
  // INSERT .. ON CONFLICT DO NOTHING: racing first calls never raise (a unique violation would abort the transaction).
  await tx.$executeRaw`INSERT INTO "CyrusServerManagedPlugin" ("id","serverId","key","family","status","dependents","refCount","createdAt","updatedAt")
    VALUES (${"csmp_" + randomUUID().replace(/-/g, "")}, ${serverId}, ${key}, ${family}, 'removed', '[]'::jsonb, 0, now(), now())
    ON CONFLICT ("serverId","key") DO NOTHING`;
  const rows = await tx.$queryRaw<RowRec[]>`SELECT "id","status","version","sha256","family","dependents","refCount" FROM "CyrusServerManagedPlugin" WHERE "serverId" = ${serverId} AND "key" = ${key} FOR UPDATE`;
