  if (plan.kind === "busy") return { ok: false, code: "busy", error: "this managed plugin is being changed right now; try again shortly" };
  if (plan.kind === "noop") return { ok: true, action: "not_held", refCount: plan.dependents.length };
  if (plan.kind === "decRef") return { ok: true, action: "ref_dropped", refCount: plan.dependents.length };

