/**
 * Cyrus mods through the shared mods engine (source "cyrus").
 *
 * A Cyrus mod is a Paper plugin jar built by Cyrus (ModBuild, jar stored on the
 * primary under /var/lib/nxeon/modbuilds). Routing its installs through
 * lib/mods/engine.ts — instead of the old direct copy — means the guest state
 * file records exactly which jar Nxeon placed, so the Mods tab can list it,
 * switch it off/on, update it, roll it back and uninstall it like any
 * catalogue plugin (backups, staged write, rollback included).
 *
 * GameMod row: gameFamily "minecraft", source "cyrus", sourceId = the chain's
 * rootBuildId, active=false (never listed in the catalogue/store), created by
 * lib/cyrus-mods/registry.ts. The version placed is CatalogFacts.targetVersionId
 * (a ModBuild id, for update/rollback), else the chain's current version.
 *
 * The jar never leaves the primary over the network: it is read from disk and
 * handed to the engine as a prefetched package (sha256 checked against the
 * stored ModBuild.jarSha256).
 */
import { createHash } from "node:crypto";
import type { CatalogFacts, InstallerCtx, Resolution } from "../types";

export const CYRUS_SOURCE = "cyrus";
/** Generated plugins target the Paper API (Adventure etc.); Spigot/Bukkit can't load them, Folia isn't safe. */
export const CYRUS_VARIANTS = ["paper", "purpur"];

export type CyrusJar = {
  build: { id: string; version: string | null; pluginName: string | null; jarName: string; jarSha256: string | null; mcVersion: string };
  /** Display name of the mod (page title). */
  name: string;
  /** Unique package version within the chain (version string, disambiguated when two versions share one). */
  packageVersion: string;
  bytes: Buffer;
};

/** Where jars come from. Default: the DB + jar store (./../../cyrus-mods/registry). Tests swap it. */
export type CyrusJarSource = (args: { rootBuildId: string; targetBuildId: string | null; serverId: string }) => Promise<CyrusJar | { error: string }>;

let source: CyrusJarSource | null = null;
export function setCyrusJarSource(fn: CyrusJarSource | null) {
  source = fn;
}
async function jarSource(): Promise<CyrusJarSource> {
  if (source) return source;
  const m = await import("../../cyrus-mods/registry");
  return m.loadCyrusJar;
}

/** plugins/<Name>/ folder name for a plugin name (null when nothing safe is left: never back up plugins/ itself). */
export function configDir(pluginName: string | null): string | null {
  const n = (pluginName ?? "").replace(/[^A-Za-z0-9_-]/g, "");
  return n.length ? n : null;
}

export const cyrusPackageKey = (rootBuildId: string) => `cyrus:${rootBuildId}`;

export async function resolveCyrus(mod: CatalogFacts, ctx: InstallerCtx): Promise<Resolution | { error: string }> {
