}

export function resourcePackEntry(name: string, files: { path: string; data: Buffer }[], origin: ModEntry["origin"], opts: { id?: string; cyrus?: ModEntry["cyrus"]; changed?: boolean } = {}): ModEntry {
  return { id: opts.id ?? `${origin}:resourcepack:${name}`, label: `resource pack ${name}`, kind: "resourcepack", origin, cyrus: opts.cyrus ?? null, changed: opts.changed, resourcePack: indexResourcePack(name, files) };
}

/** A candidate jar given as bytes (a Cyrus build or a third-party download). */
export function candidateJar(file: string, bytes: Buffer, opts: { id?: string; cyrus?: ModEntry["cyrus"]; changed?: boolean; budgets?: ModEntry["budgets"] } = {}): ModEntry {
  return pluginEntry(inspectJar(file, `plugins/${file}`, bytes), "candidate", { changed: true, ...opts });
}

/** Everything the inventory found, as server-origin entries, plus the context for the engine. */
export function inventoryEntries(inv: InventoryReport, opts: { exclude?: (path: string) => boolean } = {}): { mods: ModEntry[]; ctx: ConflictContext } {
  const mods: ModEntry[] = [];
  for (const p of inv.plugins) if (!opts.exclude?.(p.path)) mods.push(pluginEntry(p, "server"));
  for (const d of inv.datapacks.folder) if (!opts.exclude?.(`datapacks/${d.name}`)) mods.push(datapackEntry(d, "server"));
  return { mods, ctx: { mcVersion: inv.software.mcVersion, software: inv.software.name, packOwners: inv.resourcePackOwners } };
}
export type PackChange =
  | { op: "upsert"; namespace: string; role: string; sha1: string; prompt?: string; required?: boolean; owner?: string }
  | { op: "remove"; namespace: string; role: string };
/** What the server inventory knows (data, read elsewhere): installed plugin names, current server.properties. */
export type PackInventory = { plugins?: string[]; serverProperties?: Record<string, string> };

export type PackChangeResult =
  | { ok: true; config: LoaderConfig; action: "added" | "updated" | "unchanged" | "removed" | "absent"; id: string; changed: boolean; warnings: Issue[] }
  | { ok: false; code: string; error: string };

/**
 * Apply one pack change to the loader config. Existing entries keep their position (pack stacking order is the
 * list order); new ones are appended. The URL is always the immutable `/p/<sha1>.zip` for the sha1.
 */
export function applyPackChange(current: LoaderConfig | null, change: PackChange, ctx: { urlFor: (sha1: string) => string }, inv: PackInventory = {}): PackChangeResult {
  let id: string;
  try { id = packIdFor(change.namespace, change.role); } catch (e) { return { ok: false, code: "bad_identity", error: (e as Error).message }; }
  const base: LoaderConfig = current ? { schema: 1, packs: current.packs.map((p) => ({ ...p })) } : { schema: 1, packs: [] };
  const v = validateLoaderConfig(base);

/** Current config on the server: null when there is none; an error when the file exists but is invalid. */
export async function readLoaderConfig(fs: GuestFs, base = MC_BASE): Promise<{ ok: true; config: LoaderConfig | null } | { ok: false; error: string }> {
  const raw = await fs.readFile(loaderConfigGuestPath(base), 1024 * 1024);
  if (!raw) return { ok: true, config: null };
  let json: unknown;
  try { json = JSON.parse(raw.toString("utf8")); } catch { return { ok: false, error: "packs.json on the server is not valid JSON" }; }
  const v = validateLoaderConfig(json);
  return v.ok ? { ok: true, config: v.config } : { ok: false, error: v.errors.map((e) => e.message).join("; ") };
}

/** Write the config atomically (temp file + rename). Returns false when the bytes on the server are already identical. */
export async function writeLoaderConfig(fs: GuestFs, config: LoaderConfig, base = MC_BASE): Promise<boolean> {
  const v = validateLoaderConfig(config, { requireHttps: true });
  if (!v.ok) throw new Error(`refusing to write an invalid pack config: ${v.errors.map((e) => e.message).join("; ")}`);
  const dest = loaderConfigGuestPath(base);
  const text = Buffer.from(serializeLoaderConfig(config));
  const cur = await fs.readFile(dest, 1024 * 1024);
  if (cur && cur.equals(text)) return false;
  const dir = dest.slice(0, dest.lastIndexOf("/"));
  await fs.mkdirp(dir);
  const tmp = `${dest}.nxeon-part`;
  await fs.writeFile(tmp, text);
  await fs.rename(tmp, dest);
  await fs.chownLike(`${base}/server.properties`, [dir, dest]);
  return true;
}

