// Cyrus R5 "engine release record", build-service half: the facts only the build service knows about how ONE build was
// produced (prompt + section versions, API sheet + rules hashes, scanner hash + profile, registry hash, JDK, classpath
// hash, allowlisted dependencies used, image version). Attached to the build record as `release` when it succeeds
// (finish() in server.js) and summarised on /health. The portal (lib/cyrus/engine-core/release.ts) re-checks it and
// combines it with what the portal knows (jar sha256 it re-hashed, its own registry hash).
// Plain Node, no deps. Every fact is optional: anything that cannot be read is null (never guessed).
"use strict";
const fs = require("fs");
const path = require("path");
const crypto = require("crypto");
const { execFileSync } = require("child_process");

const RELEASE_SCHEMA = 1;
const IMAGE_VERSION = "0.5";
const sha256 = (b) => crypto.createHash("sha256").update(b).digest("hex");

const fileCache = new Map();
/** sha256 of a file, cached by path + mtime + size; null when it cannot be read. */
function hashFile(p) {
  if (!p) return null;
  let st;
  try { st = fs.statSync(p); } catch { return null; }
  if (!st.isFile()) return null;
  const key = `${p}:${st.mtimeMs}:${st.size}`;
  if (fileCache.has(key)) return fileCache.get(key);
  let h = null;
  try { h = sha256(fs.readFileSync(p)); } catch { h = null; }
  fileCache.set(key, h);
  return h;
}

const jdkCache = new Map();
/** `javac -version` output for one javac binary (cached per process; null when it does not run). */
function javacVersion(javac) {
  if (jdkCache.has(javac)) return jdkCache.get(javac);
  let v = null;
  try {
    const out = execFileSync(javac, ["-version"], { timeout: 15000, stdio: ["ignore", "pipe", "pipe"], encoding: "utf8" });
    v = String(out).trim().slice(0, 80) || null;
  } catch (e) {
    const err = e && e.stderr ? String(e.stderr).trim() : "";
    v = /^javac \d/.test(err) ? err.slice(0, 80) : null;
  }
  jdkCache.set(javac, v);
  return v;
}

/** Service-wide facts (for /health): image, scanner, rules, registry, sheets. */
function serviceFacts(o) {
  const dir = o.dir || __dirname;
  return {
    schema: RELEASE_SCHEMA,
    image: IMAGE_VERSION,
    scannerSha256: hashFile(path.join(dir, "scan.js")),
    rulesSha256: hashFile(o.rulesFile || path.join(dir, "rules", "failure-rules.json")),
    netPolicySha256: hashFile(path.join(dir, "rules", "net-policy.json")),
    registrySha256: hashFile(o.registryFile || null),
    depsManifestVersion: o.depsManifestVersion || null,
  };
}

/**
 * The per-build record. `rec` is the build record (promptVersion, knowledge, mcVersion, scanProfile, importDeps, assets);
 * `o` carries what server.js knows: { dir, rulesFile, rulesVersion, registryFile, cpDir, tc: { release, javac }, deps:
 * [{ id, file, sha256 }], sections: { assets, datapack, design, itemmodel }, sheetsOn, model }.
 */
function releaseFor(rec, o) {
  const dir = o.dir || __dirname;
  const sheet = o.sheetsOn === false ? null : path.join(dir, "sheets", `${rec.mcVersion}.md`);
  const sheetSha = hashFile(sheet);
  const facts = serviceFacts(o);
  const sections = {};
  for (const [k, v] of Object.entries(o.sections || {})) if (typeof v === "string" && v) sections[k] = v;
  return {
    schema: RELEASE_SCHEMA,
    service: "nxeon-modbuilder",
    image: IMAGE_VERSION,
    promptVersion: rec.promptVersion || null,
    sections,
    knowledge: rec.knowledge || null,
    sheets: sheetSha ? [{ name: `paper-api-${rec.mcVersion}.md`, sha256: sheetSha }] : [],
    rules: { version: o.rulesVersion || null, sha256: facts.rulesSha256 },
    scanner: { sha256: facts.scannerSha256, profile: rec.scanProfile === "attested" ? "attested" : "strict" },
    registrySha256: facts.registrySha256,
    jdk: o.tc ? { release: Number(o.tc.release) || null, version: javacVersion(o.tc.javac) } : null,
    classpathSha256: o.cpDir ? hashFile(path.join(o.cpDir, `${rec.mcVersion}.txt`)) : null,
    deps: (o.deps || []).map((d) => ({ id: String(d.id), sha256: d.sha256 || null })).sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0)),
    toolchain: o.tc ? `javac --release ${o.tc.release} -proc:none; jar --date (sorted entries)` : null,
  };
}

module.exports = { RELEASE_SCHEMA, IMAGE_VERSION, hashFile, javacVersion, serviceFacts, releaseFor };

