// Cyrus R5 delivery: a copy-on-write JOURNAL over a server's file access, so a delivery can be rolled back to the
// EXACT previous bytes of every path it (or any installer it calls: the Mods engine, the managed-plugin installer, the
// Mod Pack unit, the creature writer, the Pack Loader config writer) changed.
//
// Every mutation goes through `JournalFs`. Before the FIRST mutation of a path it records what was there: a file is
// copied to the journal's backup folder (on the server: `cp`, no download) and hashed; a missing path is recorded as
// absent; a directory about to be removed is captured file by file. Parent folders a write creates are recorded too.
// `rollback()` undoes everything in reverse order (restored files are written as a new file + rename, so a running
// JVM that holds the old file open is never corrupted), then re-reads every journaled path and compares it with the
// recorded hash (or absence). `commit()` drops the backups. The journal itself is persisted next to the backups
// after every new entry, so a crashed worker leaves a recoverable journal (`recoverJournal`).
// HOST SEAM: `TxnFs` is a GuestFs-shaped subset; Nxeon's SshGuestFs / LocalGuestFs satisfy it structurally.
import { createHash, randomBytes } from "node:crypto";

export interface TxnFs {
  stat(p: string): Promise<{ type: "file" | "dir"; size: number } | null>;
  readFile(p: string, maxBytes?: number): Promise<Buffer | null>;
  writeFile(p: string, data: Buffer): Promise<void>;
  mkdirp(p: string): Promise<void>;
  rename(from: string, to: string): Promise<void>;
  remove(p: string): Promise<void>;
  list(dir: string): Promise<string[]>;
  copy(from: string, to: string): Promise<void>;
  chownLike?(ref: string, paths: string[]): Promise<void>;
  readonly kind?: "ssh" | "local";
}

export type JournalEntry =
  | { t: "file"; path: string; existed: true; sha256: string; size: number; backup: string }
  | { t: "absent"; path: string }
  | { t: "dir"; path: string; files: { rel: string; sha256: string; backup: string }[]; dirs: string[] }
  | { t: "mkdir"; path: string };
export type JournalFile = { schema: 1; id: string; label: string; startedAt: string; base: string; entries: JournalEntry[] };
export type RollbackReport = { attempted: boolean; ok: boolean; restored: number; removed: number; mismatches: string[] };

export const JOURNAL_ROOT = "/root/.nxeon-cyrus/delivery-journal";
export const MAX_FILE_BYTES = 256 * 1024 * 1024;
export const MAX_DIR_FILES = 2000;

const sha = (b: Buffer) => createHash("sha256").update(b).digest("hex");
const errMsg = (e: unknown) => (e instanceof Error ? e.message : String(e)).slice(0, 300);
const parentOf = (p: string) => p.slice(0, p.lastIndexOf("/")) || "/";
const norm = (p: string) => p.replace(/\/+$/, "") || "/";

export class JournalFs implements TxnFs {
  readonly entries: JournalEntry[] = [];
  private seen = new Set<string>();
  private n = 0;
  readonly dir: string;
  readonly kind?: "ssh" | "local";
  constructor(readonly inner: TxnFs, readonly opts: { id?: string; label?: string; root?: string; base?: string; passthrough?: string[]; now?: Date }) {
    const id = opts.id ?? `${(opts.now ?? new Date()).toISOString().replace(/[-:.]/g, "").slice(0, 15)}-${randomBytes(4).toString("hex")}`;
    this.dir = `${opts.root ?? JOURNAL_ROOT}/${id}`;
    this.kind = inner.kind;
    this.file = { schema: 1, id, label: opts.label ?? "delivery", startedAt: (opts.now ?? new Date()).toISOString(), base: opts.base ?? "/opt/mc", entries: this.entries };
  }
  readonly file: JournalFile;
  get id() { return this.file.id; }

  private pass(p: string): boolean {
    const n = norm(p);
    if (n === this.dir || n.startsWith(this.dir + "/")) return true;
    return (this.opts.passthrough ?? []).some((x) => n === norm(x) || n.startsWith(norm(x) + "/"));
  }
  private async persist() {
    await this.inner.mkdirp(this.dir);
    const tmp = `${this.dir}/journal.json.part`;
    await this.inner.writeFile(tmp, Buffer.from(JSON.stringify(this.file)));
    await this.inner.rename(tmp, `${this.dir}/journal.json`);
  }
  private nextBackup() { return `${this.dir}/b/${String(++this.n).padStart(5, "0")}`; }

  /** Record missing ancestor folders a write/mkdir will create (outermost first). */
  private async ancestors(p: string) {
    const missing: string[] = [];
    for (let d = parentOf(p); d && d !== "/"; d = parentOf(d)) {
      if (this.seen.has(`mkdir:${d}`)) break;
      const st = await this.inner.stat(d);
      if (st) break;
      missing.push(d);
    }
    for (const d of missing.reverse()) { this.seen.add(`mkdir:${d}`); this.entries.push({ t: "mkdir", path: d }); }
    return missing.length;
  }

  /** Capture `p` before its first mutation. */
  private async capture(p0: string, why: "write" | "remove") {
    const p = norm(p0);
    if (this.pass(p) || this.seen.has(p)) return;
    // a path inside an already-captured directory needs nothing more
    for (const e of this.entries) if (e.t === "dir" && p.startsWith(e.path + "/")) { this.seen.add(p); return; }
    this.seen.add(p);
    const st = await this.inner.stat(p);
    if (!st) { this.entries.push({ t: "absent", path: p }); if (why === "write") await this.ancestors(p); await this.persist(); return; }
    if (st.type === "file") {
      if (st.size > MAX_FILE_BYTES) throw new Error(`${p} is too large to back up safely (${st.size} bytes)`);
      const b = await this.inner.readFile(p, MAX_FILE_BYTES);
      if (!b) throw new Error(`${p} could not be read for the backup`);
      const backup = this.nextBackup();
      await this.inner.copy(p, backup);
      const copy = await this.inner.readFile(backup, MAX_FILE_BYTES);
      if (!copy || !copy.equals(b)) throw new Error(`backup of ${p} did not verify`);
      this.entries.push({ t: "file", path: p, existed: true, sha256: sha(b), size: b.length, backup });
      await this.persist();
      return;
    }
    // a directory: capture every file under it (bounded)
    const files: { rel: string; sha256: string; backup: string }[] = [];
    const dirs: string[] = [];
    const walk = async (d: string, rel: string, depth: number) => {
      if (depth > 12) throw new Error(`${p} is nested too deeply to back up safely`);
      for (const name of (await this.inner.list(d)).sort()) {
        const full = `${d}/${name}`, r = rel ? `${rel}/${name}` : name;
        const s = await this.inner.stat(full);
        if (!s) continue; // symlinks are reported as missing by the guest fs: never followed
        if (s.type === "dir") { dirs.push(r); await walk(full, r, depth + 1); continue; }
        if (files.length >= MAX_DIR_FILES) throw new Error(`${p} has too many files to back up safely`);
        const b = await this.inner.readFile(full, MAX_FILE_BYTES);
        if (!b) throw new Error(`${full} could not be read for the backup`);
        const backup = this.nextBackup();
        await this.inner.copy(full, backup);
        files.push({ rel: r, sha256: sha(b), backup });
      }
    };
    await walk(p, "", 0);
    this.entries.push({ t: "dir", path: p, files, dirs });
    await this.persist();
  }

  stat(p: string) { return this.inner.stat(p); }
  readFile(p: string, maxBytes?: number) { return this.inner.readFile(p, maxBytes); }
  list(dir: string) { return this.inner.list(dir); }
  async writeFile(p: string, data: Buffer) { await this.capture(p, "write"); return this.inner.writeFile(p, data); }
  async mkdirp(p: string) { if (!this.pass(p)) { if (await this.ancestors(`${norm(p)}/x`)) await this.persist(); } return this.inner.mkdirp(p); }
  async rename(from: string, to: string) { await this.capture(from, "remove"); await this.capture(to, "write"); return this.inner.rename(from, to); }
  async remove(p: string) { await this.capture(p, "remove"); return this.inner.remove(p); }
  async copy(from: string, to: string) { await this.capture(to, "write"); return this.inner.copy(from, to); }
  async chownLike(ref: string, paths: string[]) { return this.inner.chownLike?.(ref, paths); }

  /** Journaled paths (for reports). */
  touched(): string[] { return this.entries.filter((e) => e.t !== "mkdir").map((e) => e.path); }

  rollback(): Promise<RollbackReport> { return rollbackEntries(this.inner, this.entries, this.dir); }
  /** The change stands: drop the backups and the journal. */
  async commit(): Promise<void> { await this.inner.remove(this.dir).catch(() => {}); }
}

async function restoreFile(fs: TxnFs, backup: string, target: string) {
  const part = `${target}.nxeon-restore`;
  await fs.mkdirp(parentOf(target));
  await fs.copy(backup, part);
  await fs.rename(part, target);
}

/** Undo journal entries (newest first), then verify every path against the record. Never throws. */
export async function rollbackEntries(fs: TxnFs, entries: JournalEntry[], dir: string): Promise<RollbackReport> {
  const rep: RollbackReport = { attempted: true, ok: true, restored: 0, removed: 0, mismatches: [] };
  for (const e of [...entries].reverse()) {
    try {
      if (e.t === "file") { await fs.remove(`${e.path}.nxeon-part`).catch(() => {}); await restoreFile(fs, e.backup, e.path); rep.restored++; }
      else if (e.t === "absent") { if (await fs.stat(e.path)) { await fs.remove(e.path); rep.removed++; } }
      else if (e.t === "dir") {
        if (await fs.stat(e.path)) await fs.remove(e.path);
        await fs.mkdirp(e.path);
        for (const d of e.dirs) await fs.mkdirp(`${e.path}/${d}`);
        for (const f of e.files) await restoreFile(fs, f.backup, `${e.path}/${f.rel}`);
        rep.restored += e.files.length;
      } else if (e.t === "mkdir") {
        const st = await fs.stat(e.path);
        if (st?.type === "dir" && (await fs.list(e.path)).length === 0) { await fs.remove(e.path); rep.removed++; }
      }
    } catch (err) { rep.mismatches.push(`${e.path}: restore failed (${errMsg(err)})`); }
  }
  // verify
  for (const e of entries) {
    try {
      if (e.t === "file") { const b = await fs.readFile(e.path, MAX_FILE_BYTES); const now = b ? sha(b) : null; if (now !== e.sha256) rep.mismatches.push(`${e.path}: expected ${e.sha256.slice(0, 12)}, found ${now ? now.slice(0, 12) : "absent"}`); }
      else if (e.t === "absent") { if (await fs.stat(e.path)) rep.mismatches.push(`${e.path}: expected absent, still present`); }
      else if (e.t === "dir") {
        for (const f of e.files) { const b = await fs.readFile(`${e.path}/${f.rel}`, MAX_FILE_BYTES); if (!b || sha(b) !== f.sha256) rep.mismatches.push(`${e.path}/${f.rel}: not restored`); }
      } else if (e.t === "mkdir") {
        const st = await fs.stat(e.path);
        if (st && (await fs.list(e.path)).length === 0) rep.mismatches.push(`${e.path}: empty folder left behind`);
      }
    } catch (err) { rep.mismatches.push(`${e.path}: verify failed (${errMsg(err)})`); }
  }
  rep.ok = rep.mismatches.length === 0;
  if (rep.ok) await fs.remove(dir).catch(() => {});
  return rep;
}

/** Journals a crashed delivery left behind (each must be recovered before the next delivery to that server). */
export async function pendingJournals(fs: TxnFs, root = JOURNAL_ROOT): Promise<string[]> {
  const out: string[] = [];
  for (const name of (await fs.list(root)).sort()) if ((await fs.stat(`${root}/${name}/journal.json`))?.type === "file") out.push(name);
  return out;
}

/** Roll back a left-over journal (admin recovery action after a worker crash mid-delivery). */
export async function recoverJournal(fs: TxnFs, id: string, root = JOURNAL_ROOT): Promise<RollbackReport | { attempted: false; ok: false; error: string }> {
  if (!/^[A-Za-z0-9_-]{1,64}$/.test(id)) return { attempted: false, ok: false, error: "bad journal id" };
  const raw = await fs.readFile(`${root}/${id}/journal.json`, 8 * 1024 * 1024);
  if (!raw) return { attempted: false, ok: false, error: "no such journal" };
  let j: JournalFile;
  try { j = JSON.parse(raw.toString("utf8")); } catch { return { attempted: false, ok: false, error: "journal is not valid JSON" }; }
  if (j?.schema !== 1 || !Array.isArray(j.entries)) return { attempted: false, ok: false, error: "not a delivery journal" };
  const dir = `${root}/${id}`;
  for (const e of j.entries) {
    if (typeof e?.path !== "string" || !e.path.startsWith("/") || e.path.split("/").includes("..")) return { attempted: false, ok: false, error: "journal has an unsafe path" };
    if (e.t === "file" && !(e.backup.startsWith(dir + "/"))) return { attempted: false, ok: false, error: "journal backup outside its folder" };
  }
  return rollbackEntries(fs, j.entries, dir);
}

