// Cyrus R5 delivery orchestrator: the HOST SEAM and the result types. Cyrus reaches a server ONLY through these small
// injectable interfaces (file access, installer, restart, health probe, managed-plugin refs, pack hosting); Nxeon
// implements them in the worker (worker/cyrus-delivery.ts), tests implement them with fakes, the node-2 real run
// with a disposable Test Flight server. Plain JSON results (for the admin read model and a future UI).
import type { TxnFs, RollbackReport } from "./journal";
import type { ReadOnlyServerFs } from "../inventory/types";
import type { InventoryReport } from "../inventory/types";
import type { MemberPlacer } from "../modpack/install";
import type { PackStore } from "../packhost/types";
import type { StoredCreature } from "../creature/deliver";

export type Env = Record<string, string | undefined>;

/** Everything one revision of a Cyrus mod delivers, resolved and verified by the host BEFORE the server is touched. */
export type ModRelease = {
  projectId: string;
  revisionId: string;
  modBuildId?: string | null;
  namespace: string;
  /** The Minecraft version the mod was built for (managed-plugin pins are per family). */
  mcVersion: string;
  label: string;
  plugin: { pluginName: string; jarName: string; sha256: string; bytes: Buffer } | null;
  /** The mod's resource pack (Pack Loader entry role "main"): zip to publish, or an already hosted url. */
  pack: { sha1: string; sha256?: string; zip?: Buffer; url?: string; prompt: string; required: boolean } | null;
  datapacks: { name: string; zip: Buffer; sha256: string; apply: "reload" | "restart"; worldgen?: { dimensions: string[] } }[];
  /** BetterModel creatures: the compiled .bbmodel files are re-derived (and checked) by the orchestrator. */
  creatures: StoredCreature[];
};

/** What a delivery left on the server (the on-server record at DELIVERY_RECORD_DIR/<projectId>.json). */
export type DeliveryRecord = {
  schema: 1;
  projectId: string;
  revisionId: string;
  namespace: string;
  mcVersion: string;
  pluginName: string | null;
  jar: { target: string; sha256: string } | null;
  datapacks: { name: string; target: string; sha256: string; apply: "reload" | "restart"; dimensions?: string[] }[];
  models: { target: string; sha256: string }[];
  packLoaderIds: string[];
  managed: string[];
  deliveredAt: string;
};

export type HealthExpect = {
  /** Plugin names that must be enabled. */
  plugins: string[];
  /** Plugin names that must NOT be enabled any more (uninstall). */
  pluginsGone?: string[];
  /** Datapack ids as `datapack list` shows them (file/<name>.zip). */
  datapacks: string[];
  /** World generation changed: the server must actually reach "Done" after the restart. */
  worldgen: boolean;
};
export type HealthReport = {
  /** The health probe ran against a real server process (false = simulated: never a pass). */
  real: boolean;
  cameUp: boolean;
  answered: boolean;
  pluginsEnabled: string[];
  errorLines: string[];
  datapacksLoaded: string[];
  evidence: string[];
};
export type HealthVerdict = { ok: boolean; problems: string[]; report: HealthReport | null };

/** One open server for the length of a delivery (worker job, under the per-server lock). */
export interface ServerSession {
  fs: TxnFs;
  base: string;
  levelName: string;
  /** The server's Minecraft version (from the host's own record or the inventory). */
  mcVersion: string | null;
  restart(): Promise<{ ok: true } | { ok: false; error: string }>;
  /** One console command (RCON); absent = the host cannot run commands (reloads then wait for the next restart). */
  console?(command: string): Promise<{ ok: true; reply: string } | { ok: false; error: string }>;
  /** Probe after a restart / reload. */
  health(expect: HealthExpect): Promise<HealthReport>;
  /** Error lines the server already had before this delivery (so only NEW ones fail the health check). */
  baselineErrors?(): Promise<string[]>;
  close?(): void;
}

export interface ManagedPort {
  /** Install / add a ref. `fs` is the delivery's journaled file access: the installer must write only through it. */
  ensure(a: { serverId: string; key: string; mcVersion: string; dependent: string; fs: TxnFs }): Promise<{ ok: true; action: "installed" | "upgraded" | "ref_added" | "already"; pluginName: string } | { ok: false; error: string }>;
  release(a: { serverId: string; key: string; dependent: string; fs: TxnFs }): Promise<{ ok: true; action: "removed" | "ref_dropped" | "not_held" } | { ok: false; error: string }>;
  /** Opaque snapshot of this server's managed-plugin refs (database rows), restored on rollback. */
  snapshot(serverId: string): Promise<unknown>;
  restore(serverId: string, snap: unknown): Promise<{ ok: true } | { ok: false; error: string }>;
}

export interface JarPort {
  /** Place (or replace) the mod's plugin jar; must write only through `fs`. Returns the absolute target path. */
  install(a: { serverId: string; fs: TxnFs; base: string; release: ModRelease; previous: DeliveryRecord | null }): Promise<{ ok: true; target: string } | { ok: false; error: string }>;
  remove(a: { serverId: string; fs: TxnFs; base: string; record: DeliveryRecord }): Promise<{ ok: true } | { ok: false; error: string }>;
}

export interface DeliveryHost {
  open(serverId: string): Promise<ServerSession>;
  /** Read-only view for the inventory (default: the session's fs). */
  readOnly?(session: ServerSession): ReadOnlyServerFs;
  managed: ManagedPort;
  jar: JarPort;
  /** Pack hosting (immutable, content-addressed). Absent = packs cannot be hosted here: the pack part is skipped. */
  packs?: { publish(zip: Buffer, sha1: string): Promise<{ url: string }>; store?: PackStore };
  /** Mod Packs: the member placer to use with the journaled fs (Nxeon: the Mods engine placer). */
  modpackPlacer?(fs: TxnFs, session: ServerSession, packId: string): MemberPlacer;
  /** Third-party Mod Pack files. */
  fetchArtifact?: (f: import("../modpack/manifest").NxPackFile) => Promise<Buffer>;
  /** BetterModel config template (default: lib/cyrus/managed/bettermodel-config.yml). */
  betterModelConfig?: () => string;
  env?: Env;
  now?: () => Date;
  /** Fault injection (tests only): throw at the named step. */
  fault?: (step: DeliveryStep) => void;
}

export const DELIVERY_STEPS = ["open", "recover_check", "preflight", "managed", "host_pack", "pack_config", "place", "apply", "health", "handoff", "record", "commit"] as const;
export type DeliveryStep = (typeof DELIVERY_STEPS)[number];
export type StepResult = { step: DeliveryStep | "rollback" | "rollback_restart" | "rollback_health"; status: "ok" | "failed" | "skipped"; ms: number; detail: string };

export type ConflictSummary = { blocking: { id: string; class: string; message: string }[]; warnings: { id: string; class: string; severity: string; message: string }[]; notChecked: string[] };

export type DeliveryOutcome =
  | "delivered" | "updated" | "uninstalled" | "unchanged" | "pending_restart"
  | "refused" | "rolled_back" | "rollback_incomplete";

export type DeliveryResult = {
  ok: boolean;
  outcome: DeliveryOutcome;
  op: "install" | "update" | "uninstall" | "modpack_install" | "modpack_uninstall";
  serverId: string;
  subject: { projectId?: string; revisionId?: string; packId?: string; versionId?: string };
  steps: StepResult[];
  /** Why it failed / was refused (customer-safe text). */
  error?: string;
  failedStep?: DeliveryStep;
  conflicts?: ConflictSummary;
  apply?: { mode: "restart" | "reload" | "none"; reasons: string[]; restarted: boolean; reloaded: boolean };
  health?: HealthVerdict;
  rollback?: RollbackReport & { refs: "restored" | "failed" | "unchanged"; restarted: boolean; health: HealthVerdict | null };
  notes: string[];
  record?: DeliveryRecord | null;
  /** Uninstall: dimension world folders KEPT on the server (listed for an admin cleanup action). */
  keptWorldFolders?: string[];
  journalId?: string;
  startedAt: string;
  finishedAt: string;
};

export type { TxnFs, RollbackReport, InventoryReport };

