// Cyrus R5: the DELIVERY ORCHESTRATOR. Installs / updates / uninstalls one Cyrus mod (plugin jar + resource pack +
// data packs + world generation + managed plugins + creatures) or one Mod Pack on ONE server, as one transaction-like
// sequence:
//   open -> recover check (a left-over journal refuses) -> preflight (server inventory + conflict engine against what is
//   already there: blocking refuses, warnings are recorded; release bytes verified; Pack Loader config valid) ->
//   [snapshot managed-plugin refs] -> ensure managed plugins (Pack Loader, BetterModel) -> host the pack (immutable URL)
//   -> Pack Loader config -> place jar / data packs / creature models (all through the copy-on-write journal) -> delivery
//   record -> apply ONLY as the semantics require (restart / minecraft:reload / nothing) -> HEALTH CHECK (answers,
//   plugins enabled, no new error lines, data packs loaded, worldgen: really came up) -> BetterModel hand-off (after the
//   restart) -> commit.
// ANY failure after preflight rolls back to the exact previous state: every journaled file (bytes verified), the
// managed-plugin refs (database rows), and, when the server was restarted or reloaded, restarts / reloads it again and
// checks that it came up; why is recorded step by step. Mod Packs reuse the same transaction (their unit installer
// writes through the same journal), so a pack is still one unit.
// OFF unless CYRUS_DELIVERY=1 (and each part behind its existing flag: CYRUS_MANAGED_PLUGINS_REAL,
// CYRUS_DATAPACK_DELIVERY_REAL (+ CYRUS_WORLDGEN), CYRUS_CREATURES, CYRUS_MODPACK_INSTALL_REAL).
// HOST SEAM: everything goes through DeliveryHost (./types.ts); no Nxeon import.
import { createHash } from "node:crypto";
import { JournalFs, pendingJournals, type RollbackReport } from "./journal";
import { DELIVERY_RECORD_DIR, JOURNAL_PASSTHROUGH, PACK_LOADER_KEY, PACK_LOADER_PLUGIN, BETTERMODEL_KEY, BETTERMODEL_PLUGIN, datapackFile, datapackId, dependentFor, dimensionFolders, judgeHealth, packDependent, planApply, readRecord, recordPath, switches, type ApplyInput, type ApplyPlan } from "./plan";
import type { ConflictSummary, DeliveryHost, DeliveryRecord, DeliveryResult, DeliveryStep, HealthExpect, HealthVerdict, ModRelease, ServerSession, StepResult } from "./types";
import { scanServer } from "../inventory/scan";
import { indexZip, readEntry } from "../inventory/zipread";
import { indexDatapack } from "../inventory/datapack";
import { candidateJar, datapackEntry, inventoryEntries } from "../conflicts/normalize";
import { detectConflicts } from "../conflicts/engine";
import type { ModEntry } from "../conflicts/types";
import { readLoaderConfig, writeLoaderConfig } from "../packhost/deliver";
import { applyPackChange, LOADER_CONFIG_PATH, validateLoaderConfig, type LoaderConfig } from "../packhost/loader-config";
import { compileStoredCreatures, CONFIG_MARKER, CONFIG_PATH as BM_CONFIG_PATH, MODELS_DIR as BM_MODELS_DIR, managedConfigTemplate } from "../creature/deliver";
import { handoffBetterModelPack } from "../creature/handoff";
import { installModPackUnit, uninstallModPackUnit, type UnitResult } from "../modpack/install";
import { validateNxPack } from "../modpack/manifest";
import { RELOAD_COMMAND } from "../datapack/deliver";
import type { GuestFs } from "../../mods/guest-fs";

const sha256 = (b: Buffer) => createHash("sha256").update(b).digest("hex");
const sha1 = (b: Buffer) => createHash("sha1").update(b).digest("hex");
const errMsg = (e: unknown) => (e instanceof Error ? e.message : String(e)).slice(0, 500);
const NS_RE = /^nx_[a-z0-9]{8}$/;
export const PACK_ROLE = "main";

class StepFail extends Error { constructor(readonly step: DeliveryStep, msg: string) { super(msg); } }
class Refusal extends Error { constructor(readonly step: DeliveryStep, msg: string, readonly conflicts?: ConflictSummary) { super(msg); } }

export type DeliverOptions = {
  /** "now" (default): restart when the change needs one, then health-check. "next_restart": never restart (refused for worldgen/creatures). */
  restartPolicy?: "now" | "next_restart";
  /** Warning finding ids the user acknowledged (recorded; warnings never block). */
  acknowledge?: string[];
  /** Fail the health check on new error lines (default true). */
  strictLog?: boolean;
};

type Txn = {
  host: DeliveryHost; serverId: string; session: ServerSession; jfs: JournalFs; steps: StepResult[]; notes: string[];
  refsSnap: unknown; refsTouched: boolean; restartAttempted: boolean; reloaded: boolean; baseline: string[];
};
type BodyOut = { apply: ApplyInput; expect: HealthExpect; record: DeliveryRecord | null; outcome: DeliveryResult["outcome"]; handoff?: boolean; keptWorldFolders?: string[]; unchanged?: boolean; conflicts?: ConflictSummary };
type Prepared = { body: (t: Txn) => Promise<BodyOut>; conflicts?: ConflictSummary; precheckRestart?: { worldgen: boolean; creatures: boolean } };

async function timed<T>(t: { steps: StepResult[]; host: DeliveryHost }, step: DeliveryStep, fn: () => Promise<T>, detail?: (v: T) => string): Promise<T> {
  const t0 = Date.now();
  try {
    t.host.fault?.(step);
    const v = await fn();
    t.steps.push({ step, status: "ok", ms: Date.now() - t0, detail: detail ? detail(v).slice(0, 400) : "" });
    return v;
  } catch (e) {
    t.steps.push({ step, status: "failed", ms: Date.now() - t0, detail: errMsg(e) });
    if (e instanceof Refusal || e instanceof StepFail) throw e;
    throw new StepFail(step, errMsg(e));
  }
}
const skip = (t: { steps: StepResult[] }, step: DeliveryStep, detail: string) => t.steps.push({ step, status: "skipped", ms: 0, detail });

/** The shared transaction. `prepare` runs the read-only preflight; its `body` does every mutation through t.jfs. */
async function transaction(a: { serverId: string; op: DeliveryResult["op"]; subject: DeliveryResult["subject"]; host: DeliveryHost; label: string; opts: DeliverOptions; prepare: (s: ServerSession, steps: StepResult[]) => Promise<Prepared> }): Promise<DeliveryResult> {
  const env = a.host.env ?? process.env;
  const now = a.host.now ?? (() => new Date());
  const startedAt = now().toISOString();
  const steps: StepResult[] = [];
  const notes: string[] = [];
  const done = (r: Omit<DeliveryResult, "op" | "serverId" | "subject" | "steps" | "notes" | "startedAt" | "finishedAt">): DeliveryResult =>
    ({ op: a.op, serverId: a.serverId, subject: a.subject, steps, notes, startedAt, finishedAt: now().toISOString(), ...r });
  if (!switches(env).delivery) return done({ ok: false, outcome: "refused", error: "Cyrus delivery is switched off (CYRUS_DELIVERY is not 1); nothing was changed" });

  let session: ServerSession;
  try { session = await timed({ steps, host: a.host }, "open", () => a.host.open(a.serverId)); }
  catch (e) { return done({ ok: false, outcome: "refused", failedStep: "open", error: `the server could not be opened: ${errMsg(e)}` }); }
  try {
    try {
      const left = await timed({ steps, host: a.host }, "recover_check", () => pendingJournals(session.fs), (v) => (v.length ? `left-over journals: ${v.join(", ")}` : "none"));
      if (left.length) return done({ ok: false, outcome: "refused", failedStep: "recover_check", error: `a previous delivery to this server did not finish (journal ${left[0]}); an admin must recover it first (recoverJournal) before anything else is delivered` });
    } catch (e) { return done({ ok: false, outcome: "refused", failedStep: "recover_check", error: errMsg(e) }); }

    let prep: Prepared;
    try { prep = await a.prepare(session, steps); }
    catch (e) {
      const ref = e instanceof Refusal ? e : null;
      return done({ ok: false, outcome: "refused", failedStep: ref?.step ?? "preflight", error: errMsg(e), conflicts: ref?.conflicts });
    }
    if (a.opts.restartPolicy === "next_restart" && prep.precheckRestart && (prep.precheckRestart.worldgen || prep.precheckRestart.creatures)) {
      return done({ ok: false, outcome: "refused", failedStep: "preflight", conflicts: prep.conflicts, error: `${prep.precheckRestart.worldgen ? "world generation" : "animated creatures"} must be delivered with a supervised restart (restartPolicy "now"), because a broken pack stops the server at its next start` });
    }

    const jfs = new JournalFs(session.fs, { label: a.label, base: session.base, passthrough: JOURNAL_PASSTHROUGH, now: now() });
    const t: Txn = { host: a.host, serverId: a.serverId, session, jfs, steps, notes, refsSnap: null, refsTouched: false, restartAttempted: false, reloaded: false, baseline: [] };
    let out: BodyOut | null = null;
    let plan: ApplyPlan | null = null;
    let health: HealthVerdict | undefined;
    try {
      t.refsSnap = await a.host.managed.snapshot(a.serverId);
      t.baseline = (await session.baselineErrors?.().catch(() => [] as string[])) ?? [];
      out = await prep.body(t);
      if (out.unchanged) { await jfs.commit(); return done({ ok: true, outcome: "unchanged", conflicts: prep.conflicts ?? out.conflicts, record: out.record, journalId: jfs.id }); }
      plan = planApply(out.apply);
      const restartNow = plan.mode === "restart" && a.opts.restartPolicy !== "next_restart";
      // apply
      await timed(t, "apply", async () => {
        if (plan!.mode === "restart" && !restartNow) return;
        if (plan!.mode === "restart") { t.restartAttempted = true; const r = await session.restart(); if (!r.ok) throw new Error(`restart failed: ${r.error}`); }
        else if (plan!.mode === "reload") {
          if (!session.console) { notes.push("the data pack loads on the next restart (this server cannot run console commands)"); return; }
          t.reloaded = true;
          const r = await session.console(RELOAD_COMMAND);
          if (!r.ok) throw new Error(`${RELOAD_COMMAND} failed: ${r.error}`);
        }
        for (const c of plan!.consoleAfter) if (session.console) await session.console(c).catch(() => null); // the Pack Loader also watches its file
      }, () => `${plan!.mode}${plan!.mode === "restart" && !restartNow ? " (deferred to the next restart)" : ""}: ${plan!.reasons.join("; ")}`);
      if (plan.mode === "restart" && !restartNow) {
        skip(t, "health", "not checked: the change takes effect at the next restart");
        await timed(t, "commit", () => jfs.commit());
        notes.push("Restart the server to load the change.");
        return done({ ok: true, outcome: "pending_restart", conflicts: prep.conflicts ?? out.conflicts, apply: { mode: plan.mode, reasons: plan.reasons, restarted: false, reloaded: false }, record: out.record, keptWorldFolders: out.keptWorldFolders, journalId: jfs.id });
      }
      // health
      if (plan.mode === "none" && !out.expect.plugins.length && !out.expect.datapacks.length) skip(t, "health", "nothing to check: no restart or reload happened");
      else {
        health = await timed(t, "health", async () => {
          const v = judgeHealth(out!.expect, await session.health(out!.expect), a.opts.strictLog === false ? undefined : t.baseline);
          if (a.opts.strictLog === false) v.problems = v.problems.filter((p) => !p.startsWith("new error lines"));
          v.ok = v.problems.length === 0;
          if (!v.ok) throw Object.assign(new Error(v.problems.join("; ")), { verdict: v });
          return v;
        }, () => "healthy").catch((e) => { health = (e as { verdict?: HealthVerdict }).verdict; throw e; });
      }
      // BetterModel builds its pack at start: publish it and point the Pack Loader at it (after the restart)
      if (out.handoff && plan.mode === "restart") {
        await timed(t, "handoff", async () => {
          const store = a.host.packs?.store;
          if (!store) { notes.push("the BetterModel pack could not be handed off (no pack hosting here); creatures show without their pack"); return "no store"; }
          const h = await handoffBetterModelPack({ fs: jfs as unknown as GuestFs, store, base: session.base });
          if (!h.ok) throw new Error(`BetterModel pack hand-off: ${h.error}`);
          if (session.console) await session.console("nxpacks reload").catch(() => null);
          return "handed off";
        }, (v) => String(v));
      }
      await timed(t, "commit", () => jfs.commit());
      return done({ ok: true, outcome: out.outcome, conflicts: prep.conflicts ?? out.conflicts, apply: { mode: plan.mode, reasons: plan.reasons, restarted: t.restartAttempted, reloaded: t.reloaded }, health, record: out.record, keptWorldFolders: out.keptWorldFolders, journalId: jfs.id });
    } catch (e) {
      const failedStep = e instanceof StepFail || e instanceof Refusal ? e.step : "place";
      const rb = await rollback(t, plan);
      const incomplete = !rb.ok || rb.refs === "failed" || (rb.health !== null && !rb.health.ok);
      return done({
        ok: false, outcome: incomplete ? "rollback_incomplete" : "rolled_back", failedStep, error: errMsg(e), conflicts: prep.conflicts ?? out?.conflicts,
        apply: plan ? { mode: plan.mode, reasons: plan.reasons, restarted: t.restartAttempted, reloaded: t.reloaded } : undefined, health, rollback: rb, record: null, journalId: jfs.id,
      });
    }
  } finally { session.close?.(); }
}

/** Undo: files (journal), refs (database), then restart / reload again if the change already reached the server. */
async function rollback(t: Txn, plan: ApplyPlan | null): Promise<RollbackReport & { refs: "restored" | "failed" | "unchanged"; restarted: boolean; health: HealthVerdict | null }> {
  const t0 = Date.now();
  const files = await t.jfs.rollback();
  let refs: "restored" | "failed" | "unchanged" = "unchanged";
  if (t.refsTouched) {
    const r = await t.host.managed.restore(t.serverId, t.refsSnap).catch((e) => ({ ok: false as const, error: errMsg(e) }));
    refs = r.ok ? "restored" : "failed";
    if (!r.ok) files.mismatches.push(`managed plugin refs: ${r.error}`);
  }
  t.steps.push({ step: "rollback", status: files.ok && refs !== "failed" ? "ok" : "failed", ms: Date.now() - t0, detail: `${files.restored} restored, ${files.removed} removed${files.mismatches.length ? `; MISMATCHES: ${files.mismatches.slice(0, 3).join(" | ")}` : ""}; refs ${refs}` });
  let restarted = false;
  let health: HealthVerdict | null = null;
  if (t.restartAttempted) {
    const t1 = Date.now();
    const r = await t.session.restart().catch((e) => ({ ok: false as const, error: errMsg(e) }));
    restarted = r.ok;
    t.steps.push({ step: "rollback_restart", status: r.ok ? "ok" : "failed", ms: Date.now() - t1, detail: r.ok ? "restarted on the previous state" : `restart after rollback failed: ${(r as { error: string }).error}` });
    const t2 = Date.now();
    const rep = r.ok ? await t.session.health({ plugins: [], datapacks: [], worldgen: false }).catch(() => null) : null;
    health = judgeHealth({ plugins: [], datapacks: [], worldgen: false }, rep, t.baseline);
    health.problems = health.problems.filter((p) => !p.startsWith("new error lines")); // the previous state's own log is not ours to judge
    health.ok = health.problems.length === 0;
    t.steps.push({ step: "rollback_health", status: health.ok ? "ok" : "failed", ms: Date.now() - t2, detail: health.ok ? "the server came up on the previous state" : health.problems.join("; ").slice(0, 400) });
  } else if (t.reloaded && t.session.console) {
    await t.session.console(RELOAD_COMMAND).catch(() => null);
  }
  void plan;
  return { ...files, refs, restarted, health };
}

// ------------------------------------------------------------------------------------------------ preflight helpers

function datapackCandidate(name: string, zip: Buffer, cyrus: ModEntry["cyrus"]): Promise<ModEntry> {
  const z = indexZip(zip);
  if (!z.ok) throw new Error(`data pack ${name}: ${z.error}`);
  const files = z.zip.entries.filter((e) => !e.dir && e.name.startsWith("data/")).map((e) => ({ path: e.name, read: () => { const r = readEntry(z.zip, e); return r.ok ? r.data : null; } }));
  const mm = z.zip.entries.find((e) => e.name === "pack.mcmeta");
  const mcmeta = mm ? (() => { const r = readEntry(z.zip, mm); return r.ok ? r.data : null; })() : null;
  return indexDatapack(name, "candidate", "zip", files, mcmeta).then((d) => datapackEntry(d, "candidate", { cyrus, changed: true }));
}

function summarize(rep: ReturnType<typeof detectConflicts>, involve: (f: { items: { mod: string }[] }) => boolean): ConflictSummary {
  const mine = rep.findings.filter(involve);
  return {
    blocking: mine.filter((f) => f.severity === "blocking").map((f) => ({ id: f.id, class: f.class, message: f.message })),
    warnings: mine.filter((f) => f.severity !== "blocking").map((f) => ({ id: f.id, class: f.class, severity: f.severity, message: f.message })).slice(0, 50),
    notChecked: rep.notChecked.slice(0, 30),
  };
}

function verifyRelease(r: ModRelease): string | null {
  if (!/^[A-Za-z0-9_-]{1,64}$/.test(r.projectId)) return "bad project id";
  if (!NS_RE.test(r.namespace)) return "bad namespace";
  if (r.plugin) {
    if (!/^[A-Za-z0-9._ -]{1,120}\.jar$/.test(r.plugin.jarName) || r.plugin.jarName.includes("/")) return "bad jar name";
    if (sha256(r.plugin.bytes) !== r.plugin.sha256) return "the plugin jar does not match its recorded sha256";
  }
  if (r.pack?.zip && sha1(r.pack.zip) !== r.pack.sha1) return "the resource pack does not match its recorded sha1";
  if (r.pack && !r.pack.zip && !(r.pack.url && /^https:\/\//.test(r.pack.url))) return "the resource pack has neither bytes nor an https URL";
  for (const d of r.datapacks) {
    if (!/^[a-z0-9_-]{1,40}$/.test(d.name)) return `bad data pack name ${d.name}`;
    if (sha256(d.zip) !== d.sha256) return `data pack ${d.name} does not match its recorded sha256`;
    if (d.worldgen && d.apply !== "restart") return `data pack ${d.name} has world generation and must be applied with a restart`;
  }
  return null;
}

// ------------------------------------------------------------------------------------------------ install / update

/** Install a revision of a Cyrus mod, or update the one already delivered (same project). */
export async function deliverMod(serverId: string, release: ModRelease, host: DeliveryHost, opts: DeliverOptions = {}): Promise<DeliveryResult> {
  const env = host.env ?? process.env;
  const sw = switches(env);
  let op: DeliveryResult["op"] = "install";
  const result = await transaction({
    serverId, op, subject: { projectId: release.projectId, revisionId: release.revisionId }, host, label: `deliver-${release.projectId}`, opts,
    prepare: async (session, steps) => {
      const ctx = { steps, host };
      return timed(ctx, "preflight", async () => {
        const bad = verifyRelease(release);
        if (bad) throw new Refusal("preflight", `the mod version is not deliverable: ${bad}; nothing was changed`);
        const notes: string[] = [];
        // what this delivery may carry (each part behind its own switch; off = left out with a note)
        const datapacks = release.datapacks.filter((d) => {
          if (!sw.datapacks) { notes.push(`data pack ${d.name} was not delivered: data pack delivery is switched off`); return false; }
          if (d.worldgen && !sw.worldgen) { notes.push(`data pack ${d.name} was not delivered: world generation is switched off`); return false; }
          return true;
        });
        const pack = release.pack && sw.managed && (release.pack.url || host.packs) ? release.pack : null;
        if (release.pack && !pack) notes.push(sw.managed ? "the custom resource pack was not delivered: pack hosting is not available here" : "the custom resource pack was not delivered: managed plugins (the Pack Loader) are switched off");
        const creatures = sw.creatures ? release.creatures : [];
        if (release.creatures.length && !creatures.length) notes.push("animated creatures were not delivered: creature delivery is switched off");
        const compiled = creatures.length ? compileStoredCreatures(release.namespace, creatures) : { ok: true as const, files: [] };
        if (!compiled.ok) throw new Refusal("preflight", `${compiled.error}; nothing was changed`);
        if (!release.plugin && !datapacks.length && !pack && !compiled.files.length) throw new Refusal("preflight", "nothing in this version can be delivered with the current switches; nothing was changed");
        const prev = readRecord(await session.fs.readFile(recordPath(release.projectId), 1024 * 1024));
        op = prev ? "update" : "install";
        // inventory + conflicts against what the server already runs (our own previous files excluded)
        const ro = host.readOnly?.(session) ?? session.fs;
        const inv = await scanServer(ro, { base: session.base });
        const own = new Set([prev?.jar?.target, ...(prev?.datapacks.map((d) => d.target) ?? [])].filter(Boolean).map((p) => p!.slice(session.base.length + 1)));
        const { mods, ctx: cctx } = inventoryEntries(inv, { exclude: (p) => own.has(p) || [...own].some((o) => o.endsWith(`/${p}`) || p.endsWith(o)) });
        const cyrus = { namespace: release.namespace, projectId: release.projectId };
        const cands: ModEntry[] = [];
        if (release.plugin) cands.push(candidateJar(release.plugin.jarName, release.plugin.bytes, { id: `candidate:${release.plugin.jarName}`, cyrus }));
        for (const d of datapacks) cands.push(await datapackCandidate(datapackFile(release.namespace, d.name).replace(/\.zip$/, ""), d.zip, cyrus));
        const rep = detectConflicts([...cands, ...mods], { ...cctx, mcVersion: cctx.mcVersion ?? session.mcVersion ?? release.mcVersion });
        const candIds = new Set(cands.map((c) => c.id));
        const conflicts = summarize(rep, (f) => f.items.some((i) => candIds.has(i.mod)));
        if (conflicts.blocking.length) throw new Refusal("preflight", `blocked by ${conflicts.blocking.length} conflict(s) with what is already on the server: ${conflicts.blocking.map((b) => b.message).join(" | ").slice(0, 500)}; nothing was changed`, conflicts);
        // the Pack Loader config must be valid before we touch anything
        if (pack || prev?.packLoaderIds.length) {
          const cur = await readLoaderConfig(session.fs as unknown as GuestFs, session.base);
          if (!cur.ok) throw new Refusal("preflight", `the server's pack config is invalid, so nothing was changed: ${cur.error}`);
        }
        const packOwners = inv.resourcePackOwners.filter((o) => o.kind !== "packloader").map((o) => o.name);
        return {
          conflicts,
          precheckRestart: { worldgen: datapacks.some((d) => d.worldgen) || (prev?.datapacks.some((d) => (d.dimensions ?? []).length) ?? false), creatures: compiled.files.length > 0 || (prev?.models.length ?? 0) > 0 },
          body: (t: Txn) => deliverBody(t, release, prev, { datapacks, pack, models: compiled.files, notes, packOwners, plugins: inv.plugins.map((p) => p.descriptor?.name).filter((n): n is string => !!n), serverProperties: inv.serverProperties.keys }),
        };
      }, () => "inventory + conflicts checked");
    },
  });
  return { ...result, op };
}
export const updateMod = deliverMod;

async function deliverBody(t: Txn, r: ModRelease, prev: DeliveryRecord | null, p: { datapacks: ModRelease["datapacks"]; pack: ModRelease["pack"]; models: { rel: string; data: Buffer }[]; notes: string[]; packOwners: string[]; plugins: string[]; serverProperties: Record<string, string> }): Promise<BodyOut> {
  const { session, jfs, host } = t;
  const base = session.base, level = session.levelName;
  const mc = session.mcVersion ?? r.mcVersion;
  t.notes.push(...p.notes);
  const dep = dependentFor(r.projectId);
  const managedNow = new Set<string>();
  let managedChanged = false;
  const expectPlugins: string[] = [];
  // 1. managed plugins
  const wantLoader = !!p.pack, wantBm = p.models.length > 0;
  await timed(t, "managed", async () => {
    const out: string[] = [];
    for (const [key, want] of [[PACK_LOADER_KEY, wantLoader], [BETTERMODEL_KEY, wantBm]] as const) {
      const had = prev?.managed.includes(key) ?? false;
      if (want) {
        t.refsTouched = true;
        const e = await host.managed.ensure({ serverId: t.serverId, key, mcVersion: mc, dependent: dep, fs: jfs });
        if (!e.ok) throw new Error(`${key}: ${e.error}`);
        managedNow.add(key); expectPlugins.push(e.pluginName);
        if (e.action === "installed" || e.action === "upgraded") managedChanged = true;
        out.push(`${key} ${e.action}`);
      } else if (had) {
        t.refsTouched = true;
        const rel = await host.managed.release({ serverId: t.serverId, key, dependent: dep, fs: jfs });
        if (!rel.ok) throw new Error(`${key}: ${rel.error}`);
        if (rel.action === "removed") managedChanged = true;
        out.push(`${key} ${rel.action}`);
      }
    }
    return out.join(", ") || "none needed";
  }, (v) => v);
  // 2. pack hosting
  let packUrl: string | null = null;
  if (p.pack) {
    packUrl = await timed(t, "host_pack", async () => {
      if (p.pack!.zip && host.packs) return (await host.packs.publish(p.pack!.zip, p.pack!.sha1)).url;
      if (p.pack!.url) return p.pack!.url;
      throw new Error("no pack hosting configured");
    }, (u) => `hosted at ${u}`);
    if (!/^https:\/\//.test(packUrl)) throw new StepFail("host_pack", "the pack URL must be https");
  } else skip(t, "host_pack", "no resource pack in this delivery");
  // 3. Pack Loader config
  let loaderChanged = false;
  const loaderIds: string[] = [];
  if (p.pack || prev?.packLoaderIds.length) {
    await timed(t, "pack_config", async () => {
      const cur = await readLoaderConfig(jfs as unknown as GuestFs, base);
      if (!cur.ok) throw new Error(cur.error);
      const existed = cur.config?.packs.map((x) => `${x.owner ?? "?"}:${x.id.slice(0, 8)}`) ?? [];
      const ch = p.pack
        ? applyPackChange(cur.config, { op: "upsert", namespace: r.namespace, role: PACK_ROLE, sha1: p.pack.sha1, prompt: p.pack.prompt, required: p.pack.required, owner: `project:${r.projectId}` }, { urlFor: (s) => { if (s !== p.pack!.sha1) throw new Error("pack url for another sha1"); return packUrl!; } }, { plugins: p.plugins, serverProperties: p.serverProperties })
        : applyPackChange(cur.config, { op: "remove", namespace: r.namespace, role: PACK_ROLE }, { urlFor: () => "" });
      if (!ch.ok) throw new Error(ch.error);
      for (const w of ch.warnings) t.notes.push(w.message);
      if (p.packOwners.length) t.notes.push(`this server already has another resource-pack owner (${p.packOwners.join(", ")}); players may get two pack prompts`);
      if (p.pack) loaderIds.push(ch.id);
      if (ch.changed) { await writeLoaderConfig(jfs as unknown as GuestFs, ch.config, base); loaderChanged = true; }
      return `${ch.action}${existed.length ? `; other entries kept: ${existed.length}` : ""}`;
    }, (v) => v);
  } else skip(t, "pack_config", "no pack entry to change");
  // 4. place: jar, data packs, creature models
  let jarChanged = false, modelsChanged = false, managedConfigChanged = false;
  const placedDps: DeliveryRecord["datapacks"] = [];
  const models: DeliveryRecord["models"] = [];
  let jar: DeliveryRecord["jar"] = null;
  const dpApply: ApplyInput["datapacks"] = [];
  await timed(t, "place", async () => {
    if (r.plugin) {
      const cur = prev?.jar ? await jfs.readFile(prev.jar.target) : null;
      const same = !!prev?.jar && cur !== null && sha256(cur) === r.plugin.sha256 && prev.jar.target.endsWith(`/${r.plugin.jarName}`);
      if (!same) {
        const j = await host.jar.install({ serverId: t.serverId, fs: jfs, base, release: r, previous: prev });
        if (!j.ok) throw new Error(`plugin jar: ${j.error}`);
        const placed = await jfs.readFile(j.target);
        if (!placed || sha256(placed) !== r.plugin.sha256) throw new Error("the plugin jar on the server does not verify after placing it");
        jar = { target: j.target, sha256: r.plugin.sha256 };
        jarChanged = true;
      } else jar = prev!.jar;
      expectPlugins.push(r.plugin.pluginName);
    } else if (prev?.jar) {
      const rm = await host.jar.remove({ serverId: t.serverId, fs: jfs, base, record: prev });
      if (!rm.ok) throw new Error(`removing the previous plugin jar: ${rm.error}`);
      jarChanged = true;
    }
    for (const d of p.datapacks) {
      const target = `${base}/${level}/datapacks/${datapackFile(r.namespace, d.name)}`;
      const cur = await jfs.readFile(target);
      const changed = !cur || sha256(cur) !== d.sha256;
      if (changed) { await jfs.mkdirp(`${base}/${level}/datapacks`); await jfs.writeFile(`${target}.nxeon-part`, d.zip); await jfs.rename(`${target}.nxeon-part`, target); }
      placedDps.push({ name: d.name, target, sha256: d.sha256, apply: d.apply, ...(d.worldgen ? { dimensions: d.worldgen.dimensions } : {}) });
      dpApply.push({ changed, apply: d.apply, worldgen: !!d.worldgen });
    }
    for (const old of prev?.datapacks ?? []) {
      if (placedDps.some((x) => x.target === old.target)) continue;
      if (await jfs.stat(old.target)) await jfs.remove(old.target);
      dpApply.push({ changed: true, apply: old.apply, worldgen: !!old.dimensions?.length });
    }
    if (p.models.length) {
      const cfg = `${base}/${BM_CONFIG_PATH}`;
      const cur = await jfs.readFile(cfg, 256 * 1024);
      const want = Buffer.from((host.betterModelConfig ?? managedConfigTemplate)());
      if (!cur || (cur.toString("utf8").startsWith(CONFIG_MARKER) && !cur.equals(want))) { await jfs.mkdirp(`${base}/plugins/BetterModel`); await jfs.writeFile(cfg, want); managedConfigChanged = true; }
      else if (!cur.toString("utf8").startsWith(CONFIG_MARKER)) t.notes.push("BetterModel's config.yml was changed by the server owner, so Nxeon left it as it is");
      await jfs.mkdirp(`${base}/${BM_MODELS_DIR}`);
      for (const f of p.models) {
        const target = `${base}/${f.rel}`;
        const curm = await jfs.readFile(target, 4 * 1024 * 1024);
        if (!curm || !curm.equals(f.data)) { await jfs.writeFile(`${target}.nxeon-part`, f.data); await jfs.rename(`${target}.nxeon-part`, target); modelsChanged = true; }
        models.push({ target, sha256: sha256(f.data) });
      }
    }
    for (const old of prev?.models ?? []) if (!models.some((m) => m.target === old.target) && (await jfs.stat(old.target))) { await jfs.remove(old.target); modelsChanged = true; }
    return `jar ${jarChanged ? "placed" : r.plugin ? "unchanged" : "none"}; ${placedDps.length} data pack(s); ${models.length} model(s)`;
  }, (v) => v);
  if (wantBm) expectPlugins.push(BETTERMODEL_PLUGIN);
  // 5. the on-server delivery record
  const record: DeliveryRecord = {
    schema: 1, projectId: r.projectId, revisionId: r.revisionId, namespace: r.namespace, mcVersion: r.mcVersion, pluginName: r.plugin?.pluginName ?? null,
    jar, datapacks: placedDps, models, packLoaderIds: loaderIds, managed: [...managedNow].sort(), deliveredAt: (host.now ?? (() => new Date()))().toISOString(),
  };
  await timed(t, "record", async () => { await jfs.mkdirp(DELIVERY_RECORD_DIR); const rp = recordPath(r.projectId); await jfs.writeFile(`${rp}.part`, Buffer.from(JSON.stringify(record, null, 2) + "\n")); await jfs.rename(`${rp}.part`, rp); return rp; }, (v) => v);
  const apply: ApplyInput = { jarChanged, managedChanged, datapacks: dpApply, modelsChanged, managedConfigChanged, loaderChanged };
  const nothing = !jarChanged && !managedChanged && !dpApply.some((d) => d.changed) && !modelsChanged && !managedConfigChanged && !loaderChanged;
  return {
    apply, record, outcome: prev ? "updated" : "delivered", handoff: modelsChanged || managedConfigChanged, unchanged: nothing && !!prev && prev.revisionId === r.revisionId,
    expect: { plugins: [...new Set(expectPlugins.filter((n) => n !== PACK_LOADER_PLUGIN || wantLoader))], datapacks: placedDps.map((d) => datapackId(d.target.slice(d.target.lastIndexOf("/") + 1))), worldgen: dpApply.some((d) => d.changed && d.worldgen) },
  };
}

// ------------------------------------------------------------------------------------------------ uninstall

/** Remove a delivered mod: jar, data packs, models, pack entry; release managed plugins (ref-counted). Dimension
 *  world folders are KEPT (players' builds live there) and listed in `keptWorldFolders` for an admin cleanup action. */
export async function uninstallMod(serverId: string, projectId: string, host: DeliveryHost, opts: DeliverOptions = {}): Promise<DeliveryResult> {
  return transaction({
    serverId, op: "uninstall", subject: { projectId }, host, label: `uninstall-${projectId}`, opts,
    prepare: async (session, steps) => timed({ steps, host }, "preflight", async () => {
      const prev = readRecord(await session.fs.readFile(recordPath(projectId), 1024 * 1024));
      if (!prev) return { body: async (t: Txn) => { await t.jfs.commit(); return { apply: { jarChanged: false, managedChanged: false, datapacks: [], modelsChanged: false, managedConfigChanged: false, loaderChanged: false }, expect: { plugins: [], datapacks: [], worldgen: false }, record: null, outcome: "unchanged" as const, unchanged: true }; } };
      if (prev.packLoaderIds.length) {
        const cur = await readLoaderConfig(session.fs as unknown as GuestFs, session.base);
        if (!cur.ok) throw new Refusal("preflight", `the server's pack config is invalid, so nothing was changed: ${cur.error}`);
      }
      return { body: (t: Txn) => uninstallBody(t, prev) };
    }, () => "delivery record found"),
  });
}

async function uninstallBody(t: Txn, prev: DeliveryRecord): Promise<BodyOut> {
  const { jfs, session, host } = t;
  const base = session.base;
  let managedChanged = false, loaderChanged = false, jarChanged = false, modelsChanged = false;
  const dp: ApplyInput["datapacks"] = [];
  await timed(t, "pack_config", async () => {
    if (!prev.packLoaderIds.length) return "no pack entry";
    const cur = await readLoaderConfig(jfs as unknown as GuestFs, base);
    if (!cur.ok) throw new Error(cur.error);
    const ch = applyPackChange(cur.config, { op: "remove", namespace: prev.namespace, role: PACK_ROLE }, { urlFor: () => "" });
    if (!ch.ok) throw new Error(ch.error);
    if (ch.changed) { await writeLoaderConfig(jfs as unknown as GuestFs, ch.config, base); loaderChanged = true; }
    return ch.action;
  }, (v) => v);
  await timed(t, "place", async () => {
    if (prev.jar) { const rm = await host.jar.remove({ serverId: t.serverId, fs: jfs, base, record: prev }); if (!rm.ok) throw new Error(rm.error); jarChanged = true; }
    for (const d of prev.datapacks) { if (await jfs.stat(d.target)) await jfs.remove(d.target); dp.push({ changed: true, apply: d.apply, worldgen: !!d.dimensions?.length }); }
    for (const m of prev.models) if (await jfs.stat(m.target)) { await jfs.remove(m.target); modelsChanged = true; }
    return `removed jar ${prev.jar ? "yes" : "none"}, ${prev.datapacks.length} data pack(s), ${prev.models.length} model(s)`;
  }, (v) => v);
  await timed(t, "managed", async () => {
    const out: string[] = [];
    for (const key of prev.managed) {
      t.refsTouched = true;
      const rel = await host.managed.release({ serverId: t.serverId, key, dependent: dependentFor(prev.projectId), fs: jfs });
      if (!rel.ok) throw new Error(`${key}: ${rel.error}`);
      if (rel.action === "removed") managedChanged = true;
      out.push(`${key} ${rel.action}`);
    }
    return out.join(", ") || "none held";
  }, (v) => v);
  await timed(t, "record", async () => { await jfs.remove(recordPath(prev.projectId)); return "record removed"; }, (v) => v);
  const kept: string[] = [];
  for (const f of dimensionFolders(base, session.levelName, prev.datapacks.flatMap((d) => d.dimensions ?? []))) if ((await jfs.stat(f))?.type === "dir") kept.push(f);
  if (kept.length) t.notes.push(`The dimension world folder(s) ${kept.join(", ")} were kept (players' builds live there); an admin can delete them.`);
  return {
    apply: { jarChanged, managedChanged, datapacks: dp, modelsChanged, managedConfigChanged: false, loaderChanged }, record: null, outcome: "uninstalled", keptWorldFolders: kept,
    expect: { plugins: [], pluginsGone: prev.pluginName && prev.jar ? [prev.pluginName] : [], datapacks: [], worldgen: dp.some((d) => d.worldgen) },
  };
}

// ------------------------------------------------------------------------------------------------ Mod Packs (same unit)

export async function deliverModPack(serverId: string, built: { manifest: unknown; archive: Map<string, Buffer> }, host: DeliveryHost, opts: DeliverOptions = {}): Promise<DeliveryResult> {
  const env = host.env ?? process.env;
  const v = validateNxPack(built.manifest);
  const packId = v.ok ? v.pack.packId : "unknown";
  return transaction({
    serverId, op: "modpack_install", subject: { packId, versionId: v.ok ? v.pack.versionId : undefined }, host, label: `modpack-${packId}`, opts,
    prepare: async (session, steps) => timed({ steps, host }, "preflight", async () => {
      if (!v.ok) throw new Refusal("preflight", `invalid Mod Pack: ${v.errors[0]?.message ?? "?"}`);
      if (!switches(env).modpacks) throw new Refusal("preflight", "Mod Pack installs are switched off (CYRUS_MODPACK_INSTALL_REAL is not 1); nothing was changed");
      if (!host.modpackPlacer) throw new Refusal("preflight", "this host cannot place Mod Pack members");
      const raw = await session.fs.readFile(`${session.base}/${LOADER_CONFIG_PATH}`, 1024 * 1024);
      if (raw) { let j: unknown; try { j = JSON.parse(raw.toString("utf8")); } catch { throw new Refusal("preflight", "the server's packs.json is not valid JSON; nothing was changed"); } if (!validateLoaderConfig(j).ok) throw new Refusal("preflight", "the server's packs.json is invalid; nothing was changed"); }
      const wg = v.pack.members.length > 0 && false;
      return { precheckRestart: { worldgen: wg, creatures: false }, body: (t: Txn) => modpackBody(t, v.pack.packId, v.pack.resourcePacks.packs.length > 0, (fs) => installModPackUnit({ manifest: built.manifest, archive: built.archive, base: session.base, levelName: session.levelName, deps: { fs, placer: host.modpackPlacer!(fs, session, packId), fetch: host.fetchArtifact, publish: host.packs ? (zip, s) => host.packs!.publish(zip, s) : undefined } }), v.pack.members.filter((m) => m.kind === "plugin").map((m) => m.label)) };
    }, () => "manifest valid"),
  });
}

export async function uninstallModPack(serverId: string, packId: string, host: DeliveryHost, opts: DeliverOptions = {}): Promise<DeliveryResult> {
  const env = host.env ?? process.env;
  return transaction({
    serverId, op: "modpack_uninstall", subject: { packId }, host, label: `modpack-${packId}-uninstall`, opts,
    prepare: async (_session, steps) => timed({ steps, host }, "preflight", async () => {
      if (!/^mp_[A-Za-z0-9]{12}$/.test(packId)) throw new Refusal("preflight", "bad pack id");
      if (!switches(env).modpacks) throw new Refusal("preflight", "Mod Pack installs are switched off (CYRUS_MODPACK_INSTALL_REAL is not 1); nothing was changed");
      if (!host.modpackPlacer) throw new Refusal("preflight", "this host cannot place Mod Pack members");
      return { body: (t: Txn) => modpackBody(t, packId, false, (fs) => uninstallModPackUnit({ packId, base: t.session.base, deps: { fs, placer: host.modpackPlacer!(fs, t.session, packId) } }), [], true) };
    }, () => "ok"),
  });
}

async function modpackBody(t: Txn, packId: string, needsLoader: boolean, run: (fs: JournalFs) => Promise<UnitResult>, pluginLabels: string[], uninstall = false): Promise<BodyOut> {
  const dep = packDependent(packId);
  let managedChanged = false;
  const expect: string[] = [];
  if (needsLoader) {
    await timed(t, "managed", async () => {
      t.refsTouched = true;
      const e = await t.host.managed.ensure({ serverId: t.serverId, key: PACK_LOADER_KEY, mcVersion: t.session.mcVersion ?? "", dependent: dep, fs: t.jfs });
      if (!e.ok) throw new Error(e.error);
      managedChanged = e.action === "installed" || e.action === "upgraded";
      expect.push(e.pluginName);
      return e.action;
    }, (v) => v);
  } else skip(t, "managed", "no resource packs");
  const unit = await timed(t, "place", async () => {
    const u = await run(t.jfs);
    if (!u.ok) throw new Error(`Mod Pack ${u.step}: ${u.error}`);
    return u;
  }, (u) => `${u.ok ? u.action : ""}: ${u.ok ? u.changed.slice(0, 6).join(", ") : ""}`);
  if (uninstall) {
    await timed(t, "managed", async () => { t.refsTouched = true; const r = await t.host.managed.release({ serverId: t.serverId, key: PACK_LOADER_KEY, dependent: dep, fs: t.jfs }); if (!r.ok) throw new Error(r.error); if (r.action === "removed") managedChanged = true; return r.action; }, (v) => v);
  }
  const u = unit as Extract<UnitResult, { ok: true }>;
  const datapacks = (u.record?.files ?? []).filter((f) => f.path.includes("/datapacks/")).map((f) => datapackId(f.path.slice(f.path.lastIndexOf("/") + 1)));
  return {
    apply: { jarChanged: u.restartRequired, managedChanged, datapacks: datapacks.map(() => ({ changed: u.action !== "unchanged", apply: "reload" as const, worldgen: false })), modelsChanged: false, managedConfigChanged: false, loaderChanged: needsLoader && u.action !== "unchanged" },
    record: null, outcome: uninstall ? "uninstalled" : u.action === "updated" ? "updated" : "delivered", unchanged: u.action === "unchanged" && !managedChanged,
    expect: { plugins: uninstall ? [] : [...expect, ...pluginLabels.map((l) => l.replace(/ .*$/, ""))].filter(Boolean), datapacks: uninstall ? [] : datapacks, worldgen: false },
  };
}

