// Test helper: a fake DeliveryHost over a real temp directory (LocalGuestFs), with a fake "server process" whose boot
// outcome is derived from the files on disk (plugin.yml names, a broken-worldgen marker inside a data pack), in-memory
// managed-plugin refs, a fake pack store, and fault hooks. Used by test/cyrus-delivery.test.ts.
import { createHash } from "node:crypto";
import { mkdtempSync, readdirSync, readFileSync, rmSync, statSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";
import { LocalGuestFs } from "../lib/mods/guest-fs";
import { inspectJar } from "../lib/cyrus/inventory/jar";
import { indexZip } from "../lib/cyrus/inventory/zipread";
import { zip } from "../lib/cyrus/textures/zip";
import type { DeliveryHost, DeliveryStep, HealthReport, ServerSession, TxnFs } from "../lib/cyrus/delivery/types";

export const BASE = "/opt/mc";
export const BROKEN_MARKER = "data/nx_broken01/worldgen/noise_settings/broken.json";
export const h = (b: Buffer | string) => createHash("sha256").update(b).digest("hex");
export const pluginJar = (name: string, extra = "") => zip([{ path: "plugin.yml", data: Buffer.from(`name: ${name}\nversion: 1.0.0${extra}\nmain: dev.cyrus.${name.toLowerCase()}.Main\napi-version: "1.21"\n`) }]);

/** Wrap an fs: throw on the Nth mutating call (counting writeFile/mkdirp/rename/remove/copy). */
export class FaultFs implements TxnFs {
  ops = 0;
  constructor(readonly inner: TxnFs, public failAt = 0) {}
  private tick(op: string, p: string) { this.ops++; if (this.failAt && this.ops === this.failAt) throw new Error(`injected fault at op ${this.ops} (${op} ${p})`); }
  stat(p: string) { return this.inner.stat(p); }
  readFile(p: string, m?: number) { return this.inner.readFile(p, m); }
  list(d: string) { return this.inner.list(d); }
  async writeFile(p: string, d: Buffer) { this.tick("writeFile", p); return this.inner.writeFile(p, d); }
  async mkdirp(p: string) { this.tick("mkdirp", p); return this.inner.mkdirp(p); }
  async rename(a: string, b: string) { this.tick("rename", b); return this.inner.rename(a, b); }
  async remove(p: string) { this.tick("remove", p); return this.inner.remove(p); }
  async copy(a: string, b: string) { this.tick("copy", b); return this.inner.copy(a, b); }
}

export type FakeOpts = {
  restartFails?: number; // fail this many restarts
  failStep?: DeliveryStep;
  failAtOp?: number;
  noConsole?: boolean;
  env?: Record<string, string>;
};

export class FakeServer {
  readonly dir = mkdtempSync(path.join(tmpdir(), "cyrus-deliv-"));
  readonly raw = new LocalGuestFs(this.dir);
  refs = new Map<string, { dependents: string[]; installed: boolean }>();
  restarts = 0;
  consoleLog: string[] = [];
  published = new Map<string, Buffer>();
  booted: HealthReport;
  opens = 0;
  constructor() { this.booted = this.boot(); }
  cleanup() { rmSync(this.dir, { recursive: true, force: true }); }

  /** sha256 of every file + every directory path under the root (excluding the journal root when asked). */
  tree(opts: { excludeJournal?: boolean } = {}): string {
    const out: string[] = [];
    const walk = (d: string) => {
      for (const n of readdirSync(d).sort()) {
        const p = path.join(d, n), rel = path.relative(this.dir, p);
        if (opts.excludeJournal && rel.startsWith("root/.nxeon-cyrus/delivery-journal")) continue;
        if (statSync(p).isDirectory()) { out.push(`D ${rel}`); walk(p); } else out.push(`F ${rel} ${h(readFileSync(p))}`);
      }
    };
    walk(this.dir);
    return h(out.join("\n"));
  }
  files(rel: string): string[] { try { return readdirSync(path.join(this.dir, rel)).sort(); } catch { return []; } }
  read(rel: string): Buffer | null { try { return readFileSync(path.join(this.dir, rel)); } catch { return null; } }

  /** What a boot of the current files gives. */
  boot(): HealthReport {
    const errorLines: string[] = [];
    const enabled: string[] = [];
    for (const f of this.files("opt/mc/plugins").filter((n) => n.endsWith(".jar"))) {
      const b = this.read(`opt/mc/plugins/${f}`)!;
      const name = inspectJar(f, `plugins/${f}`, b, { bytecode: false }).descriptor?.name;
      if (!name) continue;
      if (/Broken/.test(name)) { errorLines.push(`[12:00:00 ERROR]: Error occurred while enabling ${name} v1.0.0`); continue; }
      enabled.push(name);
    }
    const dps = this.files("opt/mc/world/datapacks").filter((n) => n.endsWith(".zip"));
    const broken = dps.some((n) => { const z = indexZip(this.read(`opt/mc/world/datapacks/${n}`)!); return z.ok && z.zip.entries.some((e) => e.name === BROKEN_MARKER); });
    if (broken) return { real: true, cameUp: false, answered: false, pluginsEnabled: [], errorLines: ["[12:00:00 ERROR]: Registry loading errors: Failed to load nx_broken01:broken"], datapacksLoaded: [], evidence: ["no Done line"] };
    return { real: true, cameUp: true, answered: true, pluginsEnabled: enabled, errorLines, datapacksLoaded: dps.map((n) => `file/${n}`), evidence: ["Done (1.0s)!"] };
  }

  host(o: FakeOpts = {}): DeliveryHost {
    const srv = this;
    let restartFails = o.restartFails ?? 0;
    const fs: TxnFs = o.failAtOp ? new FaultFs(this.raw, o.failAtOp) : this.raw;
    const session: ServerSession = {
      fs, base: BASE, levelName: "world", mcVersion: "1.21.11",
      async restart() { srv.restarts++; if (restartFails > 0) { restartFails--; return { ok: false, error: "systemctl restart timed out" }; } srv.booted = srv.boot(); return { ok: true }; },
      ...(o.noConsole ? {} : { async console(cmd: string) { srv.consoleLog.push(cmd); if (cmd === "minecraft:reload") { const b = srv.boot(); srv.booted = { ...srv.booted, datapacksLoaded: b.cameUp ? b.datapacksLoaded : srv.booted.datapacksLoaded }; } return { ok: true as const, reply: "ok" }; } }),
      async health() { return srv.booted; },
      async baselineErrors() { return srv.booted.errorLines; },
    };
    const writeJar = async (f: TxnFs, target: string, data: Buffer) => { await f.writeFile(`${target}.nxeon-part`, data); await f.rename(`${target}.nxeon-part`, target); };
    return {
      env: { CYRUS_DELIVERY: "1", CYRUS_MANAGED_PLUGINS_REAL: "1", CYRUS_DATAPACK_DELIVERY_REAL: "1", CYRUS_DATAPACK_STUDIO: "1", CYRUS_WORLDGEN: "1", CYRUS_MODPACK_INSTALL_REAL: "1", ...(o.env ?? {}) },
      now: () => new Date("2026-10-10T12:00:00Z"),
      fault: (step) => { if (o.failStep === step) throw new Error(`injected fault at step ${step}`); },
      async open() { srv.opens++; return session; },
      managed: {
        async ensure({ serverId, key, dependent, fs: f }) {
          const k = `${serverId}:${key}`; const r = srv.refs.get(k) ?? { dependents: [], installed: false };
          const pluginName = key === "bettermodel" ? "BetterModel" : "NxeonPackLoader";
          let action: "installed" | "ref_added" | "already" = r.dependents.includes(dependent) ? "already" : "ref_added";
          if (!r.installed) { await writeJar(f, `${BASE}/plugins/${pluginName}-0.1.0.jar`, pluginJar(pluginName)); r.installed = true; action = "installed"; }
          r.dependents = [...new Set([...r.dependents, dependent])].sort();
          srv.refs.set(k, r);
          return { ok: true, action, pluginName };
        },
        async release({ serverId, key, dependent, fs: f }) {
          const k = `${serverId}:${key}`; const r = srv.refs.get(k);
          if (!r || !r.dependents.includes(dependent)) return { ok: true, action: "not_held" };
          r.dependents = r.dependents.filter((d) => d !== dependent);
          if (!r.dependents.length) { await f.remove(`${BASE}/plugins/${key === "bettermodel" ? "BetterModel" : "NxeonPackLoader"}-0.1.0.jar`); r.installed = false; srv.refs.set(k, r); return { ok: true, action: "removed" }; }
          return { ok: true, action: "ref_dropped" };
        },
        async snapshot() { return JSON.stringify([...srv.refs.entries()]); },
        async restore(_s, snap) { srv.refs = new Map(JSON.parse(String(snap))); return { ok: true }; },
      },
      jar: {
        async install({ fs: f, base, release, previous }) {
          const target = `${base}/plugins/${release.plugin!.jarName}`;
          if (previous?.jar && previous.jar.target !== target && (await f.stat(previous.jar.target))) await f.remove(previous.jar.target);
          await writeJar(f, target, release.plugin!.bytes);
          return { ok: true, target };
        },
        async remove({ fs: f, record }) { if (record.jar && (await f.stat(record.jar.target))) await f.remove(record.jar.target); return { ok: true }; },
      },
      packs: { async publish(z, sha1) { srv.published.set(sha1, z); return { url: `https://packs.example.invalid/p/${sha1}.zip` }; } },
    };
  }
}

/** A fresh tiny server: server.properties, one unrelated plugin, an empty datapacks folder, a log. */
export function seedServer(s: FakeServer) {
  const w = (rel: string, data: Buffer | string) => { const p = path.join(s.dir, rel); require("node:fs").mkdirSync(path.dirname(p), { recursive: true }); require("node:fs").writeFileSync(p, data); };
  w("opt/mc/server.properties", "level-name=world\nmotd=test\n");
  w("opt/mc/plugins/Unrelated.jar", pluginJar("Unrelated"));
  w("opt/mc/world/datapacks/.keep", "");
  w("opt/mc/logs/latest.log", "[12:00:00 INFO]: This server is running Paper version 1.21.11-132 (MC: 1.21.11)\n[12:00:00 INFO]: Done (1.0s)! For help, type \"help\"\n");
  w("opt/mc/version_history.json", JSON.stringify({ currentVersion: "1.21.11-132 (MC: 1.21.11)" }));
  s.booted = s.boot();
}

