// Cyrus R5 delivery orchestrator: fake-host + fault-injection tests. Every failure after preflight must restore the
// EXACT previous bytes (and folders) of the server dir and the managed-plugin refs; worldgen that stops the server,
// a failing restart, an update, an uninstall (world folders kept), Mod Packs through the same unit, the journal
// recovery, the flags and the restart policy.
//   tsx --test test/cyrus-delivery.test.ts
import { describe, it, afterEach } from "node:test";
import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { mkdirSync, writeFileSync } from "node:fs";
import path from "node:path";
import { deliverMod, uninstallMod, deliverModPack, uninstallModPack } from "../lib/cyrus/delivery/orchestrator";
import { JournalFs, pendingJournals, recoverJournal } from "../lib/cyrus/delivery/journal";
import { planApply, judgeHealth, dimensionFolders, switches } from "../lib/cyrus/delivery/plan";
import type { ModRelease, DeliveryStep } from "../lib/cyrus/delivery/types";
import { fsPlacer } from "../lib/cyrus/modpack/install";
import { buildModPack, type MemberInput, type BuildOk } from "../lib/cyrus/modpack/builder";
import { zip } from "../lib/cyrus/textures/zip";
import { dpZip, goodMod, jarOf, rpZip } from "./_cyrus-modfixture";
import { FakeServer, seedServer, pluginJar, BROKEN_MARKER, h } from "./_cyrus-delivery-fakehost";

const NS = "nx_deliv001";
const sha1 = (b: Buffer) => createHash("sha1").update(b).digest("hex");
const mod = goodMod(NS, "alpha");
const JAR = jarOf(mod);
const RP = rpZip(mod);
const DP = dpZip(mod);
const WG = zip([{ path: "pack.mcmeta", data: Buffer.from('{"pack":{"pack_format":94,"description":"wg"}}') }, { path: `data/${NS}/worldgen/biome/glade.json`, data: Buffer.from("{}") }, { path: `data/${NS}/dimension/glade.json`, data: Buffer.from("{}") }]);
const BROKEN = zip([{ path: "pack.mcmeta", data: Buffer.from('{"pack":{"pack_format":94,"description":"broken"}}') }, { path: BROKEN_MARKER, data: Buffer.from("{}") }]);

function release(over: Partial<ModRelease> = {}): ModRelease {
  return {
    projectId: "cp_alpha01", revisionId: "rev_1", namespace: NS, mcVersion: "1.21.11", label: "NxAlpha",
    plugin: { pluginName: mod.name, jarName: `${mod.name}-1.0.0.jar`, sha256: h(JAR), bytes: JAR },
    pack: { sha1: sha1(RP), zip: RP, prompt: "NxAlpha uses custom textures.", required: false },
    datapacks: [{ name: "alpha", zip: DP, sha256: h(DP), apply: "reload" }],
    creatures: [], ...over,
  };
}
const servers: FakeServer[] = [];
function fresh(): FakeServer { const s = new FakeServer(); seedServer(s); servers.push(s); return s; }
afterEach(() => { while (servers.length) servers.pop()!.cleanup(); });
const MUTATING: DeliveryStep[] = ["managed", "host_pack", "pack_config", "place", "record", "apply", "health"];

describe("plan (pure)", () => {
  it("apply semantics: restart for jars/worldgen/creatures, reload for reloadable data packs, nothing for config only", () => {
    const none = { jarChanged: false, managedChanged: false, datapacks: [], modelsChanged: false, managedConfigChanged: false, loaderChanged: false };
    assert.equal(planApply({ ...none, jarChanged: true }).mode, "restart");
    assert.equal(planApply({ ...none, datapacks: [{ changed: true, apply: "reload", worldgen: false }] }).mode, "reload");
    const wg = planApply({ ...none, datapacks: [{ changed: true, apply: "restart", worldgen: true }] });
    assert.equal(wg.mode, "restart"); assert.ok(wg.requireCameUp); assert.match(wg.reasons.join(" "), /world generation/);
    assert.equal(planApply({ ...none, datapacks: [{ changed: true, apply: "restart", worldgen: false }] }).mode, "restart");
    const cr = planApply({ ...none, modelsChanged: true }); assert.equal(cr.mode, "restart"); assert.ok(cr.handoff);
    const lc = planApply({ ...none, loaderChanged: true }); assert.equal(lc.mode, "none"); assert.deepEqual(lc.consoleAfter, ["nxpacks reload"]);
    assert.equal(planApply({ ...none, datapacks: [{ changed: false, apply: "reload", worldgen: false }] }).mode, "none");
  });
  it("health judge: simulated is never a pass; new error lines only; worldgen wording", () => {
    const ok = { real: true, cameUp: true, answered: true, pluginsEnabled: ["A"], errorLines: ["[10:00:00 ERROR]: old"], datapacksLoaded: ["file/x.zip"], evidence: [] };
    assert.ok(judgeHealth({ plugins: ["a"], datapacks: ["file/x.zip"], worldgen: false }, ok, ["[09:00:00 ERROR]: old"]).ok);
    assert.ok(!judgeHealth({ plugins: [], datapacks: [], worldgen: false }, { ...ok, real: false }).ok);
    assert.match(judgeHealth({ plugins: [], datapacks: [], worldgen: true }, { ...ok, cameUp: false }).problems.join(), /did not come up/);
    assert.ok(!judgeHealth({ plugins: ["B"], datapacks: [], worldgen: false }, ok, ["[x ERROR]: old"]).ok);
    assert.ok(!judgeHealth({ plugins: [], datapacks: [], worldgen: false }, { ...ok, errorLines: ["[1 ERROR]: new"] }).ok);
    assert.ok(!judgeHealth({ plugins: [], datapacks: [], worldgen: false }, null).ok);
  });
  it("dimension folders + switches", () => {
    assert.deepEqual(dimensionFolders("/opt/mc", "world", ["nx_a:glade", "bad id", "nx_a:glade"]), ["/opt/mc/world/dimensions/nx_a/glade"]);
    assert.deepEqual(switches({}), { delivery: false, managed: false, datapacks: false, worldgen: false, creatures: false, modpacks: false });
  });
});

describe("deliverMod", () => {
  it("is OFF without CYRUS_DELIVERY=1: refuses before opening the server", async () => {
    const s = fresh(); const before = s.tree();
    const r = await deliverMod("srv1", release(), { ...s.host(), env: {} });
    assert.equal(r.outcome, "refused"); assert.match(r.error!, /CYRUS_DELIVERY/); assert.equal(s.opens, 0); assert.equal(s.tree(), before);
  });

  it("fresh install: Pack Loader + pack + config + jar + data pack, restart, healthy, record, journal gone", async () => {
    const s = fresh();
    const r = await deliverMod("srv1", release(), s.host());
    assert.equal(r.outcome, "delivered", JSON.stringify(r, null, 1));
    assert.ok(r.ok);
    assert.equal(r.apply?.mode, "restart"); assert.equal(s.restarts, 1);
    assert.ok(r.health?.ok);
    assert.deepEqual(r.steps.filter((x) => x.status === "failed"), []);
    assert.ok(s.files("opt/mc/plugins").includes("NxAlpha-1.0.0.jar") && s.files("opt/mc/plugins").includes("NxeonPackLoader-0.1.0.jar"));
    const cfg = JSON.parse(s.read("opt/mc/plugins/NxeonPackLoader/packs.json")!.toString());
    assert.equal(cfg.packs.length, 1); assert.equal(cfg.packs[0].sha1, sha1(RP)); assert.match(cfg.packs[0].url, /^https:\/\/packs\.example\.invalid\/p\//);
    assert.ok(s.files("opt/mc/world/datapacks").includes(`nxeon-${NS}-alpha.zip`));
    assert.ok(s.read("root/.nxeon-cyrus/deliveries/cp_alpha01.json"));
    assert.deepEqual(s.files("root/.nxeon-cyrus/delivery-journal"), []);
    assert.deepEqual(s.refs.get("srv1:nxeon-pack-loader")?.dependents, ["project:cp_alpha01"]);
    assert.ok(s.published.has(sha1(RP)));
    // same revision again = unchanged, no restart
    const again = await deliverMod("srv1", release(), s.host());
    assert.equal(again.outcome, "unchanged"); assert.equal(s.restarts, 1);
  });

  for (const step of MUTATING) {
    it(`fault at step "${step}" restores the exact previous bytes and refs`, async () => {
      const s = fresh(); const before = s.tree(); const refs = JSON.stringify([...s.refs]);
      const r = await deliverMod("srv1", release(), s.host({ failStep: step }));
      assert.equal(r.outcome, "rolled_back", JSON.stringify(r.steps));
      assert.equal(r.failedStep, step);
      assert.ok(r.rollback?.ok, JSON.stringify(r.rollback));
      assert.equal(s.tree(), before);
      assert.equal(JSON.stringify([...s.refs]), refs);
      // a restart that had happened is undone by a second restart onto the previous state
      if (step === "health") { assert.equal(r.rollback?.restarted, true); assert.ok(r.rollback?.health?.ok); }
    });
  }

  it("a fault at EVERY single file operation (exhaustive) rolls back exactly", async () => {
    const probe = fresh();
    const ok = await deliverMod("srv1", release(), probe.host({ failAtOp: 1e9 }));
    assert.ok(ok.ok);
    const fs0 = (probe.host({ failAtOp: 1e9 }));
    void fs0;
    // count ops of a clean run
    const counter = fresh();
    const host = counter.host({ failAtOp: 1e9 });
    const sess = await host.open("x"); const total = () => (sess.fs as unknown as { ops: number }).ops;
    host.open = async () => sess;
    await deliverMod("srv1", release(), host);
    const N = total();
    assert.ok(N > 20, `only ${N} ops`);
    let rolled = 0;
    for (let i = 1; i <= N; i++) {
      const s = fresh(); const before = s.tree(); const refs = JSON.stringify([...s.refs]);
      const r = await deliverMod("srv1", release(), s.host({ failAtOp: i }));
      if (r.ok) { assert.equal(r.outcome, "delivered"); continue; } // a fault in a tolerated cleanup (journal commit)
      rolled++;
      assert.equal(r.outcome, "rolled_back", `op ${i}: ${r.error} ${JSON.stringify(r.rollback)}`);
      assert.equal(s.tree(), before, `op ${i} (${r.error}) left a different tree`);
      assert.equal(JSON.stringify([...s.refs]), refs, `op ${i}: refs`);
      s.cleanup();
    }
    assert.ok(rolled >= N - 3, `${rolled}/${N} rolled back`);
  });

  it("restart fails once: rolled back, restarted again onto the previous state", async () => {
    const s = fresh(); const before = s.tree();
    const r = await deliverMod("srv1", release(), s.host({ restartFails: 1 }));
    assert.equal(r.outcome, "rolled_back"); assert.equal(r.failedStep, "apply"); assert.match(r.error!, /restart failed/);
    assert.equal(r.rollback?.restarted, true); assert.ok(r.rollback?.health?.ok);
    assert.equal(s.tree(), before); assert.equal(s.restarts, 2);
  });

  it("restart keeps failing: files restored, outcome rollback_incomplete (server not confirmed up)", async () => {
    const s = fresh(); const before = s.tree();
    const r = await deliverMod("srv1", release(), s.host({ restartFails: 5 }));
    assert.equal(r.outcome, "rollback_incomplete"); assert.ok(r.rollback?.ok); assert.equal(r.rollback?.restarted, false);
    assert.equal(s.tree(), before);
  });

  it("a broken world generation pack that stops the server is rolled back and the server comes up again", async () => {
    const s = fresh(); const before = s.tree();
    const r = await deliverMod("srv1", release({ datapacks: [{ name: "brokenwg", zip: BROKEN, sha256: h(BROKEN), apply: "restart", worldgen: { dimensions: ["nx_broken01:nowhere"] } }] }), s.host());
    assert.equal(r.outcome, "rolled_back", JSON.stringify(r.steps));
    assert.equal(r.failedStep, "health");
    assert.match(r.error!, /did not come up/);
    assert.equal(r.rollback?.restarted, true); assert.ok(r.rollback?.health?.ok); assert.ok(s.booted.cameUp);
    assert.equal(s.tree(), before);
  });

  it("a plugin that fails to enable is rolled back", async () => {
    const s = fresh(); const before = s.tree();
    const bad = pluginJar("NxBroken");
    const r = await deliverMod("srv1", release({ plugin: { pluginName: "NxBroken", jarName: "NxBroken-1.0.0.jar", sha256: h(bad), bytes: bad }, pack: null, datapacks: [] }), s.host());
    assert.equal(r.outcome, "rolled_back"); assert.match(r.error!, /NxBroken is not enabled|new error lines/);
    assert.equal(s.tree(), before);
  });

  it("update v1 -> v2 (new jar, data pack dropped, worldgen added); a fault at each step restores v1 exactly", async () => {
    const v2jar = jarOf({ ...mod, commands: [{ name: "alphagem2", aliases: [] }] });
    const v2 = release({ revisionId: "rev_2", plugin: { pluginName: mod.name, jarName: `${mod.name}-1.1.0.jar`, sha256: h(v2jar), bytes: v2jar }, datapacks: [{ name: "glade", zip: WG, sha256: h(WG), apply: "restart", worldgen: { dimensions: [`${NS}:glade`] } }] });
    for (const step of [...MUTATING, null]) {
      const s = fresh();
      assert.ok((await deliverMod("srv1", release(), s.host())).ok);
      const v1tree = s.tree(); const v1refs = JSON.stringify([...s.refs]);
      const r = await deliverMod("srv1", v2, s.host(step ? { failStep: step } : {}));
      if (!step) {
        assert.equal(r.outcome, "updated", JSON.stringify(r.steps));
        assert.ok(!s.files("opt/mc/plugins").includes("NxAlpha-1.0.0.jar") && s.files("opt/mc/plugins").includes("NxAlpha-1.1.0.jar"));
        assert.deepEqual(s.files("opt/mc/world/datapacks").filter((n) => n.endsWith(".zip")), [`nxeon-${NS}-glade.zip`]);
        assert.equal(r.apply?.mode, "restart");
      } else {
        assert.equal(r.outcome, "rolled_back", `${step}: ${r.error}`);
        assert.equal(s.tree(), v1tree, `update fault at ${step}`);
        assert.equal(JSON.stringify([...s.refs]), v1refs);
      }
      s.cleanup();
    }
  });

  it("a data pack only change is applied with minecraft:reload (no restart)", async () => {
    const s = fresh();
    assert.ok((await deliverMod("srv1", release(), s.host())).ok);
    const dp2 = dpZip({ ...mod, dp: { ...mod.dp!, [`data/${NS}/function/tick.mcfunction`]: "say tock" } });
    const r = await deliverMod("srv1", release({ revisionId: "rev_1b", datapacks: [{ name: "alpha", zip: dp2, sha256: h(dp2), apply: "reload" }] }), s.host());
    assert.equal(r.outcome, "updated"); assert.equal(r.apply?.mode, "reload"); assert.equal(s.restarts, 1);
    assert.ok(s.consoleLog.includes("minecraft:reload"));
  });

  it("blocking conflict (same plugin name already on the server) refuses and changes nothing", async () => {
    const s = fresh();
    writeFileSync(path.join(s.dir, "opt/mc/plugins/OtherCopy.jar"), JAR);
    const before = s.tree();
    const r = await deliverMod("srv1", release(), s.host());
    assert.equal(r.outcome, "refused"); assert.ok(r.conflicts?.blocking.some((b) => b.class === "plugin.duplicate_name"));
    assert.equal(s.tree(), before); assert.equal(s.restarts, 0);
  });

  it("parts whose switch is off are left out with a note", async () => {
    const s = fresh();
    const r = await deliverMod("srv1", release(), s.host({ env: { CYRUS_DATAPACK_DELIVERY_REAL: "0", CYRUS_MANAGED_PLUGINS_REAL: "0" } }));
    assert.ok(r.ok); assert.ok(r.notes.some((n) => /data pack alpha was not delivered/.test(n)) && r.notes.some((n) => /resource pack was not delivered/.test(n)));
    assert.ok(!s.read("opt/mc/plugins/NxeonPackLoader/packs.json"));
  });

  it("restart policy next_restart: plain jar = pending_restart; world generation = refused", async () => {
    const s = fresh();
    const r = await deliverMod("srv1", release({ pack: null, datapacks: [] }), s.host(), { restartPolicy: "next_restart" });
    assert.equal(r.outcome, "pending_restart"); assert.equal(s.restarts, 0);
    const s2 = fresh(); const before = s2.tree();
    const r2 = await deliverMod("srv1", release({ datapacks: [{ name: "glade", zip: WG, sha256: h(WG), apply: "restart", worldgen: { dimensions: [`${NS}:glade`] } }] }), s2.host(), { restartPolicy: "next_restart" });
    assert.equal(r2.outcome, "refused"); assert.equal(s2.tree(), before);
  });

  it("a release whose bytes do not match is refused before anything", async () => {
    const s = fresh(); const before = s.tree();
    const r = await deliverMod("srv1", release({ plugin: { pluginName: mod.name, jarName: "x.jar", sha256: "0".repeat(64), bytes: JAR } }), s.host());
    assert.equal(r.outcome, "refused"); assert.equal(s.tree(), before);
  });
});

describe("uninstallMod", () => {
  it("removes jar, data packs, pack entry, releases the Pack Loader; keeps and lists the dimension folder", async () => {
    const s = fresh();
    assert.ok((await deliverMod("srv1", release({ datapacks: [{ name: "glade", zip: WG, sha256: h(WG), apply: "restart", worldgen: { dimensions: [`${NS}:glade`] } }] }), s.host())).ok);
    mkdirSync(path.join(s.dir, `opt/mc/world/dimensions/${NS}/glade/region`), { recursive: true });
    writeFileSync(path.join(s.dir, `opt/mc/world/dimensions/${NS}/glade/region/r.0.0.mca`), "chunks");
    const installed = s.tree();
    for (const step of ["pack_config", "place", "managed", "record", "apply", "health"] as DeliveryStep[]) {
      const f = await uninstallMod("srv1", "cp_alpha01", s.host({ failStep: step }));
      assert.equal(f.outcome, "rolled_back", `${step}: ${f.error}`); assert.equal(s.tree(), installed, `uninstall fault ${step}`);
    }
    const r = await uninstallMod("srv1", "cp_alpha01", s.host());
    assert.equal(r.outcome, "uninstalled", JSON.stringify(r.steps));
    assert.ok(!s.files("opt/mc/plugins").some((n) => n.startsWith("NxAlpha") || n.startsWith("NxeonPackLoader-")));
    assert.deepEqual(s.files("opt/mc/world/datapacks").filter((n) => n.endsWith(".zip")), []);
    assert.deepEqual(r.keptWorldFolders, [`/opt/mc/world/dimensions/${NS}/glade`]);
    assert.ok(s.read(`opt/mc/world/dimensions/${NS}/glade/region/r.0.0.mca`));
    assert.equal(JSON.parse(s.read("opt/mc/plugins/NxeonPackLoader/packs.json")!.toString()).packs.length, 0);
    assert.deepEqual(s.refs.get("srv1:nxeon-pack-loader")?.dependents, []);
    assert.equal((await uninstallMod("srv1", "cp_alpha01", s.host())).outcome, "unchanged");
  });
  it("a second mod keeps the shared Pack Loader (ref-counted)", async () => {
    const s = fresh();
    assert.ok((await deliverMod("srv1", release(), s.host())).ok);
    const m2 = goodMod("nx_deliv002", "beta"); const j2 = jarOf(m2); const rp2 = rpZip(m2);
    assert.ok((await deliverMod("srv1", { ...release(), projectId: "cp_beta01", namespace: "nx_deliv002", label: "NxBeta", plugin: { pluginName: m2.name, jarName: "NxBeta-1.0.0.jar", sha256: h(j2), bytes: j2 }, pack: { sha1: sha1(rp2), zip: rp2, prompt: "b", required: false }, datapacks: [] }, s.host())).ok);
    const r = await uninstallMod("srv1", "cp_alpha01", s.host());
    assert.ok(r.ok);
    assert.ok(s.files("opt/mc/plugins").includes("NxeonPackLoader-0.1.0.jar"));
    assert.deepEqual(s.refs.get("srv1:nxeon-pack-loader")?.dependents, ["project:cp_beta01"]);
    assert.equal(JSON.parse(s.read("opt/mc/plugins/NxeonPackLoader/packs.json")!.toString()).packs.length, 1);
  });
});

describe("journal recovery", () => {
  it("a left-over journal refuses the next delivery; recoverJournal restores the exact bytes", async () => {
    const s = fresh(); const before = s.tree();
    const j = new JournalFs(s.raw, { id: "crashed01" });
    await j.writeFile("/opt/mc/plugins/Unrelated.jar", Buffer.from("half-written"));
    await j.writeFile("/opt/mc/plugins/new/a.txt", Buffer.from("new"));
    await j.remove("/opt/mc/world");
    assert.deepEqual(await pendingJournals(s.raw), ["crashed01"]);
    const r = await deliverMod("srv1", release(), s.host());
    assert.equal(r.outcome, "refused"); assert.equal(r.failedStep, "recover_check");
    const rec = await recoverJournal(s.raw, "crashed01");
    assert.ok(rec.ok, JSON.stringify(rec));
    assert.equal(s.tree(), before);
    assert.deepEqual(await pendingJournals(s.raw), []);
  });
});

describe("Mod Packs through the same orchestrator", () => {
  const A = "nx_aaaa1111", B = "nx_bbbb2222";
  const members = (): MemberInput[] => [A, B].flatMap((ns, i) => {
    const m = goodMod(ns, i ? "beta" : "alpha");
    const project = { projectId: `cp_${m.tag}`, revisionId: `rev_${m.tag}`, namespace: ns };
    return [
      { id: m.tag, kind: "plugin", origin: "cyrus", label: m.name, version: "1.0.0", project, artifact: { name: `${m.name}.jar`, bytes: jarOf(m) } },
      { id: `${m.tag}-rp`, kind: "resourcepack", origin: "cyrus", label: `${m.name} pack`, version: "1.0.0", project, artifact: { name: `${m.tag}-rp.zip`, bytes: rpZip(m) } },
    ] as MemberInput[];
  });
  const build = async () => { const b = await buildModPack({ packId: "mp_testpack0001", name: "Pack", mcVersion: "1.21.11", members: members() }); assert.ok(b.ok, JSON.stringify(!b.ok && b.errors)); return b as BuildOk; };
  const hostFor = (s: FakeServer, o = {}) => ({ ...s.host(o), modpackPlacer: (fs: import("../lib/cyrus/delivery/types").TxnFs) => fsPlacer(fs) });

