  }
  it("Mod Packs are refused while CYRUS_MODPACK_INSTALL_REAL is off", async () => {
    const b = await build(); const s = fresh();
    const r = await deliverModPack("srv1", { manifest: b.manifest, archive: new Map(b.archive.map((f) => [f.path, f.data])) }, hostFor(s, { env: { CYRUS_MODPACK_INSTALL_REAL: "0" } }));
    assert.equal(r.outcome, "refused");
  });
});

