// Cyrus R5: the engine release record (portal + build-service halves) and the Test Flight gate (pure + fake invoker).
//   tsx --test test/cyrus-gate-release.test.ts
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { mkdtempSync, mkdirSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";
import { createHash } from "node:crypto";
import { buildEngineRelease, readEngineRelease, verifyEngineRelease, type SvcRelease } from "../lib/cyrus/engine-core/release";
import { validateEngineRecord } from "../lib/cyrus/engine-core/revisions";
import { readCyrusMeta } from "../lib/cyrus/meta";
import { commandLabels, flightBlocks, flightLines, flightVersion, gateChecks, gateVerdict, planGateFlight, readStoredFlight, dueForFlight, backoffMs, MAX_FLIGHTS_PER_BUILD, type GateBuild, type StoredFlight } from "../lib/cyrus/testflight/gate";
import { flyOne, testFlightGateSweep, type GateDeps } from "../lib/cyrus/testflight/gate-worker";
import type { CheckResult, TestFlightReport, TestFlightSpec } from "../lib/cyrus/testflight/types";
import { summarize } from "../lib/cyrus/testflight/summary";
// eslint-disable-next-line @typescript-eslint/no-require-imports
const REL = require("../services/modbuilder/release.js");

const H = (s: string) => createHash("sha256").update(s).digest("hex");
const SVC: SvcRelease = {
  schema: 1, service: "nxeon-modbuilder", image: "0.5", promptVersion: "mb-2026-10-07.3", sections: { assets: "mb-assets-2026-10-10.3" }, knowledge: "sheets+rules-2026-10-07.4",
  sheets: [{ name: "paper-api-1.21.11.md", sha256: H("sheet") }], rules: { version: "rules-2026-10-07.4", sha256: H("rules") }, scanner: { sha256: H("scan"), profile: "strict" },
  registrySha256: H("reg"), jdk: { release: 21, version: "javac 21.0.8" }, classpathSha256: H("cp"), deps: [{ id: "z-dep", sha256: H("z") }, { id: "a-dep", sha256: H("a") }], toolchain: "javac --release 21 -proc:none; jar --date (sorted entries)",
};
const NOW = new Date("2026-10-10T12:00:00Z");

describe("engine release record", () => {
  it("records everything known, deterministic, engine id independent of the artifact", () => {
    const a = buildEngineRelease({ target: "1.21.11", artifact: { kind: "jar", name: "A-1.0.jar", sha256: H("jar-a") }, svc: SVC, portalRegistrySha256: H("reg"), now: NOW, record: { model: "saka" } });
    const b = buildEngineRelease({ target: "1.21.11", artifact: { kind: "jar", name: "B-1.0.jar", sha256: H("jar-b") }, svc: SVC, portalRegistrySha256: H("reg"), now: NOW });
    assert.deepEqual(a.unknown, []);
    assert.equal(a.id, b.id, "same engine, different artifacts -> same engine id");
    assert.deepEqual(a.sbom.map((d) => d.id), ["a-dep", "z-dep"]);
    assert.equal(a.registry?.match, true);
    assert.equal(a.scanner?.profile, "strict");
    assert.equal(a.artifact.sha256, H("jar-a"));
    assert.ok(verifyEngineRelease(a));
    assert.deepEqual(buildEngineRelease({ target: "1.21.11", artifact: { kind: "jar", sha256: H("jar-a") }, svc: SVC, portalRegistrySha256: H("reg"), now: NOW }).id, a.id);
    const c = buildEngineRelease({ target: "1.21.11", artifact: { kind: "jar", sha256: H("jar-a") }, svc: { ...SVC, scanner: { sha256: H("scan2"), profile: "strict" } }, now: NOW });
    assert.notEqual(c.id, a.id, "a different scanner is a different engine");
    assert.notEqual(buildEngineRelease({ target: "26.2", artifact: { kind: "jar", sha256: H("jar-a") }, svc: SVC, now: NOW }).id, a.id);
    assert.ok(!verifyEngineRelease({ ...a, scanner: { sha256: H("x") } }), "an edited record no longer verifies");
    assert.equal(buildEngineRelease({ target: "1.21.11", artifact: { kind: "jar", sha256: H("j") }, svc: SVC, portalRegistrySha256: H("other"), now: NOW }).registry?.match, false);
  });
  it("an older service (no release) is recorded honestly: fallbacks + unknown list", () => {
    const r = buildEngineRelease({ target: "1.21.11", artifact: { kind: "jar", sha256: H("j") }, svc: null, record: { promptVersion: "mb-old", knowledge: "nosheets+norules" }, health: { image: "0.4", release: { scannerSha256: H("scan") } }, now: NOW });
    assert.equal(r.prompts.base, "mb-old"); assert.equal(r.service?.image, "0.4"); assert.equal(r.scanner?.sha256, H("scan"));
    assert.ok(r.unknown.includes("service_release_record") && r.unknown.includes("jdk.version") && r.unknown.includes("classpathSha256"));
    assert.throws(() => buildEngineRelease({ target: "x", artifact: { kind: "jar", sha256: "nope" }, now: NOW }));
  });
  it("is accepted on the revision engine record and survives Cyrus meta round trips", () => {
    const r = buildEngineRelease({ target: "1.21.11", artifact: { kind: "jar", sha256: H("j") }, svc: SVC, now: NOW });
    assert.ok(validateEngineRecord({ promptVersion: "x", release: r }).ok);
    const bad = validateEngineRecord({ release: { schema: 1, id: "nope" } });
    assert.ok(!bad.ok && bad.errors.some((e) => e.code === "bad_release"));
    assert.equal(readEngineRelease({ junk: true }), null);
    assert.deepEqual(readEngineRelease(JSON.parse(JSON.stringify(r))), JSON.parse(JSON.stringify(r)));
    const meta = readCyrusMeta({ title: "T", engineRelease: r, testFlight: { schema: 1, state: "done", checks: [] }, bogus: 1 });
    assert.equal((meta.engineRelease as { id: string }).id, r.id); assert.ok(meta.testFlight); assert.ok(!("bogus" in meta));
    assert.equal(readCyrusMeta({ engineRelease: { big: "x".repeat(70_000) } }).engineRelease, undefined);
  });
  it("build service half: hashes real files, nulls what is missing, sorts deps", () => {
    const dir = mkdtempSync(path.join(tmpdir(), "cyrus-rel-"));
    try {
      writeFileSync(path.join(dir, "scan.js"), "scan"); mkdirSync(path.join(dir, "rules")); writeFileSync(path.join(dir, "rules", "failure-rules.json"), "rules");
      mkdirSync(path.join(dir, "sheets")); writeFileSync(path.join(dir, "sheets", "1.21.11.md"), "sheet");
      mkdirSync(path.join(dir, "cp")); writeFileSync(path.join(dir, "cp", "1.21.11.txt"), "cp");
      const r = REL.releaseFor({ mcVersion: "1.21.11", promptVersion: "p1", knowledge: "k", scanProfile: "attested" }, { dir, rulesVersion: "rv", cpDir: path.join(dir, "cp"), tc: { release: "21", javac: "/nonexistent/javac" }, deps: [{ id: "b", sha256: "x" }, { id: "a" }], sections: { assets: "s1", datapack: null } });
      assert.equal(r.scanner.sha256, H("scan")); assert.equal(r.scanner.profile, "attested"); assert.equal(r.rules.sha256, H("rules"));
      assert.deepEqual(r.sheets, [{ name: "paper-api-1.21.11.md", sha256: H("sheet") }]); assert.equal(r.classpathSha256, H("cp"));
      assert.equal(r.jdk.release, 21); assert.equal(r.jdk.version, null);
      assert.deepEqual(r.deps.map((d: { id: string }) => d.id), ["a", "b"]); assert.deepEqual(r.sections, { assets: "s1" });
      assert.equal(REL.releaseFor({ mcVersion: "9.9" }, { dir }).sheets.length, 0);
      // the portal accepts what the service produced
      const er = buildEngineRelease({ target: "1.21.11", artifact: { kind: "jar", sha256: H("j") }, svc: r, now: NOW });
      assert.equal(er.scanner?.sha256, H("scan")); assert.ok(er.unknown.includes("jdk.version"));
    } finally { rmSync(dir, { recursive: true, force: true }); }
  });
});

// ------------------------------------------------------------------------------------------------ Test Flight gate
const BUILD: GateBuild = { id: "b1", mcVersion: "1.21.11", pluginName: "NxAlpha", jarSha256: H("jar"), result: { commands: [{ usage: "/alpha give <player>" }, { usage: "/alphagem" }, { usage: "nonsense with spaces" }], safety: { verdict: "pass" } } };
const ART = { jarPath: "/tmp/x.jar", datapacks: [{ name: "nxeon-nx_a-dp", localPath: "/tmp/dp.zip" }] };
const chk = (id: CheckResult["id"], status: CheckResult["status"], evidence: string[] = status === "not_run" ? [] : ["ok"]): CheckResult => ({ id, status, required: true, evidence, durationMs: 1 });
function report(over: Partial<TestFlightReport> = {}, rcon: string[] = ["plugins 'plugins' [rss 1 MB, 1 ms]: ok -> NxAlpha", "cmd-alpha 'help alpha' [rss 1 MB, 1 ms]: ok (optional) -> /alpha", "cmd-alphagem 'help alphagem' [rss 1 MB, 1 ms]: ok (optional) -> /alphagem", "datapacks-enabled 'datapack list enabled' [rss 1 MB, 1 ms]: ok -> file/nxeon-nx_a-dp.zip"]): TestFlightReport {
  return {
    schema: 1, runId: "tf-1-21-11-x", status: "completed", version: "1.21.11", javaRelease: 21, startedAt: NOW.toISOString(), finishedAt: NOW.toISOString(),
    checks: [chk("boot_done", "pass", ["Done (16.6s)!"]), chk("plugins_enabled", "pass", ["NxAlpha: enabled"]), chk("startup_log_clean", "pass", ["0 hits"]), chk("rcon_checks", "pass", rcon), chk("clean_stop", "pass", ["exit 0"]), chk("no_leaks", "pass", ["gone"])],
    timings: {}, bootMs: 18000, doneReportedSec: 16.6, peakRssKb: 870000, artifacts: [], engine: { runner: "tf-lite-3", runnerSha256: "a".repeat(64), node: "v22", host: "node-2", kernel: "x", jdk: { release: 21, version: "21.0.12", dist: "temurin", sha256: "b".repeat(64) }, paper: { version: "1.21.11", build: 132, sha256: "c".repeat(64), channel: "STABLE" }, isolation: { netns: "x", uid: 65534, noNewPrivs: true, nice: 10, activeProcessorCount: 2 } },
    notes: [], overall: "passed", ...over,
  };
}
type Store = Map<string, StoredFlight>;
function deps(runs: (spec: TestFlightSpec) => TestFlightReport | Error, store: Store, env: Record<string, string> = { CYRUS_TESTFLIGHT_GATE: "1" }, builds: GateBuild[] = [BUILD]): GateDeps & { calls: number } {
  const d = {
    calls: 0, env, now: () => NOW,
    async candidates() { return builds.map((b) => ({ ...b, cyrus: store.has(b.id) ? { testFlight: store.get(b.id) } : null, finishedAt: NOW })); },
    async artifacts() { return ART; },
    async run(spec: TestFlightSpec) { d.calls++; const r = runs(spec); if (r instanceof Error) throw r; return { report: r, summary: summarize(spec, r), resolved: {} as never, stderr: "" }; },
    async store(id: string, f: StoredFlight) { store.set(id, JSON.parse(JSON.stringify(f))); },
  };
  return d;
}

describe("Test Flight gate", () => {
  it("only versions with a pinned Paper server can fly", () => {
    assert.ok(flightVersion("1.21.11").ok);
    const r = flightVersion("26.3"); assert.ok(!r.ok && /no test server/.test(r.reason));
    assert.ok(!flightVersion("9.9").ok);
  });
  it("plans the flight: jar, data packs, plugins + help checks, Pack Loader config when available; scan block = not run", () => {
    assert.deepEqual(commandLabels(BUILD.result), ["alpha", "alphagem"]);
    const p = planGateFlight(BUILD, { ...ART, packLoader: { localPath: "/tmp/pl.jar", sha256: H("pl"), config: "{}" } });
    assert.ok(p.ok);
    assert.deepEqual(p.spec.rcon!.map((c) => c.command), ["plugins", "help alpha", "help alphagem", "nxpacks status"]);
    assert.equal(p.spec.plugins!.length, 2); assert.equal(p.spec.files![0].path, "plugins/NxeonPackLoader/packs.json");
    assert.equal(p.spec.datapacks!.length, 1);
    const blocked = planGateFlight({ ...BUILD, result: { safety: { verdict: "block" } } }, ART); assert.ok(!blocked.ok);
    const nov = planGateFlight({ ...BUILD, mcVersion: "26.3" }, ART); assert.ok(!nov.ok && /no test server/.test(nov.reason));
  });
  it("a passing flight: six honest statuses, 'boot-tested' label, page lines", async () => {
    const st: Store = new Map();
    assert.equal(await flyOne(BUILD, null, deps(() => report(), st), () => NOW), "ran");
    const f = st.get("b1")!;
    assert.equal(f.state, "done"); assert.equal(f.verdict, "passed"); assert.equal(f.label, "boot-tested on Paper 1.21.11");
    assert.deepEqual(f.checks.map((c) => `${c.id}:${c.status}`), ["compile:pass", "scan:pass", "boot:pass", "plugins_enabled:pass", "commands_registered:pass", "datapack_loaded:pass"]);
    assert.equal(f.engine?.paperBuild, 132);
    const lines = flightLines(f); assert.match(lines[0], /^Boot-tested on Paper 1\.21\.11 .*does not test gameplay/);
    assert.ok(!flightBlocks(f, { CYRUS_TESTFLIGHT_BLOCK_ON_FAIL: "1" }).blocked);
  });
