// REAL delivery runs on node-2 (not part of the unit suite). The DELIVERY ORCHESTRATOR drives a disposable server dir
// under /tank/nxeon-build/tmp/cyrus-r12/ through a host whose "restart" boots the dir's CURRENT contents on a real Paper
// server with Test Flight (every plugin jar, every world data pack, the Pack Loader config), and whose health probe
// reads that flight's report. So every restart and every health verdict below is a real Paper boot.
//   scripts/devhost run -- npx tsx test/cyrus-delivery-real.ts --local [--version 1.21.11] [--out file.json]
// Scenarios (one flight at a time, busy retried with backoff):
//   A  fresh delivery: mod jar (TfItemModel fixture) + resource pack entry (Pack Loader, packs.json) + a real data pack
//      (the data pack studio showcase) -> restart -> healthy.
//   B  update that adds a deliberately BROKEN world generation pack -> the server does not come up -> rollback restores
//      the exact previous bytes -> restart -> the server comes up healthy on the previous state.
//   C  update with a VALID world generation pack (the worldgen showcase) -> restart -> came up, dimension pack loaded.
//   D  uninstall -> restart -> healthy, jar + packs gone, Pack Loader released.
import { spawn } from "node:child_process";
import { createHash } from "node:crypto";
import { mkdirSync, readFileSync, readdirSync, rmSync, statSync, writeFileSync } from "node:fs";
import path from "node:path";
import { runTestFlight, type Remote, type RunResult } from "../lib/cyrus/testflight/client";
import type { TestFlightSpec } from "../lib/cyrus/testflight/types";
import { LocalGuestFs } from "../lib/mods/guest-fs";
import { inspectJar } from "../lib/cyrus/inventory/jar";
import { buildDataPack } from "../lib/cyrus/datapack/emit";
import { zip } from "../lib/cyrus/textures/zip";
import { deliverMod, uninstallMod } from "../lib/cyrus/delivery/orchestrator";
import type { DeliveryHost, DeliveryResult, HealthReport, ModRelease, ServerSession, TxnFs } from "../lib/cyrus/delivery/types";
import { brokenWorldgenFiles } from "./cyrus-worldgen-real";

const TF_ROOT = "/tank/nxeon-build/tmp/testflight";
const WORK = "/tank/nxeon-build/tmp/cyrus-r12";
const FX = `${TF_ROOT}/inbox/fx`;
const NS = "nx_deliv0r1";
const BASE = "/opt/mc";
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
const h = (b: Buffer) => createHash("sha256").update(b).digest("hex");
const arg = (k: string, d: string) => { const i = process.argv.indexOf(k); return i > 0 ? process.argv[i + 1] : d; };
const VERSION = arg("--version", "1.21.11");
const localRemote: Remote = {
  exec: (command, opts = {}) => new Promise((resolve) => {
    const child = spawn("bash", ["-c", command], { stdio: ["pipe", "pipe", "pipe"] });
    let stdout = "", stderr = "";
    child.stdout.on("data", (d) => (stdout += d)); child.stderr.on("data", (d) => (stderr += d));
    const t = setTimeout(() => child.kill("SIGKILL"), opts.timeoutMs ?? 120000);
    child.on("close", (code) => { clearTimeout(t); resolve({ code, stdout, stderr }); });
    child.stdin.on("error", () => {}); child.stdin.end(opts.input ?? undefined);
  }),
};
const REMOTE = process.argv.includes("--local") ? localRemote : undefined;

async function fly(spec: TestFlightSpec, label: string): Promise<RunResult> {
  for (let attempt = 1, wait = 15000; attempt <= 12; attempt++, wait = Math.min(wait * 2, 120000)) {
    const r = await runTestFlight(spec, { remote: REMOTE });
    if (r.report.status !== "busy") return r;
    console.log(`${label}: node-2 busy, retry ${attempt} in ${wait / 1000}s`);
    await sleep(wait);
  }
  throw new Error(`${label}: node-2 stayed busy`);
}

function treeHash(dir: string, skip = "root/.nxeon-cyrus/delivery-journal"): string {
  const out: string[] = [];
  const walk = (d: string) => { for (const n of readdirSync(d).sort()) { const p = path.join(d, n), rel = path.relative(dir, p); if (rel.startsWith(skip)) continue; if (statSync(p).isDirectory()) { out.push(`D ${rel}`); walk(p); } else out.push(`F ${rel} ${h(readFileSync(p))}`); } };
  walk(dir);
  return h(Buffer.from(out.join("\n")));
}

/** A host whose server is a directory, booted for real by Test Flight on every restart. */
function flightHost(root: string, flights: unknown[]): DeliveryHost & { refs: Map<string, string[]> } {
  const fs = new LocalGuestFs(root);
  const refs = new Map<string, string[]>();
  let last: RunResult | null = null;
  const local = (p: string) => path.join(root, p);
  const session: ServerSession = {
    fs, base: BASE, levelName: "world", mcVersion: VERSION,
    async restart() {
      const plugins = readdirSync(local(`${BASE}/plugins`)).filter((n) => n.endsWith(".jar")).sort().map((n) => ({ localPath: local(`${BASE}/plugins/${n}`) }));
      const dpDir = local(`${BASE}/world/datapacks`);
      const datapacks = (() => { try { return readdirSync(dpDir).filter((n) => n.endsWith(".zip")).sort().map((n) => ({ name: n.replace(/\.zip$/, "").toLowerCase().replace(/[^a-z0-9_.-]/g, "-").slice(0, 64), localPath: path.join(dpDir, n) })); } catch { return []; } })();
      const files: TestFlightSpec["files"] = [];
      try { files.push({ path: "plugins/NxeonPackLoader/packs.json", content: readFileSync(local(`${BASE}/plugins/NxeonPackLoader/packs.json`), "utf8") }); } catch { /* none */ }
      const names = plugins.map((p) => inspectJar(path.basename(p.localPath), `plugins/${path.basename(p.localPath)}`, readFileSync(p.localPath), { bytecode: false }).descriptor?.name).filter((n): n is string => !!n);
      const spec: TestFlightSpec = {
        version: VERSION, plugins, datapacks, ...(files.length ? { files } : {}),
        rcon: [{ id: "answers", command: "list", required: false }, ...(names.includes("NxeonPackLoader") ? [{ id: "packs", command: "nxpacks status", required: false }] : [])],
        timeouts: { bootSec: 200, totalSec: 480 },
      };
      try {
        const t0 = Date.now();
        last = await fly(spec, "restart");
        flights.push({ at: new Date().toISOString(), plugins: names, datapacks: datapacks.map((d) => d.name), packConfig: files.length > 0, overall: last.summary.overall, checks: last.report.checks.map((c) => ({ id: c.id, status: c.status, evidence: c.evidence.slice(0, 6) })), bootMs: last.report.bootMs, peakRssKb: last.report.peakRssKb, wallMs: Date.now() - t0, runId: last.report.runId, paper: last.report.engine?.paper ?? null, jdk: last.report.engine?.jdk?.version ?? null });
        console.log(`  flight: ${last.summary.overall} (${last.report.checks.map((c) => `${c.id}=${c.status}`).join(" ")})`);
        return { ok: true };
      } catch (e) { last = null; return { ok: false, error: (e as Error).message }; }
    },
    async health(): Promise<HealthReport> {
      const r = last?.report;
      if (!r) return { real: true, cameUp: false, answered: false, pluginsEnabled: [], errorLines: [], datapacksLoaded: [], evidence: ["no flight"] };
      const c = (id: string) => r.checks.find((x) => x.id === id);
      const boot = c("boot_done"), pe = c("plugins_enabled"), log = c("startup_log_clean"), rc = c("rcon_checks");
      const enabled = (pe?.evidence ?? []).map((l) => /^(\S+): enabled/.exec(l)?.[1]).filter((n): n is string => !!n);
      const dl = (rc?.evidence ?? []).find((l) => l.startsWith("datapacks-enabled ")) ?? "";
      return {
        real: true, cameUp: boot?.status === "pass", answered: (rc?.evidence ?? []).some((l) => l.startsWith("answers ") && /: ok/.test(l)) || c("clean_stop")?.status === "pass",
        pluginsEnabled: enabled, errorLines: log?.status === "fail" ? log.evidence.filter((l) => /ERROR|Exception|Caused by|Failed/.test(l)).slice(0, 10) : [],
        datapacksLoaded: [...dl.matchAll(/file\/([A-Za-z0-9_.-]+?)(?:\.zip)?(?=[\s,\]|"]|$)/g)].map((m) => `file/${m[1]}.zip`),
        evidence: [...(boot?.evidence ?? []).slice(0, 2), dl.slice(0, 200)],
      };
    },
  };
  const writeJar = async (f: TxnFs, target: string, data: Buffer) => { await f.writeFile(`${target}.nxeon-part`, data); await f.rename(`${target}.nxeon-part`, target); };
  const loader = readFileSync(`${FX}/NxeonPackLoader-0.1.0.jar`);
  return {
    refs,
    env: { CYRUS_DELIVERY: "1", CYRUS_MANAGED_PLUGINS_REAL: "1", CYRUS_DATAPACK_DELIVERY_REAL: "1", CYRUS_DATAPACK_STUDIO: "1", CYRUS_WORLDGEN: "1" },
    async open() { return session; },
    managed: {
      async ensure({ key, dependent, fs: f }) {
        if (key !== "nxeon-pack-loader") return { ok: false, error: `${key} is not available in this run` };
        const d = refs.get(key) ?? [];
        const installed = d.length > 0;
        if (!installed) await writeJar(f, `${BASE}/plugins/NxeonPackLoader-0.1.0.jar`, loader);
        refs.set(key, [...new Set([...d, dependent])].sort());
        return { ok: true, action: installed ? (d.includes(dependent) ? "already" : "ref_added") : "installed", pluginName: "NxeonPackLoader" };
      },
      async release({ key, dependent, fs: f }) {
        const d = (refs.get(key) ?? []).filter((x) => x !== dependent);
        refs.set(key, d);
        if (!d.length) { await f.remove(`${BASE}/plugins/NxeonPackLoader-0.1.0.jar`); return { ok: true, action: "removed" }; }
        return { ok: true, action: "ref_dropped" };
      },
      async snapshot() { return JSON.stringify([...refs.entries()]); },
      async restore(_s, snap) { refs.clear(); for (const [k, v] of JSON.parse(String(snap))) refs.set(k, v); return { ok: true }; },
    },
    jar: {
      async install({ fs: f, base, release, previous }) {
        const target = `${base}/plugins/${release.plugin!.jarName}`;
        if (previous?.jar && previous.jar.target !== target && (await f.stat(previous.jar.target))) await f.remove(previous.jar.target);
        await writeJar(f, target, release.plugin!.bytes);
        return { ok: true, target };
      },
      async remove({ fs: f, record }) { if (record.jar && (await f.stat(record.jar.target))) await f.remove(record.jar.target); return { ok: true }; },
    },
    packs: { async publish(_z, sha1) { return { url: `https://packs.example.invalid/p/${sha1}.zip` }; } },
  };
}

function seed(root: string) {
  const w = (rel: string, data: string | Buffer) => { const p = path.join(root, rel); mkdirSync(path.dirname(p), { recursive: true }); writeFileSync(p, data); };
  w(`${BASE.slice(1)}/server.properties`, "level-name=world\n");
  w(`${BASE.slice(1)}/version_history.json`, JSON.stringify({ currentVersion: `${VERSION} (MC: ${VERSION})` }));
  mkdirSync(path.join(root, BASE.slice(1), "plugins"), { recursive: true });
  mkdirSync(path.join(root, BASE.slice(1), "world/datapacks"), { recursive: true });
}

const brief = (r: DeliveryResult) => ({
  outcome: r.outcome, ok: r.ok, failedStep: r.failedStep ?? null, error: r.error ?? null, apply: r.apply ?? null,
  health: r.health ? { ok: r.health.ok, problems: r.health.problems } : null,
  rollback: r.rollback ? { ok: r.rollback.ok, restored: r.rollback.restored, removed: r.rollback.removed, mismatches: r.rollback.mismatches, refs: r.rollback.refs, restarted: r.rollback.restarted, health: r.rollback.health ? { ok: r.rollback.health.ok, problems: r.rollback.health.problems } : null } : null,
  steps: r.steps.map((s) => `${s.step}:${s.status}${s.detail ? ` (${s.detail.slice(0, 160)})` : ""}`), notes: r.notes, conflicts: r.conflicts ? { blocking: r.conflicts.blocking.length, warnings: r.conflicts.warnings.map((w) => w.class) } : null,
  keptWorldFolders: r.keptWorldFolders ?? [],
});

async function main() {
  const out: Record<string, unknown> = { what: "Cyrus R5 delivery orchestrator, real Paper boots via Test Flight on node-2", date: new Date().toISOString(), version: VERSION, scenarios: {} as Record<string, unknown> };
  const save = () => { const f = arg("--out", ""); if (f) writeFileSync(f, JSON.stringify(out, null, 1)); };
  const root = path.join(WORK, `srv-${Date.now().toString(36)}`);
  mkdirSync(root, { recursive: true });
  seed(root);
  const flights: unknown[] = [];
  const host = flightHost(root, flights);
  const jar = readFileSync(`${FX}/TfItemModel-1.0.0.jar`);
  const pluginName = inspectJar("TfItemModel-1.0.0.jar", "plugins/TfItemModel-1.0.0.jar", jar, { bytecode: false }).descriptor!.name;
  const dpSpec = JSON.parse(readFileSync(path.join(__dirname, "fixtures/cyrus-datapack/showcase.json"), "utf8"));
  const dp = buildDataPack(dpSpec, { version: VERSION, namespace: NS });
  if (!dp.ok) throw new Error(`showcase data pack: ${dp.errors.join("; ")}`);
  const wgSpec = JSON.parse(readFileSync(path.join(__dirname, "fixtures/cyrus-worldgen/showcase.json"), "utf8"));
  const wg = buildDataPack(wgSpec, { version: VERSION, namespace: NS, worldgen: true });
  if (!wg.ok) throw new Error(`worldgen showcase: ${wg.errors.join("; ")}`);
  const broken = zip(brokenWorldgenFiles(VERSION).map((f) => ({ path: f.path, data: Buffer.from(f.text) })));
  const fakePack = zip([{ path: "pack.mcmeta", data: Buffer.from('{"pack":{"pack_format":75,"description":"r12"}}') }]);
  const rel = (over: Partial<ModRelease>): ModRelease => ({
    projectId: "cp_r12real01", revisionId: "rev_1", namespace: NS, mcVersion: VERSION, label: pluginName,
    plugin: { pluginName, jarName: "TfItemModel-1.0.0.jar", sha256: h(jar), bytes: jar },
    pack: { sha1: createHash("sha1").update(fakePack).digest("hex"), zip: fakePack, prompt: "R12 real run pack.", required: false },
    datapacks: [{ name: dp.pack.name, zip: dp.pack.zip, sha256: dp.pack.sha256, apply: dp.pack.apply }], creatures: [], ...over,
  });
  const S = out.scenarios as Record<string, unknown>;
  try {
    console.log(`A: fresh delivery on ${VERSION}`);
    const t0 = treeHash(root);
    const a = await deliverMod("real-srv", rel({}), host);
    const tA = treeHash(root);
    S.A = { ...brief(a), treeBefore: t0, treeAfter: tA, refs: [...host.refs.entries()], files: readdirSync(path.join(root, "opt/mc/plugins")).sort().concat(readdirSync(path.join(root, "opt/mc/world/datapacks")).sort()) };
    console.log(`A: ${a.outcome}`); save();
    if (!a.ok) throw new Error("A failed; stopping");

    console.log("B: update with a BROKEN world generation pack");
    const b = await deliverMod("real-srv", rel({ revisionId: "rev_2_broken", datapacks: [{ name: dp.pack.name, zip: dp.pack.zip, sha256: dp.pack.sha256, apply: dp.pack.apply }, { name: "brokenwg", zip: broken, sha256: h(broken), apply: "restart", worldgen: { dimensions: ["nx_broken02:nowhere"] } }] }), host);
    const tB = treeHash(root);
    S.B = { ...brief(b), treeBeforeUpdate: tA, treeAfterRollback: tB, exactRestore: tA === tB, journalLeft: (() => { try { return readdirSync(path.join(root, "root/.nxeon-cyrus/delivery-journal")); } catch { return []; } })() };
    console.log(`B: ${b.outcome}; exact restore: ${tA === tB}`); save();

    console.log("C: update with a VALID world generation pack");
    const c = await deliverMod("real-srv", rel({ revisionId: "rev_3_worldgen", datapacks: [{ name: dp.pack.name, zip: dp.pack.zip, sha256: dp.pack.sha256, apply: dp.pack.apply }, { name: wg.pack.name, zip: wg.pack.zip, sha256: wg.pack.sha256, apply: wg.pack.apply, ...(wg.pack.worldgen ? { worldgen: { dimensions: wg.pack.worldgen.dimensions } } : {}) }] }), host);
    S.C = { ...brief(c), dimensions: wg.pack.worldgen?.dimensions ?? [] };
    console.log(`C: ${c.outcome}`); save();

    console.log("D: uninstall");
    const d = await uninstallMod("real-srv", "cp_r12real01", host);
    S.D = { ...brief(d), refs: [...host.refs.entries()], pluginsLeft: readdirSync(path.join(root, "opt/mc/plugins")).sort(), datapacksLeft: readdirSync(path.join(root, "opt/mc/world/datapacks")).sort() };
    console.log(`D: ${d.outcome}`); save();
  } finally {
    out.flights = flights;
    save();
    rmSync(root, { recursive: true, force: true });
  }
  if (!process.argv.includes("--out")) console.log(JSON.stringify(out, null, 1));
}
main().catch((e) => { console.error(e); process.exit(1); });

