        if (key !== "nxeon-pack-loader") return { ok: false, error: `${key} is not available in this run` };
        const d = refs.get(key) ?? [];
        const installed = d.length > 0;
        if (!installed) await writeJar(f, `${BASE}/plugins/NxeonPackLoader-0.1.0.jar`, loader);
        refs.set(key, [...new Set([...d, dependent])].sort());
        return { ok: true, action: installed ? (d.includes(dependent) ? "already" : "ref_added") : "installed", pluginName: "NxeonPackLoader" };
      },
      async release({ key, dependent, fs: f }) {
        const d = (refs.get(key) ?? []).filter((x) => x !== dependent);
        refs.set(key, d);
        if (!d.length) { await f.remove(`${BASE}/plugins/NxeonPackLoader-0.1.0.jar`); return { ok: true, action: "removed" }; }
        return { ok: true, action: "ref_dropped" };
      },
      async snapshot() { return JSON.stringify([...refs.entries()]); },
      async restore(_s, snap) { refs.clear(); for (const [k, v] of JSON.parse(String(snap))) refs.set(k, v); return { ok: true }; },
    },
    jar: {
      async install({ fs: f, base, release, previous }) {
        const target = `${base}/plugins/${release.plugin!.jarName}`;
        if (previous?.jar && previous.jar.target !== target && (await f.stat(previous.jar.target))) await f.remove(previous.jar.target);
        await writeJar(f, target, release.plugin!.bytes);
        return { ok: true, target };
      },
      async remove({ fs: f, record }) { if (record.jar && (await f.stat(record.jar.target))) await f.remove(record.jar.target); return { ok: true }; },
    },
    packs: { async publish(_z, sha1) { return { url: `https://packs.example.invalid/p/${sha1}.zip` }; } },
  };
}

function seed(root: string) {
  const w = (rel: string, data: string | Buffer) => { const p = path.join(root, rel); mkdirSync(path.dirname(p), { recursive: true }); writeFileSync(p, data); };
  w(`${BASE.slice(1)}/server.properties`, "level-name=world\n");
  w(`${BASE.slice(1)}/version_history.json`, JSON.stringify({ currentVersion: `${VERSION} (MC: ${VERSION})` }));
  mkdirSync(path.join(root, BASE.slice(1), "plugins"), { recursive: true });
  mkdirSync(path.join(root, BASE.slice(1), "world/datapacks"), { recursive: true });
}

const brief = (r: DeliveryResult) => ({
