async function main() {
  const out: Record<string, unknown> = { what: "Cyrus R5 delivery orchestrator, real Paper boots via Test Flight on node-2", date: new Date().toISOString(), version: VERSION, scenarios: {} as Record<string, unknown> };
  const save = () => { const f = arg("--out", ""); if (f) writeFileSync(f, JSON.stringify(out, null, 1)); };
