  const wgSpec = JSON.parse(readFileSync(path.join(__dirname, "fixtures/cyrus-worldgen/showcase.json"), "utf8"));
  const wg = buildDataPack(wgSpec, { version: VERSION, namespace: NS, worldgen: true });
