    plugin: { pluginName, jarName: "TfItemModel-1.0.0.jar", sha256: h(jar), bytes: jar },
    pack: { sha1: createHash("sha1").update(fakePack).digest("hex"), zip: fakePack, prompt: "R12 real run pack.", required: false },
    datapacks: [{ name: dp.pack.name, zip: dp.pack.zip, sha256: dp.pack.sha256, apply: dp.pack.apply }], creatures: [], ...over,
  });
  const S = out.scenarios as Record<string, unknown>;
  try {
    console.log(`A: fresh delivery on ${VERSION}`);
    const t0 = treeHash(root);
    const a = await deliverMod("real-srv", rel({}), host);
    const tA = treeHash(root);
