    console.log(`A: ${a.outcome}`); save();
    if (!a.ok) throw new Error("A failed; stopping");

    console.log("B: update with a BROKEN world generation pack");
    const b = await deliverMod("real-srv", rel({ revisionId: "rev_2_broken", datapacks: [{ name: dp.pack.name, zip: dp.pack.zip, sha256: dp.pack.sha256, apply: dp.pack.apply }, { name: "brokenwg", zip: broken, sha256: h(broken), apply: "restart", worldgen: { dimensions: ["nx_broken02:nowhere"] } }] }), host);
    const tB = treeHash(root);
