    console.log(`B: ${b.outcome}; exact restore: ${tA === tB}`); save();

    console.log("C: update with a VALID world generation pack");
    const c = await deliverMod("real-srv", rel({ revisionId: "rev_3_worldgen", datapacks: [{ name: dp.pack.name, zip: dp.pack.zip, sha256: dp.pack.sha256, apply: dp.pack.apply }, { name: wg.pack.name, zip: wg.pack.zip, sha256: wg.pack.sha256, apply: wg.pack.apply, ...(wg.pack.worldgen ? { worldgen: { dimensions: wg.pack.worldgen.dimensions } } : {}) }] }), host);
    S.C = { ...brief(c), dimensions: wg.pack.worldgen?.dimensions ?? [] };
    console.log(`C: ${c.outcome}`); save();

    console.log("D: uninstall");
    const d = await uninstallMod("real-srv", "cp_r12real01", host);
    S.D = { ...brief(d), refs: [...host.refs.entries()], pluginsLeft: readdirSync(path.join(root, "opt/mc/plugins")).sort(), datapacksLeft: readdirSync(path.join(root, "opt/mc/world/datapacks")).sort() };
    console.log(`D: ${d.outcome}`); save();
  } finally {
    out.flights = flights;
    save();
    rmSync(root, { recursive: true, force: true });
  }
  if (!process.argv.includes("--out")) console.log(JSON.stringify(out, null, 1));
}
main().catch((e) => { console.error(e); process.exit(1); });

