// REAL Test Flight gate runs on node-2 (not part of the unit suite): the gate's own flyOne() with the real invoker.
//   scripts/devhost run -- npx tsx test/cyrus-gate-real.ts --local [--out file.json]
//   1. TfHello (1.21.11 fixture, command /tfhello) -> passed, "boot-tested on Paper 1.21.11", commands registered
//   2. TfBroken (26.2 fixture, throws in onEnable) -> failed (plugins enabled FAILED), blocks with the flag
//   3. a 26.3 build -> not run: no test server for 26.3 (no flight)
import { spawn } from "node:child_process";
import { createHash } from "node:crypto";
import { readFileSync, writeFileSync } from "node:fs";
import { runTestFlight, type Remote } from "../lib/cyrus/testflight/client";
import { flyOne, type GateDeps } from "../lib/cyrus/testflight/gate-worker";
import { flightBlocks, flightLines, type GateBuild, type StoredFlight } from "../lib/cyrus/testflight/gate";

const FX = "/tank/nxeon-build/tmp/testflight/inbox/fx";
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
const localRemote: Remote = {
  exec: (command, opts = {}) => new Promise((resolve) => {
    const child = spawn("bash", ["-c", command], { stdio: ["pipe", "pipe", "pipe"] });
    let stdout = "", stderr = "";
    child.stdout.on("data", (d) => (stdout += d)); child.stderr.on("data", (d) => (stderr += d));
    const t = setTimeout(() => child.kill("SIGKILL"), opts.timeoutMs ?? 120000);
    child.on("close", (code) => { clearTimeout(t); resolve({ code, stdout, stderr }); });
    child.stdin.on("error", () => {}); child.stdin.end(opts.input ?? undefined);
  }),
};
const REMOTE = process.argv.includes("--local") ? localRemote : undefined;

async function main() {
  const store = new Map<string, StoredFlight>();
  const deps = (jar: string): GateDeps => ({
    env: { CYRUS_TESTFLIGHT_GATE: "1" },
    async candidates() { return []; },
    async artifacts() { return { jarPath: jar, datapacks: [], packLoader: null }; },
    async run(spec) {
      for (let i = 0, wait = 15000; i < 12; i++, wait = Math.min(wait * 2, 120000)) {
