        if (r.report.status !== "busy") return r;
        console.log(`busy, retry in ${wait / 1000}s`); await sleep(wait);
      }
      throw new Error("node-2 stayed busy");
    },
    async store(id, f) { store.set(id, JSON.parse(JSON.stringify(f))); },
  });
