    const f = store.get(c.b.id)!;
    const row = { build: c.b.id, version: c.b.mcVersion, result: r, wallMs: Date.now() - t0, state: f.state, verdict: f.verdict, label: f.label, checks: f.checks, reason: f.reason ?? null, bootMs: f.bootMs ?? null, peakRssKb: f.peakRssKb ?? null, engine: f.engine ?? null, lines: flightLines(f), blocksWithFlag: flightBlocks(f, { CYRUS_TESTFLIGHT_BLOCK_ON_FAIL: "1" }).blocked, blocksWithoutFlag: flightBlocks(f, {}).blocked };
