// Cyrus R5: the sound RENDER RELAY. The web process never connects to node-2: it sends render / preview jobs to a
// small loopback HTTP relay inside the WORKER, and the worker holds the ssh transport to the render host
// (./host.ts sshRenderHost). No audio is ever rendered on the primary; the relay only forwards JSON.
//   worker:  CYRUS_SOUND_RENDER=ssh + CYRUS_SOUND_RELAY_PORT=<port> + CYRUS_SOUND_RELAY_TOKEN=<secret>  -> startRenderRelay
//   web:     CYRUS_SOUND_RENDER=relay + CYRUS_SOUND_RELAY_URL=http://127.0.0.1:<port> + the same token   -> relayRenderHost
// Endpoints (bearer token, loopback only): POST /render, POST /preview, GET /health (probe of the render host).
// One job at a time (node-2 serialises renders with flock anyway). Body cap 4 MB in, 16 MB (job output cap) out.
import http from "node:http";
import { timingSafeEqual } from "node:crypto";
import { NODE2, shq, sshRemote, type Remote } from "../testflight/client";
import { MAX_JOB_OUTPUT_BYTES, type PreviewJob, type PreviewResult, type RenderJob, type RenderResult } from "./job";
import { SOUND_FFMPEG_DIR, SOUND_LIBRARY_DIR, SOUND_RENDER_ROOT, type RenderHost } from "./host";

export const MAX_RELAY_BODY = 4 * 1024 * 1024;
export const RELAY_TOKEN_MIN = 24;
export type RenderHealth = { ok: boolean; host: string; checks: { id: "reachable" | "ffmpeg" | "library" | "workdir"; ok: boolean; detail: string }[]; ms: number };

const tokenOk = (got: string | undefined, want: string) => {
  if (!got || !got.startsWith("Bearer ")) return false;
  const a = Buffer.from(got.slice(7)), b = Buffer.from(want);
  return a.length === b.length && timingSafeEqual(a, b);
};

/** Probe the ssh render host: reachable, ffmpeg runs, library present, work dir writable. Never renders audio. */
export async function probeSshRenderHost(o: { remote?: Remote; host?: string; root?: string; libraryDir?: string; ffmpegDir?: string } = {}): Promise<RenderHealth> {
  const t0 = Date.now();
  const remote = o.remote ?? sshRemote(o.host ?? NODE2);
  const root = o.root ?? SOUND_RENDER_ROOT, lib = o.libraryDir ?? SOUND_LIBRARY_DIR, ff = o.ffmpegDir ?? SOUND_FFMPEG_DIR;
  const cmd = [
    "echo NX:UP",
    `${shq(`${ff}/ffmpeg`)} -hide_banner -version 2>/dev/null | head -1 | sed 's/^/NX:FF:/'`,
    `echo "NX:LIB:$(find ${shq(lib)} -maxdepth 2 -type f 2>/dev/null | wc -l)"`,
    `mkdir -p ${shq(root)} && test -w ${shq(root)} && echo NX:WD:ok || echo NX:WD:no`,
  ].join("; ");
  const r = await remote.exec(cmd, { timeoutMs: 30000 }).catch((e) => ({ code: null, stdout: "", stderr: String(e) }));
  const line = (k: string) => r.stdout.split("\n").find((l) => l.startsWith(`NX:${k}:`))?.slice(k.length + 4) ?? null;
  const up = /NX:UP/.test(r.stdout);
  const ffv = line("FF"), libN = Number(line("LIB") ?? 0), wd = line("WD");
  const checks: RenderHealth["checks"] = [
    { id: "reachable", ok: up, detail: up ? "ssh ok" : `unreachable: ${r.stderr.slice(-160)}` },
    { id: "ffmpeg", ok: !!ffv && /ffmpeg version/.test(ffv), detail: ffv ?? "ffmpeg missing" },
    { id: "library", ok: libN > 0, detail: `${libN} files` },
    { id: "workdir", ok: wd === "ok", detail: wd === "ok" ? root : `${root} not writable` },
  ];
  return { ok: checks.every((c) => c.ok), host: `ssh:${o.host ?? NODE2}`, checks, ms: Date.now() - t0 };
}

/** Worker side: serve the relay on 127.0.0.1 only. */
export function startRenderRelay(o: { host: RenderHost; port: number; token: string; probe?: () => Promise<RenderHealth> }): http.Server {
  if (o.token.length < RELAY_TOKEN_MIN) throw new Error(`CYRUS_SOUND_RELAY_TOKEN must be at least ${RELAY_TOKEN_MIN} characters`);
  if (!Number.isInteger(o.port) || o.port < 1024 || o.port > 65535) throw new Error("bad relay port");
  let chain: Promise<unknown> = Promise.resolve();
  const serial = <T>(fn: () => Promise<T>): Promise<T> => { const p = chain.then(fn, fn); chain = p.catch(() => {}); return p; };
  const send = (res: http.ServerResponse, code: number, body: unknown) => { const b = Buffer.from(JSON.stringify(body)); res.writeHead(code, { "Content-Type": "application/json", "Content-Length": b.length, "Cache-Control": "no-store" }); res.end(b); };
  const server = http.createServer((req, res) => {
    if (!tokenOk(req.headers.authorization, o.token)) return send(res, 401, { ok: false, error: "unauthorized" });
    if (req.method === "GET" && req.url === "/health") { void (o.probe ? o.probe() : Promise.resolve({ ok: true, host: o.host.id, checks: [], ms: 0 })).then((h) => send(res, 200, h), (e) => send(res, 500, { ok: false, error: String(e) })); return; }
    if (req.method !== "POST" || (req.url !== "/render" && req.url !== "/preview")) return send(res, 404, { ok: false, error: "not found" });
    const chunks: Buffer[] = []; let n = 0;
    req.on("data", (c: Buffer) => { n += c.length; if (n > MAX_RELAY_BODY) { req.destroy(); } else chunks.push(c); });
    req.on("end", () => {
      let job: unknown;
      try { job = JSON.parse(Buffer.concat(chunks).toString("utf8")); } catch { return send(res, 400, { ok: false, code: "bad_job", error: "bad json" }); }
      const run = req.url === "/render" ? () => o.host.render(job as RenderJob) : () => (o.host.preview ? o.host.preview(job as PreviewJob) : Promise.resolve({ ok: false, code: "off", error: "this render host cannot preview" } as PreviewResult));
      serial(run).then((r) => send(res, 200, r), (e) => send(res, 200, { ok: false, code: "transport", error: (e as Error).message }));
    });
  });
  server.listen(o.port, "127.0.0.1");
  return server;
}

/** Web side: a RenderHost that forwards to the worker's relay (loopback only). */
export function relayRenderHost(url: string, token: string, fetchImpl: typeof fetch = fetch): RenderHost {
  const u = new URL(url);
  if (u.protocol !== "http:" || !["127.0.0.1", "localhost", "[::1]"].includes(u.hostname)) throw new Error("the sound relay must be a loopback http URL (it runs in the worker on the same host)");
  if (token.length < RELAY_TOKEN_MIN) throw new Error(`CYRUS_SOUND_RELAY_TOKEN must be at least ${RELAY_TOKEN_MIN} characters`);
  const base = u.origin;
  const post = async <T>(path: string, job: unknown, timeoutMs: number): Promise<T> => {
    const ctl = new AbortController(); const t = setTimeout(() => ctl.abort(), timeoutMs);
    try {
      const r = await fetchImpl(`${base}${path}`, { method: "POST", headers: { Authorization: `Bearer ${token}`, "Content-Type": "application/json" }, body: JSON.stringify(job), signal: ctl.signal });
      const text = await r.text();
      if (text.length > MAX_JOB_OUTPUT_BYTES * 1.4) return { ok: false, code: "transport", error: "render output too large" } as T;
      return JSON.parse(text) as T;
    } catch (e) { return { ok: false, code: "transport", error: `the sound relay is not reachable: ${(e as Error).message}` } as T; }
    finally { clearTimeout(t); }
  };
  return {
    id: `relay:${base}`,
    render: (job) => post<RenderResult>("/render", job, 420_000),
    preview: (job) => post<PreviewResult>("/preview", job, 140_000),
  };
}

/** Web side health probe of the relay (+ the render host behind it). */
export async function relayHealth(url: string, token: string, fetchImpl: typeof fetch = fetch): Promise<RenderHealth> {
  const t0 = Date.now();
  try {
    const r = await fetchImpl(`${new URL(url).origin}/health`, { headers: { Authorization: `Bearer ${token}` }, signal: AbortSignal.timeout(40_000) });
    return (await r.json()) as RenderHealth;
  } catch (e) { return { ok: false, host: `relay:${url}`, checks: [{ id: "reachable", ok: false, detail: (e as Error).message }], ms: Date.now() - t0 }; }
}

