const TOKEN = "t".repeat(32);
const JOB: RenderJob = { v: 1, library: [], sets: [], vorbisQuality: 4 };
function fakeHost(calls: string[]): RenderHost {
  return {
    id: "fake",
    async render(job) { calls.push(`render:${job.sets.length}`); await new Promise((r) => setTimeout(r, 30)); return { ok: true, tool: { runner: "fake", render: "r", quality: "q", ffmpeg: "none" }, sets: [], errors: [] }; },
    async preview() { calls.push("preview"); return { ok: false, code: "off", error: "no" }; },
  };
