  await new Promise((r) => srv.once("listening", r));
  try { return await fn(`http://127.0.0.1:${(srv.address() as AddressInfo).port}`); } finally { srv.close(); }
}

describe("sound render relay", () => {
  it("forwards render + preview, serialises jobs, needs the token", async () => {
    const calls: string[] = [];
    await withRelay(fakeHost(calls), async (url) => {
      const h = relayRenderHost(url, TOKEN);
      const [a, b] = await Promise.all([h.render(JOB), h.render({ ...JOB, sets: [{ name: "x", spec: {} as never }] })]);
      assert.ok(a.ok && b.ok);
      assert.deepEqual(calls.slice(0, 2).sort(), ["render:0", "render:1"]);
      assert.equal((await h.preview!({ v: 1, kind: "preview", library: { id: "a", file: "a.wav", sha256: "0".repeat(64), channels: 1, duration: 1 }, trimStart: 0, length: 1, pitch: 0, fadeIn: 0, fadeOut: 0 })).ok, false);
      const bad = relayRenderHost(url, "x".repeat(32));
      const r = await bad.render(JOB);
      assert.equal(r.ok, false);
      const health = await relayHealth(url, TOKEN); assert.equal(health.ok, true);
    });
  });
  it("refuses a non-loopback URL or a short token; a dead relay is a transport error, not a throw", async () => {
    assert.throws(() => relayRenderHost("http://10.0.0.5:7351", TOKEN), /loopback/);
    assert.throws(() => relayRenderHost("https://127.0.0.1:7351", TOKEN), /loopback/);
    assert.throws(() => relayRenderHost("http://127.0.0.1:7351", "short"), /at least/);
    const r = await relayRenderHost("http://127.0.0.1:1", TOKEN).render(JOB);
    assert.ok(!r.ok && r.code === "transport");
    assert.throws(() => startRenderRelay({ host: fakeHost([]), port: 47999, token: "short" }));
  });
  it("selection: relay mode in the web process; ssh is refused inside Next.js (NEXT_RUNTIME)", () => {
    const relay = selectRenderHost({ CYRUS_SOUND_RENDER: "relay", CYRUS_SOUND_RELAY_URL: "http://127.0.0.1:7351", CYRUS_SOUND_RELAY_TOKEN: TOKEN, NEXT_RUNTIME: "nodejs" });
    assert.ok(relay.ok && relay.host.id.startsWith("relay:"));
    const ssh = selectRenderHost({ CYRUS_SOUND_RENDER: "ssh", NEXT_RUNTIME: "nodejs" });
    assert.ok(!ssh.ok && /never connects/.test(ssh.reason));
    assert.ok(selectRenderHost({ CYRUS_SOUND_RENDER: "ssh" }).ok, "worker / scripts keep ssh");
    assert.ok(!selectRenderHost({ CYRUS_SOUND_RENDER: "relay", CYRUS_SOUND_RELAY_URL: "http://example.com", CYRUS_SOUND_RELAY_TOKEN: TOKEN }).ok);
  });
  it("ssh health probe parses the render host's answer (fake remote)", async () => {
    const ok = await probeSshRenderHost({ remote: { exec: async () => ({ code: 0, stdout: "NX:UP\nNX:FF:ffmpeg version 7.1.1-static\nNX:LIB:514\nNX:WD:ok\n", stderr: "" }) } });
    assert.ok(ok.ok); assert.equal(ok.checks.find((c) => c.id === "library")?.detail, "514 files");
    const down = await probeSshRenderHost({ remote: { exec: async () => ({ code: 255, stdout: "", stderr: "Connection refused" }) } });
    assert.ok(!down.ok); assert.match(down.checks[0].detail, /Connection refused/);
  });
});
