import { spawn } from "node:child_process";
import { readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import type { AddressInfo } from "node:net";
import type { Remote } from "../lib/cyrus/testflight/client";
import { sshRenderHost } from "../lib/cyrus/sound/host";
import { startRenderRelay, relayRenderHost, relayHealth, probeSshRenderHost } from "../lib/cyrus/sound/relay";

const local: Remote = { exec: (command, opts = {}) => new Promise((resolve) => { const c = spawn("bash", ["-c", command], { stdio: ["pipe", "pipe", "pipe"] }); let o = "", e = ""; c.stdout.on("data", (d) => (o += d)); c.stderr.on("data", (d) => (e += d)); const t = setTimeout(() => c.kill("SIGKILL"), opts.timeoutMs ?? 120000); c.on("close", (code) => { clearTimeout(t); resolve({ code, stdout: o, stderr: e }); }); c.stdin.on("error", () => {}); c.stdin.end(opts.input ?? undefined); }) };
const remote = process.argv.includes("--local") ? local : undefined;
const TOKEN = `r12-${Date.now()}-relay-token-xxxxxxxx`;

async function main() {
  const host = sshRenderHost({ remote });
  const srv = startRenderRelay({ host, port: 47610, token: TOKEN, probe: () => probeSshRenderHost({ remote }) });
  await new Promise((r) => srv.once("listening", r));
  const url = `http://127.0.0.1:${(srv.address() as AddressInfo).port}`;
  try {
    const health = await relayHealth(url, TOKEN);
    const spec = JSON.parse(readFileSync(path.join(__dirname, "../services/modbuilder/sound-example.json"), "utf8"));
    const t0 = Date.now();
    const r = await relayRenderHost(url, TOKEN).render({ v: 1, library: [], sets: [{ name: spec.name, spec }], vorbisQuality: 4 });
    const out = {
      what: "Cyrus R5 sound render relay (worker relay -> node-2 render host), real", date: new Date().toISOString(), health,
      render: r.ok ? { ok: true, ms: Date.now() - t0, tool: r.tool, events: r.sets.flatMap((s) => s.events.map((e) => ({ event: e.event, files: e.files.length, bytes: e.files.reduce((a, f) => a + f.bytes, 0), codec: e.files[0]?.encoded.codec, channels: e.files[0]?.encoded.channels }))), errors: r.errors } : r,
    };
    const i = process.argv.indexOf("--out");
    if (i > 0) writeFileSync(process.argv[i + 1], JSON.stringify(out, null, 1));
    console.log(JSON.stringify({ health: health.ok, checks: health.checks, render: (out.render as { ok: boolean }).ok, events: (out.render as { events?: unknown[] }).events?.length }, null, 1));
  } finally { srv.close(); }
}
main().catch((e) => { console.error(e); process.exit(1); });
